#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DesktopStartupMode {
    Normal,
    BackgroundCycle,
    UiSchemaDiagnostic,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct DesktopStartupWorkPlan {
    automatic_work: bool,
    external_access: bool,
    business_state_recovery: bool,
}

impl DesktopStartupMode {
    fn work_plan(self) -> DesktopStartupWorkPlan {
        match self {
            Self::Normal | Self::BackgroundCycle => DesktopStartupWorkPlan {
                automatic_work: true,
                external_access: true,
                business_state_recovery: true,
            },
            Self::UiSchemaDiagnostic => DesktopStartupWorkPlan {
                automatic_work: false,
                external_access: false,
                business_state_recovery: false,
            },
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::Normal => "NORMAL",
            Self::BackgroundCycle => "BACKGROUND_CYCLE",
            Self::UiSchemaDiagnostic => "UI_SCHEMA_DIAGNOSTIC_ACCEPTANCE",
        }
    }
}

impl DesktopStartupWorkPlan {
    fn runs_automatic_work(self) -> bool {
        self.automatic_work
    }
    fn allows_external_access(self) -> bool {
        self.external_access
    }
    fn recovers_business_state(self) -> bool {
        self.business_state_recovery
    }
}

fn desktop_context_for_startup(startup_mode: DesktopStartupMode) -> tauri::Context<tauri::Wry> {
    let mut context = tauri::generate_context!();
    // A scheduled cycle owns business work, never a UI or browser profile.
    // Decide this before Tauri constructs any configured native window.
    if startup_mode == DesktopStartupMode::BackgroundCycle {
        context.config_mut().app.windows.clear();
    }
    context
}

#[cfg(test)]
mod startup_window_contract_tests {
    use super::*;

    #[test]
    fn background_cycle_does_not_construct_native_windows_or_webviews() {
        let context = desktop_context_for_startup(DesktopStartupMode::BackgroundCycle);
        assert!(context.config().app.windows.is_empty(), "background CLI must not construct a WebView and hide it later");
    }

    #[test]
    fn normal_and_diagnostic_keep_their_configured_windows() {
        let expected: tauri::Context<tauri::Wry> = tauri::generate_context!();
        assert!(expected.config().app.windows.iter().any(|window| window.label == "main"));
        let expected = serde_json::to_value(&expected.config().app.windows).unwrap();
        for mode in [DesktopStartupMode::Normal, DesktopStartupMode::UiSchemaDiagnostic] {
            assert_eq!(serde_json::to_value(&desktop_context_for_startup(mode).config().app.windows).unwrap(), expected);
        }
    }
}

fn desktop_startup_mode_from_args<I, S>(args: I) -> Result<DesktopStartupMode, String>
where
    I: IntoIterator<Item = S>,
    S: AsRef<str>,
{
    let mut diagnostic = false;
    let mut background = false;
    for argument in args {
        match argument.as_ref() {
            UI_SCHEMA_DIAGNOSTIC_ARGUMENT => diagnostic = true,
            desktop_background_runtime_v1::BACKGROUND_CYCLE_ARGUMENT => background = true,
            _ => {}
        }
    }
    match (diagnostic, background) {
        (true, true) => {
            Err("UI/schema diagnostic acceptance cannot run as a background cycle".into())
        }
        (true, false) => Ok(DesktopStartupMode::UiSchemaDiagnostic),
        (false, true) => Ok(DesktopStartupMode::BackgroundCycle),
        (false, false) => Ok(DesktopStartupMode::Normal),
    }
}

fn background_cycle_root(startup_mode: DesktopStartupMode) -> Result<Option<PathBuf>, String> {
    if startup_mode != DesktopStartupMode::BackgroundCycle {
        return Ok(None);
    }
    let environment_root = std::env::var_os(desktop_background_runtime_v1::BACKGROUND_APP_ROOT_ENV)
        .map(PathBuf::from);
    let argument_roots = std::env::args_os()
        .filter_map(|argument| argument.into_string().ok())
        .filter_map(|argument| argument.strip_prefix(desktop_background_runtime_v1::BACKGROUND_APP_ROOT_ARGUMENT).map(str::to_owned))
        .collect::<Vec<_>>();
    if argument_roots.len() > 1 {
        return Err("Desktop 后台数据根参数重复".to_owned());
    }
    let argument_root = argument_roots.into_iter().next().map(PathBuf::from);
    if environment_root.is_some() && argument_root.is_some() && environment_root != argument_root {
        return Err("Desktop 后台数据根参数冲突".to_owned());
    }
    environment_root.or(argument_root)
        .map(|root| {
            if !root.is_absolute()
                || root.parent().is_none()
                || root
                    .components()
                    .any(|component| component == std::path::Component::ParentDir)
            {
                return Err("Desktop 后台数据根无效".to_owned());
            }
            Ok(root)
        })
        .transpose()
}

