fn domain_mutation_request_fingerprint(args: &DomainMutationArgs) -> Result<String, String> {
    desktop_intent_request_schema::request_fingerprint(
        "domain",
        &json!({
            "workspaceId": args.workspace_id,
            "entity": args.entity,
            "action": args.action,
            "objectId": args.object_id,
            "expectedRevision": args.expected_revision,
            "fields": args.fields,
        }),
    )
}

fn history_request_fingerprint(args: &HistoryArgs, redo: bool) -> Result<String, String> {
    desktop_intent_request_schema::request_fingerprint(
        "history",
        &json!({"workspaceId": args.workspace_id, "action": if redo { "redo" } else { "undo" }}),
    )
}

fn model_metadata_request_fingerprint(args: &ModelMetadataArgs) -> Result<String, String> {
    desktop_intent_request_schema::request_fingerprint(
        "metadata",
        &json!({
            "workspaceId": args.workspace_id,
            "providerId": args.provider_id,
            "modelId": args.model_id,
            "expectedRevision": args.expected_revision,
            "metadata": args.metadata,
        }),
    )
}

