struct DesktopWorkspaceStore {
    root: PathBuf,
    configuration_database: Option<PathBuf>,
    database: PathBuf,
    credentials: desktop_model_service_v1::AppPrivateProviderCredentialStore,
    /// P7-E can only create its own named, isolated sync workspace.  It is intentionally not
    /// represented by P6's `workspaces` table and has no Tauri command until account/recovery
    /// ownership is explicitly connected in a later authorized phase.
    #[allow(
        dead_code,
        reason = "P7-E remains owner-internal until an authorized account/recovery entrypoint exists"
    )]
    p7e_isolated_store: p7e_isolated_workspace_v1::IsolatedWorkspaceStore,
    /// P8-A opens only a private, local ledger. P8-B may read aggregate status internally, but no
    /// Tauri command, UI, production registry or executor reaches it.
    #[allow(
        dead_code,
        reason = "P8-A is contract-tested only; UI/production tool binding is not authorized"
    )]
    p8_agent_ledger: p8_agent_ledger_v1::AgentLedgerStore,
}

#[derive(Clone)]
struct DesktopStoreReadPaths {
    root: PathBuf,
    database: PathBuf,
}

impl DesktopStoreReadPaths {
    /// Startup shell data is presentation-only. It must not wait for a reminder or chat writer
    /// holding the mutable workspace store mutex.
    fn list_workspaces(&self) -> Result<Vec<WorkspaceSummary>, String> {
        let connection = open_desktop_workspace_readonly_connection(&self.root, &self.database)?;
        DesktopWorkspaceStore::list_workspaces_at(&self.root, &connection)
    }

    fn workspace_projection(&self, workspace_id: &str) -> Result<WorkspaceProjection, String> {
        let connection = open_desktop_workspace_readonly_connection(&self.root, &self.database)?;
        DesktopWorkspaceStore::workspace_projection_at(&self.root, &connection, workspace_id)
    }

    fn cloud_workspace_projections(&self, workspace_ids: &[String]) -> Result<DesktopCloudWorkspaceProjectionBatch, String> {
        if workspace_ids.len() > 10_000 {
            return Err(json_error("云端列表工作区数量超出读取上限"));
        }
        let mut batch = DesktopCloudWorkspaceProjectionBatch { projections: Vec::new(), failed_workspace_ids: Vec::new() };
        if workspace_ids.is_empty() { return Ok(batch); }
        let connection = open_desktop_workspace_readonly_connection(&self.root, &self.database)?;
        // A single read snapshot keeps favorite state and complete projected history coherent,
        // without the mutable store mutex, credentials, transports or a second domain owner.
        let snapshot = connection.unchecked_transaction().map_err(|_| json_error("无法开始云端列表只读快照"))?;
        let mut seen = std::collections::HashSet::new();
        for workspace_id in workspace_ids {
            if !seen.insert(workspace_id) { continue; }
            let projected = DesktopWorkspaceStore::workspace_projection_at(&self.root, &snapshot, workspace_id)
                .and_then(|workspace| desktop_app_settings_v1::read_favorite_conversation_ids(&snapshot, workspace_id)
                    .map(|favorite_ids| DesktopCloudWorkspaceProjection { workspace_id: workspace_id.clone(), workspace, favorite_ids }));
            match projected {
                Ok(projection) => batch.projections.push(projection),
                Err(_) => batch.failed_workspace_ids.push(workspace_id.clone()),
            }
        }
        snapshot.commit().map_err(|_| json_error("无法完成云端列表只读快照"))?;
        Ok(batch)
    }
}

struct DesktopLocalSearchRequest {
    request_id: u64,
    cancellation: Arc<AtomicBool>,
    interrupt: Option<InterruptHandle>,
}

#[derive(Default)]
struct DesktopLocalSearchRequestState {
    active: Option<DesktopLocalSearchRequest>,
}

impl DesktopLocalSearchRequestState {
    fn begin(&mut self, request_id: u64) -> Result<Arc<AtomicBool>, String> {
        if request_id == 0 {
            return Err(json_error("本机搜索请求无效"));
        }
        if let Some(active) = self.active.as_ref() {
            if active.request_id >= request_id {
                return Err(json_error("本机搜索已取消"));
            }
        }
        if let Some(active) = self.active.take() {
            active.cancellation.store(true, Ordering::SeqCst);
            if let Some(interrupt) = active.interrupt.as_ref() {
                interrupt.interrupt();
            }
        }
        let cancellation = Arc::new(AtomicBool::new(false));
        self.active = Some(DesktopLocalSearchRequest {
            request_id,
            cancellation: Arc::clone(&cancellation),
            interrupt: None,
        });
        Ok(cancellation)
    }

    fn register_interrupt(
        &mut self,
        request_id: u64,
        cancellation: &Arc<AtomicBool>,
        interrupt: InterruptHandle,
    ) {
        if let Some(active) = self.active.as_mut().filter(|active| {
            active.request_id == request_id && Arc::ptr_eq(&active.cancellation, cancellation)
        }) {
            active.interrupt = Some(interrupt);
        } else {
            interrupt.interrupt();
        }
    }

    fn cancel_through(&mut self, request_id: u64) {
        if self
            .active
            .as_ref()
            .is_some_and(|active| active.request_id <= request_id)
        {
            if let Some(active) = self.active.take() {
                active.cancellation.store(true, Ordering::SeqCst);
                if let Some(interrupt) = active.interrupt.as_ref() {
                    interrupt.interrupt();
                }
            }
        }
    }

    fn finish(&mut self, request_id: u64, cancellation: &Arc<AtomicBool>) {
        if self.active.as_ref().is_some_and(|active| {
            active.request_id == request_id && Arc::ptr_eq(&active.cancellation, cancellation)
        }) {
            self.active = None;
        }
    }
}

struct AppState {
    _process_lock: fs::File,
    store: Mutex<DesktopWorkspaceStore>,
    /// Immutable for the lifetime of a running app. Read-only previews and
    /// search must not wait behind a writer that temporarily owns `store`.
    store_paths: DesktopStoreReadPaths,
    storage_location_config: Option<PathBuf>,
    local_search_requests: Mutex<DesktopLocalSearchRequestState>,
    pdf_requests: Mutex<desktop_preview_requests::Requests>,
    archive_preview_requests: Mutex<desktop_preview_requests::Requests>,
    video_thumbnail_requests: Arc<Mutex<desktop_preview_requests::ConcurrentRequests>>,
    video_thumbnail_slots: Arc<tokio::sync::Semaphore>,
    credentials: desktop_model_service_v1::AppPrivateProviderCredentialStore,
    ordinary_chat_cancellations: Arc<Mutex<BTreeMap<String, Vec<Arc<AtomicBool>>>>>,
    blocking_business_executions: Arc<Mutex<usize>>,
    web_jobs: Arc<desktop_web_jobs_v1::Jobs>,
    ordinary_chat_mock_endpoint: Option<String>,
    windows_model_service_test_endpoint: Option<String>,
    windows_ocr_test_endpoint: Option<String>,
    ordinary_chat_acceptance_enabled: bool,
    history_knowledge_cancellations: Arc<Mutex<BTreeMap<String, Arc<AtomicBool>>>>,
    reminder_cancellations: Arc<Mutex<BTreeMap<String, Arc<AtomicBool>>>>,
    p6e_acceptance_enabled: bool,
    p6h_acceptance_enabled: bool,
    account_sync_mock_enabled: bool,
    /// Shared across CHAT/WORK so a late browser callback cannot undo sign-out
    /// or replace a newer login while authorization runs off the UI thread.
    account_auth_generation: Arc<Mutex<u64>>,
    c16_visual_acceptance_state: Option<String>,
    startup_mode: DesktopStartupMode,
    account_root: PathBuf,
    work_area: Option<Arc<AppState>>,
}

impl AppState {
    fn attach_work_store(&mut self, work_store: DesktopWorkspaceStore) -> Result<(), String> {
        if self.work_area.is_some() {
            return Err(json_error("WORK 状态已存在，未重复接入"));
        }
        let work_paths = DesktopStoreReadPaths {
            root: work_store.root.clone(),
            database: work_store.database.clone(),
        };
        self.work_area = Some(Arc::new(Self {
            _process_lock: self
                ._process_lock
                .try_clone()
                .map_err(|_| json_error("WORK 进程锁句柄不可复制"))?,
            store: Mutex::new(work_store),
            store_paths: work_paths,
            storage_location_config: self.storage_location_config.clone(),
            local_search_requests: Mutex::new(DesktopLocalSearchRequestState::default()),
            pdf_requests: Mutex::new(desktop_preview_requests::Requests::default()),
            archive_preview_requests: Mutex::new(desktop_preview_requests::Requests::default()),
            video_thumbnail_requests: Arc::new(Mutex::new(
                desktop_preview_requests::ConcurrentRequests::default(),
            )),
            video_thumbnail_slots: Arc::new(tokio::sync::Semaphore::new(2)),
            credentials: self.credentials.clone(),
            ordinary_chat_cancellations: Arc::new(Mutex::new(BTreeMap::new())),
            blocking_business_executions: self.blocking_business_executions.clone(),
            web_jobs: Arc::new(desktop_web_jobs_v1::Jobs::default()),
            ordinary_chat_mock_endpoint: self.ordinary_chat_mock_endpoint.clone(),
            windows_model_service_test_endpoint: self.windows_model_service_test_endpoint.clone(),
            windows_ocr_test_endpoint: self.windows_ocr_test_endpoint.clone(),
            ordinary_chat_acceptance_enabled: self.ordinary_chat_acceptance_enabled,
            history_knowledge_cancellations: Arc::new(Mutex::new(BTreeMap::new())),
            reminder_cancellations: Arc::new(Mutex::new(BTreeMap::new())),
            p6e_acceptance_enabled: self.p6e_acceptance_enabled,
            p6h_acceptance_enabled: self.p6h_acceptance_enabled,
            account_sync_mock_enabled: self.account_sync_mock_enabled,
            account_auth_generation: self.account_auth_generation.clone(),
            c16_visual_acceptance_state: self.c16_visual_acceptance_state.clone(),
            startup_mode: self.startup_mode,
            account_root: self.account_root.clone(),
            work_area: None,
        }));
        Ok(())
    }

    fn require_external_access(&self) -> Result<(), String> {
        if self.startup_mode.work_plan().allows_external_access() {
            Ok(())
        } else {
            Err(json_error(
                "UI/schema diagnostic acceptance 已抑制凭据、网络与外部进程",
            ))
        }
    }
}

