        let parent = target
            .parent()
            .ok_or_else(|| json_error("知识库私有副本路径无效"))?;
        fs::create_dir_all(parent).map_err(|_| json_error("无法创建知识库私有副本"))?;
        let temporary = parent.join(format!(".{package_hash}.part"));
        fs::write(&temporary, &bytes).map_err(|_| json_error("无法写入知识库私有副本"))?;
