#[tauri::command]
fn choose_desktop_storage_location(
    app: AreaAppHandle,
    selected_path: String,
) -> Result<(), String> {
    // The location setting owns the entire application root, including CHAT, WORK and
    // shared configuration. A request issued while WORK is visible must not select its
    // child database as the next application root.
    let root = app.root_state();
    let store = root.store.lock().map_err(|_| "数据目录繁忙")?;
    let config = if let Some(config) = &root.storage_location_config {
        config.clone()
    } else {
        app.path()
            .app_config_dir()
            .map_err(|_| "配置目录不可用")?
            .join("storage-location.json")
    };
    desktop_storage_location::schedule(&config, &store.root, Path::new(&selected_path))
}

#[tauri::command]
fn import_desktop_ocr_drop(
    state: AreaState<'_>,
    args: DesktopClipboardAttachmentImportArgs,
) -> Result<desktop_transcription_v1::TaskProjection, String> {
    use base64::Engine as _;
    let store = state
        .store
        .lock()
        .map_err(|_| json_error("Desktop store 被锁定"))?;
    let name = std::path::Path::new(&args.display_name)
        .file_name()
        .and_then(|s| s.to_str())
        .ok_or("文件名无效")?;
    if args.bytes_base64.len() > 140_000_000 {
        return Err("文件过大".into());
    }
    let bytes = base64::engine::general_purpose::STANDARD
        .decode(&args.bytes_base64)
        .map_err(|_| "文件内容无效")?;
    let staging = store.root.join(format!(
        "ocr-drop-{}",
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map_err(|_| "时间不可用")?
            .as_nanos()
    ));
    std::fs::create_dir(&staging).map_err(|_| "无法准备文件")?;
    let path = staging.join(name);
    let result = (|| {
        std::fs::write(&path, bytes).map_err(|_| "无法读取拖入文件")?;
        desktop_transcription_v1::import_document_source(
            &store.root,
            &store.database,
            desktop_transcription_v1::ImportArgs {
                workspace_id: args.workspace_id,
                selected_path: path.to_string_lossy().into_owned(),
            },
        )
    })();
    let _ = std::fs::remove_dir_all(&staging);
    result
}

