#[tauri::command]
async fn run_desktop_ocr_task(
    state: AreaState<'_>,
    task_id: String,
) -> Result<desktop_transcription_v1::TaskProjection, String> {
    state.require_external_access()?;
    let execution = BlockingBusinessExecution::begin(&state.blocking_business_executions)?;
    let (root, database) = {
        let store = state
            .store
            .lock()
            .map_err(|_| json_error("Desktop store 被锁定"))?;
        (store.root.clone(), store.database.clone())
    };
    let test_endpoint = state.windows_ocr_test_endpoint.clone();
    let api_key = if test_endpoint.is_some() {
        Ok(b"nfai-synthetic-windows-ocr".to_vec())
    } else {
        resolve_ocr_api_key_for_run(state.ordinary_chat_acceptance_enabled, || {
            state
                .credentials
                .with_secret("ZHIPU", |bytes| Ok(bytes.to_vec()))
        })
    }
    .map_err(|error| {
        let _ = desktop_transcription_v1::run_ocr_task(&root, &database, &task_id, &[]);
        error
    })?;
    tauri::async_runtime::spawn_blocking(move || {
        let _execution = execution;
        if let Some(endpoint) = test_endpoint {
            desktop_transcription_v1::run_ocr_task_at(
                &root,
                &database,
                &task_id,
                &api_key,
                &format!("{endpoint}/api/paas/v4/layout_parsing"),
            )
        } else {
            desktop_transcription_v1::run_ocr_task(&root, &database, &task_id, &api_key)
        }
    })
    .await
    .map_err(|_| json_error("GLM-OCR 执行线程异常"))?
}

