#[tauri::command]
fn save_desktop_model_service_settings(
    state: AreaState<'_>,
    mut args: DesktopModelServiceSaveArgs,
) -> Result<DesktopModelServiceSettingProjection, String> {
    state.require_external_access()?;
    desktop_model_service_v1::validate_configuration(&args.provider_id, &args.preset_id)?;
    let _write = MODEL_SERVICE_SETTINGS_WRITE_LOCK
        .lock()
        .map_err(|_| json_error("模型设置保存繁忙，请重试"))?;
    let current = state
        .store
        .lock()
        .map_err(|_| json_error("Desktop store 被锁定"))?
        .read_desktop_model_service_setting_records()?
        .into_iter()
        .find(|record| record.provider_id == args.provider_id)
        .ok_or_else(|| json_error("模型服务商无效"))?;
    if current.revision != args.expected_revision {
        return Err(json_error("模型服务设置已在其他窗口更新；请刷新后重试"));
    }

    if args.preserve_enabled { args.enabled = current.enabled; }
    if args.preserve_preset { args.preset_id = current.preset_id.clone(); }
    args.preset_id = canonical_desktop_model_choice(&args.preset_id).to_owned();

    let credential_store = &state.credentials;
    let mut credential_staged = false;
    if let Some(api_key) = args.api_key {
        let api_key = Zeroizing::new(api_key);
        let trimmed = api_key.trim();
        if !trimmed.is_empty() {
            let before = model_setting_state(&current);
            let after = desktop_model_service_v1::ModelSettingState {
                provider_id: args.provider_id.clone(),
                enabled: args.enabled,
                preset_id: args.preset_id.clone(),
                revision: args
                    .expected_revision
                    .checked_add(1)
                    .ok_or_else(|| json_error("模型服务设置 revision 溢出"))?,
            };
            if let Err(error) = credential_store.begin_model_setting_secret_update(
                before,
                after,
                trimmed.as_bytes(),
            ) {
                let store = state
                    .store
                    .lock()
                    .map_err(|_| json_error("模型凭据更新待恢复；请重开应用"))?;
                reconcile_pending_model_setting(&store, credential_store)
                    .map_err(|_| json_error("模型凭据更新待恢复；请重开应用"))?;
                return Err(error);
            }
            credential_staged = true;
            pause_windows_model_pending_acceptance(&state.account_root, "before-sqlite")?;
        }
    }
    let committed = (|| {
        state
            .store
            .lock()
            .map_err(|_| json_error("Desktop store 被锁定"))?
            .save_desktop_model_service_setting_record(
                &args.provider_id,
                args.enabled,
                &args.preset_id,
                args.expected_revision,
            )
    })();
    let record = if credential_staged {
        if committed.is_ok() {
            pause_windows_model_pending_acceptance(&state.account_root, "after-sqlite")?;
        }
        let observed = {
            let store = state
                .store
                .lock()
                .map_err(|_| json_error("模型凭据更新待恢复；请重开应用"))?;
            reconcile_pending_model_setting(&store, credential_store)
                .map_err(|_| json_error("模型凭据更新待恢复；请重开应用"))?
        };
        match observed {
            Some((record, desktop_model_service_v1::ModelSettingResolution::CommittedNew)) => {
                record
            }
            Some((_, desktop_model_service_v1::ModelSettingResolution::RestoredPrevious)) => {
                return Err(committed
                    .err()
                    .unwrap_or_else(|| json_error("模型设置未持久化；原有 API Key 已恢复")));
            }
            None => return Err(json_error("模型凭据待决记录缺失；请重开应用后核对")),
        }
    } else {
        committed?
    };
    desktop_model_service_projection(record, credential_store)
}

#[cfg(all(windows, debug_assertions))]
fn pause_windows_model_pending_acceptance(root: &Path, phase: &str) -> Result<(), String> {
    if std::env::var("NANFENG_AI_WINDOWS_MODEL_PENDING_PAUSE").ok().as_deref() != Some(phase) {
        return Ok(());
    }
    let verified = desktop_windows_acceptance::resolve(
        Some(root),
        true,
        desktop_windows_acceptance::IDENTIFIER,
        &std::env::temp_dir(),
    )?
    .ok_or_else(|| "模型待决验收根缺失".to_owned())?;
    if verified != root {
        return Err("模型待决验收根不一致".to_owned());
    }
    fs::write(root.join(format!("model-pending-{phase}.reached")), b"reached")
        .map_err(|_| "模型待决验收标记无法写入".to_owned())?;
    loop {
        std::thread::park_timeout(std::time::Duration::from_secs(1));
    }
}

#[cfg(not(all(windows, debug_assertions)))]
fn pause_windows_model_pending_acceptance(_root: &Path, _phase: &str) -> Result<(), String> {
    Ok(())
}

#[cfg(all(windows, debug_assertions))]
fn pause_windows_draft_read_acceptance(root: &Path) -> Result<(), String> {
    if std::env::var("NANFENG_AI_WINDOWS_DRAFT_READ_PAUSE").ok().as_deref() != Some("CHAT_UNBOUND") {
        return Ok(());
    }
    let arm = root.join("draft-read-pause.arm");
    let metadata = match fs::symlink_metadata(&arm) {
        Ok(metadata) => metadata,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(()),
        Err(_) => return Err("草稿读取验收布防标记不可读".to_owned()),
    };
    let verified = desktop_windows_acceptance::resolve(
        Some(root), true, desktop_windows_acceptance::IDENTIFIER, &std::env::temp_dir(),
    )?.ok_or_else(|| "草稿读取验收根缺失".to_owned())?;
    if verified != root {
        return Err("草稿读取验收根不一致".to_owned());
    }
    if !metadata.file_type().is_file() || metadata.len() != 0 {
        return Err("草稿读取验收布防标记无效".to_owned());
    }
    fs::remove_file(&arm).map_err(|_| "草稿读取验收布防标记无法消费".to_owned())?;
    let reached = root.join("draft-read-pause.reached");
    let resume = root.join("draft-read-pause.continue");
    if fs::symlink_metadata(&resume).is_ok() {
        return Err("草稿读取验收继续标记已存在".to_owned());
    }
    let marker = fs::OpenOptions::new().write(true).create_new(true).open(&reached)
        .map_err(|_| "草稿读取验收停点标记无法创建".to_owned())?;
    marker.sync_all().map_err(|_| "草稿读取验收停点标记无法持久化".to_owned())?;
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(60);
    loop {
        match fs::symlink_metadata(&resume) {
            Ok(metadata) if metadata.file_type().is_file() && metadata.len() == 0 => return Ok(()),
            Ok(_) => return Err("草稿读取验收继续标记无效".to_owned()),
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {},
            Err(_) => return Err("草稿读取验收继续标记不可读".to_owned()),
        }
        if std::time::Instant::now() >= deadline {
            return Err("草稿读取验收停点等待超时".to_owned());
        }
        std::thread::sleep(std::time::Duration::from_millis(100));
    }
}

