#[cfg(all(windows, debug_assertions))]
fn windows_ordinary_chat_credential_pause_requested() -> bool {
    std::env::var("NANFENG_AI_WINDOWS_ORDINARY_CHAT_CREDENTIAL_PAUSE")
        .ok()
        .as_deref()
        == Some("before-credential")
}

#[cfg(not(all(windows, debug_assertions)))]
fn windows_ordinary_chat_credential_pause_requested() -> bool {
    false
}

#[cfg(all(windows, debug_assertions))]
fn pause_windows_ordinary_chat_credential_acceptance(root: &Path, has_loopback_endpoint: bool) -> Result<(), String> {
    if !windows_ordinary_chat_credential_pause_requested() {
        return Ok(());
    }
    if !has_loopback_endpoint {
        return Err(json_error("普通聊天凭据验收缺少回环端点；未向服务商建立连接"));
    }
    let verified = desktop_windows_acceptance::resolve(
        Some(root),
        true,
        desktop_windows_acceptance::IDENTIFIER,
        &std::env::temp_dir(),
    )?
    .ok_or_else(|| "普通聊天凭据验收根缺失".to_owned())?;
    if verified != root {
        return Err("普通聊天凭据验收根不一致".to_owned());
    }
    let reached = root.join("ordinary-chat-before-credential.reached");
    let resume = root.join("ordinary-chat-before-credential.resume");
    fs::write(&reached, b"reached")
        .map_err(|_| "普通聊天凭据验收标记无法写入".to_owned())?;
    for _ in 0..300 {
        if resume.is_file() {
            fs::remove_file(&resume)
                .map_err(|_| "普通聊天凭据验收放行标记无法清理".to_owned())?;
            return Ok(());
        }
        std::thread::sleep(std::time::Duration::from_millis(100));
    }
    Err(json_error("普通聊天凭据验收停点超时；未向服务商建立连接"))
}

#[cfg(not(all(windows, debug_assertions)))]
fn pause_windows_ordinary_chat_credential_acceptance(_root: &Path, _has_loopback_endpoint: bool) -> Result<(), String> {
    Ok(())
}

fn reconcile_pending_model_setting(
    store: &DesktopWorkspaceStore,
    credentials: &desktop_model_service_v1::AppPrivateProviderCredentialStore,
) -> Result<
    Option<(
        DesktopModelServiceSettingRecord,
        desktop_model_service_v1::ModelSettingResolution,
    )>,
    String,
> {
    let Some((before, _after)) = credentials.pending_model_setting_states()? else {
        return Ok(None);
    };
    let observed = store.read_desktop_model_service_setting_record_raw(&before.provider_id)?;
    let resolution = credentials
        .settle_model_setting_secret_update(&model_setting_state(&observed))?
        .ok_or_else(|| json_error("模型凭据待决记录缺失；请重开应用后核对"))?;
    Ok(Some((observed, resolution)))
}

#[tauri::command]
fn delete_desktop_model_service_credential(
    state: AreaState<'_>,
    provider_id: String,
) -> Result<DesktopModelServiceSettingProjection, String> {
    state.require_external_access()?;
    desktop_model_service_v1::validate_provider(&provider_id)?;
    let _write = MODEL_SERVICE_SETTINGS_WRITE_LOCK
        .lock()
        .map_err(|_| json_error("模型设置保存繁忙，请重试"))?;
    state.credentials.delete_user_secret(&provider_id)?;
    let record = state
        .store
        .lock()
        .map_err(|_| json_error("Desktop store 被锁定"))?
        .read_desktop_model_service_setting_records()?
        .into_iter()
        .find(|record| record.provider_id == provider_id)
        .ok_or_else(|| json_error("模型服务商无效"))?;
    desktop_model_service_projection(record, &state.credentials)
}

/// Credential plaintext crosses IPC only after the user explicitly presses the reveal control.
#[tauri::command]
fn reveal_desktop_model_service_credential(
    _app: AreaAppHandle,
    provider_id: String,
    state: AreaState<'_>,
) -> Result<String, String> {
    state.require_external_access()?;
    let secret = read_user_authorized_provider_secret(&state.credentials, &provider_id)?;
    String::from_utf8(secret.to_vec())
        .map_err(|_| json_error("本机 API Key 格式无效；请重新保存。"))
}

/// The app-private credential owner never reaches macOS Keychain or exposes a system prompt.
fn read_user_authorized_provider_secret(
    credential_store: &desktop_model_service_v1::AppPrivateProviderCredentialStore,
    provider_id: &str,
) -> Result<Zeroizing<Vec<u8>>, String> {
    credential_store.with_secret(provider_id, |bytes| Ok(Zeroizing::new(bytes.to_vec())))
}

fn read_ordinary_chat_bound_secret(
    credential_store: &desktop_model_service_v1::AppPrivateProviderCredentialStore,
    provider_id: &str,
    expected_revision: Option<u64>,
    read_setting: impl FnOnce(&str) -> Result<DesktopModelServiceSettingRecord, String>,
) -> Result<Zeroizing<Vec<u8>>, String> {
    let _write = MODEL_SERVICE_SETTINGS_WRITE_LOCK
        .lock()
        .map_err(|_| json_error("模型设置保存繁忙；本次请求未外发"))?;
    let expected_revision = expected_revision
        .ok_or_else(|| json_error("模型设置在本次请求准备后已变更；未外发"))?;
    let current = read_setting(provider_id)?;
    if !current.enabled || current.revision != expected_revision {
        return Err(json_error("模型设置在本次请求准备后已变更；未外发"));
    }
    read_user_authorized_provider_secret(credential_store, provider_id)
}

fn ordinary_chat_credential_failure_code(error: &str) -> &'static str {
    if error.contains("模型设置在本次请求准备后已变更") {
        "MODEL_SETTINGS_CHANGED"
    } else if error.contains("尚未保存") {
        "CREDENTIAL_MISSING"
    } else {
        "CREDENTIAL_UNAVAILABLE"
    }
}

#[cfg(test)]
mod user_authorized_credential_read_tests {
    use super::ordinary_chat_credential_failure_code;

    #[test]
    fn app_private_credential_failures_keep_the_precise_retry_state() {
        assert_eq!(
            ordinary_chat_credential_failure_code("应用私有凭据无法解密；请重新保存 API Key。"),
            "CREDENTIAL_UNAVAILABLE"
        );
    }
}

/// Connection testing is user-triggered and can reach only the fixed endpoint/model registry.
#[tauri::command]
async fn test_desktop_model_service_connection(
    _app: AreaAppHandle,
    args: DesktopModelServiceConnectionTestArgs,
    state: AreaState<'_>,
) -> Result<DesktopModelServiceConnectionTestProjection, String> {
    let _execution = BlockingBusinessExecution::begin(&state.blocking_business_executions)?;
    state.require_external_access()?;
    let preset = desktop_model_service_v1::connection_test_preset(&args.provider_id, &args.preset_id)?;
    if !state.store.lock().map_err(|_| json_error("Desktop store 被锁定"))?
        .openrouter_preset_available(&preset) {
        return Err(json_error("模型已不在已核验服务商目录；未读取凭据或发起连接测试"));
    }
    let secret = read_user_authorized_provider_secret(&state.credentials, &args.provider_id)?;
    desktop_model_service_v1::test_saved_connection(
        &args.provider_id,
        &args.preset_id,
        secret,
        state.windows_model_service_test_endpoint.as_deref(),
    )
    .await?;
    Ok(DesktopModelServiceConnectionTestProjection {
        provider_id: args.provider_id,
        preset_id: args.preset_id,
        succeeded: true,
        message: "连接测试通过。".to_owned(),
        tested_at_ms: local_now_millis(),
    })
}

// Read-only attachment of request facts to the exact immutable quantitative fact.
// A retry may reuse a legacy attempt row; its new answer/time cannot relabel old charges.
fn ocr_usage_details(connection: &Connection, entry: &usage_ledger_v1::Entry) -> Result<Option<DesktopOcrUsageDetails>,String> {
    if entry.source != usage_ledger_v1::Source::DesktopLocal || !entry.replay_token.starts_with("ocr-final-") { return Ok(None); }
    connection.query_row("SELECT provider_id,attempt_id,attempt_number,source_display_name,page_count,provider_request_id FROM desktop_ocr_attempts_v1 WHERE attempt_id=?1 AND task_id=?2 AND task_id=?3 AND requested_model_id=?4",
        params![entry.attempt_id,entry.conversation_id,entry.branch_leaf_message_id,entry.requested_model_id],
        |row|Ok(DesktopOcrUsageDetails {provider_id:row.get(0)?,attempt_id:row.get(1)?,attempt_number:row.get(2)?,source_display_name:row.get(3)?,page_count:row.get(4)?,provider_request_id:row.get(5)?}),
    ).optional().map_err(|_|json_error("无法读取 OCR 调用详情"))
}

fn usage_attempt_outcome(connection: &Connection, entry: &usage_ledger_v1::Entry)
    -> Result<(Option<String>, Option<String>, Option<i64>), String> {
    if entry.source != usage_ledger_v1::Source::DesktopLocal {
        return Ok((None, None, None));
    }
    if entry.replay_token.starts_with("ocr-final-") {
        let fact = connection.query_row("SELECT state,safe_error_code,created_at_ms,terminal_at_ms FROM desktop_ocr_attempts_v1 WHERE attempt_id=?1 AND task_id=?2 AND task_id=?3 AND requested_model_id=?4",
            params![entry.attempt_id,entry.conversation_id,entry.branch_leaf_message_id,entry.requested_model_id],
            |row|Ok((row.get::<_,String>(0)?,row.get::<_,Option<String>>(1)?,row.get::<_,i64>(2)?,row.get::<_,Option<i64>>(3)?)),
        ).optional().map_err(|_|json_error("无法读取 OCR 逐次状态"))?;
        if let Some((state,code,created,terminal)) = fact {
            let elapsed = if state=="COMPLETED" && created>0 { terminal.and_then(|end|end.checked_sub(created)).filter(|value|*value>=0) } else { None };
            return Ok((Some(state),code,elapsed));
        }
    }
    let auxiliary_fact = if entry.replay_token.starts_with("history-knowledge-final-") {
        let receipt=desktop_history_knowledge_v1::accounting_receipt(connection,&entry.attempt_id)?;
        if let Some(receipt)=receipt {
            if *entry==DesktopWorkspaceStore::history_accounting_entry(&receipt) {
                Some((receipt.terminal_state,receipt.safe_error_code))
            } else {None}
        } else {connection.query_row(
            "SELECT status,safe_error_code FROM desktop_history_knowledge_candidates_v1 WHERE attempt_id=?1 AND candidate_id=?2 AND conversation_id=?3 AND requested_model_id=?4 AND input_tokens IS ?5 AND output_tokens IS ?6 AND charge_micros IS ?7",
            params![entry.attempt_id,entry.execution_id,entry.conversation_id,entry.requested_model_id,entry.input_tokens,entry.output_tokens,entry.charge_micros],
            |row|Ok((row.get::<_,String>(0)?,row.get::<_,Option<String>>(1)?)),
        ).optional().map_err(|_|json_error("无法读取历史整理调用状态"))?}
    } else if entry.replay_token.starts_with("reminder-final-") {
        let run = connection.query_row(
            "SELECT run.status,run.safe_error_code FROM desktop_reminder_runs_v1 run JOIN desktop_reminder_plans_v1 plan ON plan.plan_id=run.plan_id WHERE run.attempt_id=?1 AND run.plan_id=?2 AND COALESCE(plan.conversation_id,'reminder-local')=?3 AND run.requested_model_id=?4 AND run.input_tokens IS ?5 AND run.output_tokens IS ?6 AND run.charge_micros IS ?7",
            params![entry.attempt_id,entry.execution_id,entry.conversation_id,entry.requested_model_id,entry.input_tokens,entry.output_tokens,entry.charge_micros],
            |row|Ok((row.get::<_,String>(0)?,row.get::<_,Option<String>>(1)?)),
        ).optional().map_err(|_|json_error("无法读取定时监控调用状态"))?;
        match run {
            Some(fact) => Some(fact),
            None => connection.query_row(
                "SELECT status,safe_error_code FROM desktop_reminder_drafts_v1 WHERE attempt_id=?1 AND draft_id=?2 AND COALESCE(conversation_id,'reminder-local')=?3 AND requested_model_id=?4 AND input_tokens IS ?5 AND output_tokens IS ?6 AND charge_micros IS ?7",
                params![entry.attempt_id,entry.execution_id,entry.conversation_id,entry.requested_model_id,entry.input_tokens,entry.output_tokens,entry.charge_micros],
                |row|Ok((row.get::<_,String>(0)?,row.get::<_,Option<String>>(1)?)),
            ).optional().map_err(|_|json_error("无法读取提醒草案调用状态"))?,
        }
    } else if entry.replay_token.starts_with("ocr-final-") {
        connection.query_row(
            "SELECT state,error_code FROM desktop_transcription_tasks WHERE id=?1 AND id=?2 AND 'transcription-'||id||'-'||attempt_count=?3 AND model_id=?4 AND input_tokens IS ?5 AND output_tokens IS ?6 AND estimated_charge_micros IS ?7",
            params![entry.conversation_id,entry.branch_leaf_message_id,entry.attempt_id,entry.requested_model_id,entry.input_tokens,entry.output_tokens,entry.charge_micros],
            |row|Ok((row.get::<_,String>(0)?,row.get::<_,Option<String>>(1)?)),
        ).optional().map_err(|_|json_error("无法读取转写调用状态"))?
    } else { None };
    if entry.replay_token.starts_with("history-knowledge-final-") || entry.replay_token.starts_with("reminder-final-") || entry.replay_token.starts_with("ocr-final-") {
        return Ok(auxiliary_fact.map(|(state,code)|match state.as_str() {
            "COMPLETED"|"SUCCEEDED"|"PENDING_REVIEW"|"ACCEPTING"|"ACCEPTED"|"REJECTED"|"CONFIRMED"|"NOT_ELIGIBLE" => (Some("COMPLETED".into()),None,None),
            "RECOVERY_REQUIRED" => (Some("UNKNOWN".into()),code,None),
            "FAILED"|"UNKNOWN"|"CANCELLED" => (Some(state),code,None),
            _ => (None,None,None),
        }).unwrap_or((None,None,None)));
    }
    if entry.entry_id.starts_with("usage-title-") {
        let fact = connection.query_row(
            "SELECT state,safe_error_code FROM desktop_conversation_title_attempts WHERE attempt_id=?1 AND conversation_id=?2 AND assistant_message_id=?3 AND occurred_at_ms=?4",
            params![entry.attempt_id,entry.conversation_id,entry.branch_leaf_message_id,entry.occurred_at_ms],
            |row| Ok((row.get::<_,String>(0)?,row.get::<_,Option<String>>(1)?)),
        ).optional().map_err(|_|json_error("无法读取标题调用状态"))?;
        return Ok(fact.map(|(state,code)|(Some(state),code,None)).unwrap_or((None,None,None)));
    }
    let fact = connection.query_row(
        "SELECT state,safe_error_code,created_at_ms,terminal_at_ms FROM desktop_ordinary_chat_attempts WHERE attempt_id=?1 AND conversation_id=?2 AND assistant_message_id=?3 AND COALESCE(terminal_at_ms,created_at_ms)=?4",
        params![entry.attempt_id,entry.conversation_id,entry.branch_leaf_message_id,entry.occurred_at_ms],
        |row| Ok((row.get::<_,String>(0)?,row.get::<_,Option<String>>(1)?,row.get::<_,i64>(2)?,row.get::<_,Option<i64>>(3)?)),
    ).optional().map_err(|_|json_error("无法读取普通调用状态"))?;
    Ok(fact.map(|(state,code,created,terminal)|{
        let elapsed = if matches!(state.as_str(),"COMPLETED"|"COMPLETED_ACCOUNTING_PENDING"|"RESPONSE_COMMITTED") && created>0 {
            terminal.and_then(|end|end.checked_sub(created)).filter(|value|*value>=0)
        } else { None };
        (Some(state),code,elapsed)
    }).unwrap_or((None,None,None)))
}

#[tauri::command]
async fn read_desktop_usage_ledger(
    app: AreaAppHandle,
) -> Result<DesktopUsageLedgerProjection, String> {
    let execution = BlockingBusinessExecution::begin(&app.root_state().blocking_business_executions)?;
    let (root, database, ordinary_chat_fallbacks) = {
        let state = app.area_state()?;
        let store = state
            .store
            .lock()
            .map_err(|_| json_error("Desktop store 被锁定"))?;
        let ordinary_chat_fallbacks = ordinary_chat_usage_fallbacks(&store)?;
        (store.root.join("usage-ledger"), store.database.clone(), ordinary_chat_fallbacks)
    };
    tauri::async_runtime::spawn_blocking(move || {
        let _execution = execution;
        let tasks = desktop_transcription_v1::read_state(&database, None)?.tasks;
        let ledger = usage_ledger_v1::Ledger::open(&root)?;
        for task in tasks.into_iter().filter(|task| task.model_id == "glm-ocr" && task.state == "COMPLETED") {
            let fact_id = format!("transcription-{}-{}", task.id, task.attempt_count);
            if ledger.by_id(&format!("usage-{fact_id}"))?.is_some() {
                // Current OCR writes this quantitative fact when the provider response
                // arrives. Only older completed tasks still need startup backfill.
                continue;
            }
            let input_tokens = task.input_tokens.map(i64::try_from).transpose().map_err(|_| json_error("GLM-OCR 输入 Token 超出账本范围"))?;
            let output_tokens = task.output_tokens.map(i64::try_from).transpose().map_err(|_| json_error("GLM-OCR 输出 Token 超出账本范围"))?;
            let charge_micros = i64::try_from(task.estimated_charge_micros).map_err(|_| json_error("GLM-OCR 费用超出账本范围"))?;
            let entry = usage_ledger_v1::Entry {
                entry_id: format!("usage-{fact_id}"),
                replay_token: format!("ocr-final-{fact_id}"),
                execution_id: fact_id.clone(),
                conversation_id: task.id.clone(),
                branch_leaf_message_id: task.id.clone(),
                invocation_id: fact_id.clone(),
                attempt_id: fact_id,
                kind: usage_ledger_v1::Kind::FinalMeasured,
                fact_grade: usage_ledger_v1::FactGrade::ProviderReported,
                requested_model_id: task.model_id.clone(),
                actual_model_id: Some(task.model_id),
                input_tokens,
                output_tokens,
                cached_input_tokens: None,
                charge_micros: Some(charge_micros),
                budget_micros: None,
                adjustment_micros: None,
                currency_code: Some("CNY".into()),
                cost_source: Some("LOCAL_ESTIMATE".into()),
                reconciliation_fingerprint: None,
                reconciles_entry_id: None,
                source: usage_ledger_v1::Source::DesktopLocal,
                occurred_at_ms: task.updated_at_millis,
            };
            if matches!(ledger.append(&entry)?, usage_ledger_v1::AppendResult::Conflict) {
                return Err(json_error("GLM-OCR 用量账本幂等冲突"));
            }
        }
        if !root.join("usage-ledger-v1.sqlite3").is_file() {
            return Ok(DesktopUsageLedgerProjection {
                records: Vec::new(),
                input_tokens: 0,
                output_tokens: 0,
                cached_input_tokens: 0,
            });
        }
        let entries = ledger.display_entries()?;
        let request_connection = Connection::open_with_flags(&database, OpenFlags::SQLITE_OPEN_READ_ONLY)
            .map_err(|_|json_error("调用状态数据库不可读"))?;
        let records = entries
            .into_iter()
            .map(|entry| {
                let provider_usage_missing = entry.input_tokens.is_none()
                    && entry.output_tokens.is_none() && entry.cached_input_tokens.is_none();
                let fallback = (entry.kind == usage_ledger_v1::Kind::FinalMeasured && provider_usage_missing)
                    .then(|| ordinary_chat_fallbacks.get(&entry.attempt_id).copied())
                    .flatten();
                let local_estimate = fallback.is_some() && entry.charge_micros.is_none();
                let (request_state,safe_error_code,model_elapsed_ms) = if let Some(outcome)=ledger.call_outcome(&entry)? {
                    (Some(outcome.state.as_str().to_owned()),outcome.safe_error_code,outcome.model_elapsed_ms)
                } else if ledger.retrieval_was_interrupted(&entry)? {
                    (Some("UNKNOWN".into()),Some("PROCESS_INTERRUPTED".into()),None)
                } else {usage_attempt_outcome(&request_connection,&entry)?};
                let ocr_details = ocr_usage_details(&request_connection,&entry)?;
                let call_metadata = ledger.call_metadata(&entry.entry_id)?;
                Ok(DesktopUsageLedgerRecordProjection {
                    requested_model_id:entry.requested_model_id.clone(),actual_model_id:entry.actual_model_id.clone(),
                    attempt_id:entry.attempt_id.clone(),source_root_id:sha256(root.to_string_lossy().as_bytes()),
                    call_metadata, execution_id:entry.execution_id.clone(),invocation_id:entry.invocation_id.clone(),
                    request_state,safe_error_code,model_elapsed_ms,ocr_details,
                    entry_id: entry.entry_id,
                    conversation_id: entry.conversation_id,
                    model_id: entry.actual_model_id.unwrap_or(entry.requested_model_id),
                    kind: entry.kind.as_str().to_owned(),
                    fact_grade: if local_estimate {
                        usage_ledger_v1::FactGrade::Estimated.as_str().to_owned()
                    } else {
                        entry.fact_grade.as_str().to_owned()
                    },
                    input_tokens: fallback.map(|value| value.0).or(entry.input_tokens),
                    output_tokens: fallback.map(|value| value.1).or(entry.output_tokens),
                    cached_input_tokens: fallback
                        .map(|value| value.2)
                        .or(entry.cached_input_tokens),
                    charge_micros: entry.charge_micros,
                    currency_code: entry.currency_code,
                    cost_source: entry
                        .cost_source
                        .or_else(|| local_estimate.then(|| "LOCAL_ESTIMATE".to_owned())),
                    occurred_at_ms: entry.occurred_at_ms,
                })
            })
            .collect::<Result<Vec<_>,String>>()?;
        Ok(DesktopUsageLedgerProjection {
            input_tokens: records
                .iter()
                .filter_map(|record| record.input_tokens)
                .sum(),
            output_tokens: records
                .iter()
                .filter_map(|record| record.output_tokens)
                .sum(),
            cached_input_tokens: records
                .iter()
                .filter_map(|record| record.cached_input_tokens)
                .sum(),
            records,
        })
    })
    .await
    .map_err(|_| json_error("调用记录后台读取线程异常"))?
}

