#[tauri::command]
async fn read_desktop_privacy_inventory(
    app: AreaAppHandle,
) -> Result<DesktopPrivacyInventoryProjection, String> {
    // The picker migrates the application root, not the WORK child database.
    let application_root = app.root_state().store_paths.root.clone();
    let config = if let Some(config) = &app.root_state().storage_location_config {
        config.clone()
    } else {
        app.path()
            .app_config_dir()
            .map_err(|_| "配置目录不可用")?
            .join("storage-location.json")
    };
    run_desktop_store_blocking(
        app,
        "Desktop store 被锁定",
        "隐私清单后台读取线程异常",
        move |store| {
            let mut inventory = store.read_desktop_privacy_inventory()?;
            inventory.storage_path = application_root.to_string_lossy().into_owned();
            inventory.pending_storage_path =
                desktop_storage_location::pending_path(&config, &application_root)?
                    .map(|path| path.to_string_lossy().into_owned());
            Ok(inventory)
        },
    )
    .await
}

#[tauri::command]
fn preview_desktop_privacy_deletion(
    app: AreaAppHandle,
    args: DesktopPrivacyPreviewArgs,
) -> Result<DesktopPrivacyDeletionPreview, String> {
    if args.scope == "ALL_LOCAL_BUSINESS_DATA" {
        return preview_full_local_business_data(&app.root_state());
    }
    app.area_state()?
        .store
        .lock()
        .map_err(|_| json_error("Desktop store 被锁定"))?
        .preview_desktop_privacy_deletion(args)
}

fn preview_full_local_business_data(root: &AppState) -> Result<DesktopPrivacyDeletionPreview, String> {
    if data_areas_have_active_execution(root) {
        return Err(json_error("存在运行中的任务，请完成任务后重新预览全部本地数据"));
    }
    let work = root.work_area.as_ref().ok_or_else(|| json_error("WORK 区尚未就绪"))?;
    let mut totals = BTreeMap::<String, (u64, u64)>::new();
    for owner in [&*root, &**work] {
        let store = owner.store.lock().map_err(|_| json_error("Desktop store 被锁定"))?;
        if store.configuration_database.is_none() {
            return Err(json_error("共享配置区尚未就绪"));
        }
        for item in store.read_desktop_privacy_inventory()?.aggregates {
            let total = totals.entry(item.id).or_default();
            total.0 = total.0.saturating_add(item.count);
            total.1 = total.1.saturating_add(item.byte_count);
        }
    }
    let (files, bytes) = DesktopWorkspaceStore::privacy_file_aggregate(&root.account_root)?;
    totals.insert("files_app_private".into(), (files, bytes));
    let aggregates = totals.into_iter().filter(|(_, (count, bytes))| *count > 0 || *bytes > 0)
        .map(|(id, (count, byte_count))| DesktopPrivacyAggregateProjection { id, count, byte_count })
        .collect::<Vec<_>>();
    let mut stable = String::from("ALL_LOCAL_BUSINESS_DATA");
    for item in &aggregates {
        stable.push_str(&format!("|{}:{}:{}", item.id, item.count, item.byte_count));
    }
    for name in ["workspace.sqlite3", "work-area/workspace.sqlite3", "app-configuration.sqlite3"] {
        let database = root.account_root.join(name);
        stable.push_str(&format!("|{name}:{}", sha256_file(&database)?));
        let wal = PathBuf::from(format!("{}-wal", database.display()));
        if wal.exists() {
            stable.push_str(&format!("|{name}-wal:{}", sha256_file(&wal)?));
        }
    }
    let credentials = root.account_root.join("provider-credentials-v1");
    if credentials.exists() {
        for entry in fs::read_dir(&credentials).map_err(|_| json_error("凭据范围不可枚举"))? {
            let entry = entry.map_err(|_| json_error("凭据范围不可读取"))?;
            let metadata = fs::symlink_metadata(entry.path()).map_err(|_| json_error("凭据范围身份不可读取"))?;
            if !metadata.is_file() || metadata.file_type().is_symlink() {
                return Err(json_error("凭据范围包含非普通文件"));
            }
            let name = entry.file_name().into_string().map_err(|_| json_error("凭据范围名称无效"))?;
            stable.push_str(&format!("|credential:{name}:{}", sha256_file(&entry.path())?));
        }
    }
    Ok(DesktopPrivacyDeletionPreview {
        scope: "ALL_LOCAL_BUSINESS_DATA".into(),
        aggregates,
        fingerprint: sha256(stable.as_bytes()),
        task_candidates: Vec::new(),
    })
}

#[tauri::command]
fn delete_desktop_privacy_data(
    app: AreaAppHandle,
    args: DesktopPrivacyDeleteArgs,
) -> Result<DesktopPrivacyDeletionResult, String> {
    if args.scope == "ALL_LOCAL_BUSINESS_DATA" {
        return queue_full_local_business_data_delete(&app, args);
    }
    let state = app.area_state()?;
    let store = state
        .store
        .lock()
        .map_err(|_| json_error("Desktop store 被锁定"))?;
    store.delete_desktop_privacy_scope(args)
}

fn queue_full_local_business_data_delete(
    app: &AreaAppHandle,
    args: DesktopPrivacyDeleteArgs,
) -> Result<DesktopPrivacyDeletionResult, String> {
    if args.confirmation_phrase != "删除全部本地业务数据" || !args.selected_task_ids.is_empty() {
        return Err(json_error("需要输入完整确认语"));
    }
    let root = app.root_state();
    if !matches!(root.startup_mode, DesktopStartupMode::Normal | DesktopStartupMode::UiSchemaDiagnostic) {
        return Err(json_error("当前启动模式不能删除本地业务数据"));
    }
    // Serialize task admission with the final preview and exit-queue publication.
    let mut pending = PENDING_FULL_LOCAL_DELETE.lock().map_err(|_| json_error("全部删除队列不可用"))?;
    let preview = preview_full_local_business_data(&root)?;
    if preview.fingerprint != args.preview_fingerprint {
        return Err(json_error("数据已变化或状态不再安全，请重新预览后确认"));
    }
    if pending.is_some() {
        return Err(json_error("全部删除已进入退出队列"));
    }
    *pending = Some(PendingFullLocalDelete {
        root: root.account_root.clone(),
        root_lock: root._process_lock.try_clone().map_err(|_| json_error("进程锁不可复制"))?,
        synthetic_pause: if cfg!(all(windows, debug_assertions))
            && std::env::var_os(desktop_windows_acceptance::ROOT_ENV)
                .map(PathBuf::from).and_then(|path| path.canonicalize().ok())
                == Some(root.account_root.clone())
            && root.account_root.join(".nanfeng-windows-acceptance.json").is_file()
        {
            std::env::var("NANFENG_AI_WINDOWS_FULL_DELETE_PAUSE").ok()
                .filter(|step| ["candidate-published", "after-commit"].contains(&step.as_str()))
        } else { None },
    });
    let exit_app = app.clone();
    if std::thread::Builder::new().name("nanfeng-full-delete-exit".into()).spawn(move || {
        std::thread::sleep(std::time::Duration::from_millis(250));
        exit_app.exit(0);
    }).is_err() {
        *pending = None;
        return Err(json_error("全部删除无法安排安全退出"));
    }
    Ok(DesktopPrivacyDeletionResult {
        deleted: preview.aggregates,
        cleanup_pending: false,
        credential_cleanup_pending: false,
        restart_required: true,
    })
}

