#[tauri::command]
async fn read_desktop_video_thumbnail(
    app: AreaAppHandle,
    args: DesktopVideoThumbnailArgs,
    request_id: Option<u64>,
) -> Result<DesktopVideoThumbnail, String> {
    let media_resource_dir = app.path().resource_dir().ok();
    let (id, cancellation, registry, slots) = {
        let state = app.area_state()?;
        let registry = Arc::clone(&state.video_thumbnail_requests);
        let mut requests = registry
            .lock()
            .map_err(|_| json_error("视频缩略图请求状态不可用"))?;
        let id = match request_id {
            Some(id) => id,
            None => requests.begin()?,
        };
        let cancellation = requests.start(id)?;
        (
            id,
            cancellation,
            Arc::clone(&registry),
            Arc::clone(&state.video_thumbnail_slots),
        )
    };
    let completion = desktop_preview_requests::ReadCompletion::new(registry, id);
    let permit = desktop_preview_requests::acquire_read_slot(slots, &cancellation).await?;
    run_desktop_store_paths_blocking(
        app,
        "本地视频缩略图锁不可用",
        "本地视频缩略图后台读取线程异常",
        move |paths| {
            // Ownership follows the blocking worker, even if its async caller is dropped.
            let _permit = permit;
            let _completion = completion;
            read_desktop_video_thumbnail_cancellable(
                &paths.root,
                &paths.database,
                &args,
                media_resource_dir.as_deref(),
                &cancellation,
            )
        },
    )
    .await
}

#[tauri::command]
async fn read_desktop_search_attachment_preview(
    app: AreaAppHandle,
    args: DesktopTextPreviewArgs,
) -> Result<DesktopSearchAttachmentPreview, String> {
    let media_resource_dir = app.path().resource_dir().ok();
    run_desktop_store_paths_blocking(
        app,
        "本地搜索附件预览锁不可用",
        "本地搜索附件预览后台线程异常",
        move |paths| {
            read_desktop_search_attachment_preview_from_paths(
                &paths.root,
                &paths.database,
                media_resource_dir.as_deref(),
                &args,
            )
        },
    )
    .await
}

