#[tauri::command]
fn cancel_desktop_archive_preview(
    state: AreaState<'_>,
    request_id: u64,
) -> Result<(), String> {
    state
        .archive_preview_requests
        .lock()
        .map_err(|_| json_error("压缩包请求状态不可用"))?
        .cancel(request_id);
    Ok(())
}

async fn run_desktop_archive_request<T, F>(
    app: AreaAppHandle,
    request_id: Option<u64>,
    operation: F,
) -> Result<T, String>
where
    T: Send + 'static,
    F: FnOnce(&DesktopStoreReadPaths, &AtomicBool) -> Result<T, String> + Send + 'static,
{
    let (id, cancellation) = {
        let state = app.area_state()?;
        let mut requests = state
            .archive_preview_requests
            .lock()
            .map_err(|_| json_error("压缩包请求状态不可用"))?;
        let id = match request_id {
            Some(id) => id,
            None => requests.begin()?,
        };
        (id, requests.start(id)?)
    };
    let result = run_desktop_preview_paths_blocking(
        app.clone(),
        "本地压缩包预览锁不可用",
        "本地压缩包后台读取线程异常",
        move |paths| {
            if cancellation.load(Ordering::SeqCst) {
                return Err(json_error("压缩包预览已取消"));
            }
            let result = operation(&paths, &cancellation)?;
            if cancellation.load(Ordering::SeqCst) {
                return Err(json_error("压缩包预览已取消"));
            }
            Ok(result)
        },
    )
    .await;
    if let Ok(mut requests) = app.area_state()?.archive_preview_requests.lock() {
        requests.finish(id);
    }
    result
}

