#[tauri::command]
async fn open_desktop_attachment_with_system(
    app: AreaAppHandle,
    state: AreaState<'_>,
    args: DesktopSystemOpenAttachmentArgs,
) -> Result<(), String> {
    state.require_external_access()?;
    let path = run_desktop_store_blocking(
        app,
        "本地附件打开锁不可用",
        "本地附件准备任务异常",
        move |store| store.prepare_attachment_for_system_open(&args),
    )
    .await?;
    // Do not retain the business store lock while an external application starts.
    tauri::async_runtime::spawn_blocking(move || {
        DesktopWorkspaceStore::open_prepared_attachment_with_system(&path)
    })
    .await
    .map_err(|_| json_error("系统打开后台任务异常"))?
}

#[tauri::command]
async fn share_desktop_attachment(
    app: AreaAppHandle,
    window: tauri::WebviewWindow,
    state: AreaState<'_>,
    args: DesktopSystemOpenAttachmentArgs,
) -> Result<(), String> {
    state.require_external_access()?;
    let path = run_desktop_store_blocking(
        app,
        "本地附件分享锁不可用",
        "本地附件分享准备任务异常",
        move |store| store.prepare_attachment_for_share(&args),
    )
    .await?;
    #[cfg(target_os = "macos")]
    {
        let view_address = window
            .ns_view()
            .map_err(|_| json_error("macOS 分享锚点不可用"))? as usize;
        let path = path.to_string_lossy().to_string();
        window
            .run_on_main_thread(move || {
                let path = NSString::from_str(&path);
                let url = NSURL::fileURLWithPath(&path);
                let item: Retained<AnyObject> = url.into();
                let items = NSArray::from_retained_slice(&[item]);
                let picker = unsafe {
                    NSSharingServicePicker::initWithItems(NSSharingServicePicker::alloc(), &items)
                };
                let view = unsafe { &*(view_address as *const NSView) };
                picker.showRelativeToRect_ofView_preferredEdge(
                    view.bounds(),
                    view,
                    NSRectEdge::MinY,
                );
            })
            .map_err(|_| json_error("macOS 分享面板未打开"))?;
        Ok(())
    }
    #[cfg(windows)]
    {
        desktop_windows_share::show(&window, &path).await
    }
    #[cfg(not(any(target_os = "macos", windows)))]
    {
        let _ = (window, path);
        Err(json_error("当前平台尚未提供受控系统分享适配器"))
    }
}

fn validated_desktop_source_link(href: &str) -> Result<Url, String> {
    let url = Url::parse(href.trim()).map_err(|_| json_error("来源网站地址无效"))?;
    if !matches!(url.scheme(), "http" | "https")
        || url.host_str().is_none()
        || !url.username().is_empty()
        || url.password().is_some()
    {
        return Err(json_error("来源网站地址不受支持"));
    }
    Ok(url)
}

#[tauri::command]
async fn open_desktop_source_link(
    state: AreaState<'_>,
    args: DesktopSourceLinkArgs,
) -> Result<(), String> {
    state.require_external_access()?;
    let url = validated_desktop_source_link(&args.href)?;
    #[cfg(target_os = "macos")]
    {
        std::process::Command::new("/usr/bin/open")
            .arg(url.as_str())
            .spawn()
            .map_err(|_| json_error("无法交给 macOS 浏览器打开该来源网站"))?;
        Ok(())
    }
    #[cfg(windows)]
    {
        tauri::async_runtime::spawn_blocking(move || desktop_windows_system_open::open_source(&url))
            .await
            .map_err(|_| json_error("来源网站打开后台任务异常"))?
    }
    #[cfg(not(any(target_os = "macos", windows)))]
    {
        let _ = url;
        Err(json_error("当前平台尚未提供受控来源网站打开适配器"))
    }
}

