#[tauri::command]
fn export_desktop_json_knowledge(state:AreaState<'_>,workspace_id:String,knowledge_ids:Vec<String>,selected_path:String)->Result<desktop_json_knowledge_export_v1::Receipt,String> {
    let target=Path::new(&selected_path);
    let parent=target.parent().ok_or("JSON_EXPORT_TARGET_INVALID")?.canonicalize().map_err(|_|"JSON_EXPORT_TARGET_INVALID")?;
    let private_root=state.account_root.canonicalize().map_err(|_|"JSON_EXPORT_PRIVATE_ROOT")?;
    if parent.starts_with(private_root) { return Err("JSON_EXPORT_PRIVATE_TARGET".into()); }
    let store=state.store.lock().map_err(|_|json_error("Desktop store 被锁定"))?;
    let prepared=desktop_json_knowledge_export_v1::prepare(&mut store.connection()?,&workspace_id,&knowledge_ids,&chrono::Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Millis,true))?;
    desktop_json_knowledge_export_v1::write(prepared,target)
}

