async fn run_desktop_web_knowledge(state:AreaState<'_>,workspace_id:String,task_id:String,raw_url:String,retry:bool)->Result<desktop_web_knowledge_tasks_v1::Task,String> {
    let registration=state.web_jobs.begin(&workspace_id,&task_id)?;
    let (c,root)={let store=state.store.lock().map_err(|_|json_error("Desktop store 被锁定"))?;(store.connection()?,state.store_paths.root.clone())};
    desktop_web_background_v1::run_registered(c,root,workspace_id,task_id,raw_url,retry,registration).await
}
