async fn execute_desktop_history_knowledge_prepared(
    app: AreaAppHandle,
    prepared: DesktopHistoryKnowledgePrepared,
) -> Result<desktop_history_knowledge_v1::Projection, String> {
    let state = app.area_state()?;
    let signal = Arc::new(AtomicBool::new(false));
    let cancellation = Arc::new(BackgroundCancellationRegistration::begin(
        &state.history_knowledge_cancellations,
        prepared.reservation.candidate_id.clone(), signal.clone(),
    )?);
    let secret = if state.ordinary_chat_mock_endpoint.is_some() {
        Zeroizing::new(b"local-history-knowledge-mock-only".to_vec())
    } else {
        let credential_store = state.credentials.clone();
        match credential_store.with_secret(&prepared.provider_id, |bytes| {
            Ok(Zeroizing::new(bytes.to_vec()))
        }) {
            Ok(secret) => secret,
            Err(_) => {
                let connection = state
                    .store
                    .lock()
                    .map_err(|_| json_error("Desktop store 被锁定"))?
                    .connection()?;
                let _ = desktop_history_knowledge_v1::fail(
                    &connection,
                    &prepared.reservation.candidate_id,
                    false,
                    "CREDENTIAL",
                    system_now_millis(),
                );
                return desktop_history_knowledge_v1::read_projection(&connection)
                    .map_err(|error| json_error(&error));
            }
        }
    };
    let request = desktop_ordinary_chat_v1::TransportRequest {
        endpoint: prepared.endpoint.clone(),
        provider_id: prepared.provider_id.clone(),
        model_id: prepared.model_id.clone(),
        messages: desktop_history_knowledge_v1::prompt(&prepared.reservation.source),
        idempotency_key: prepared.reservation.attempt_id.clone(),
        max_output_tokens: 768,
        web_search_route: "NONE".into(),
        structured_json: false,
        disable_thinking: false,

        grounded_answer: false,
        explicit_search_query: None,
    };
    let worker_app = app.clone();
    let worker_prepared = prepared.clone();
    let worker_cancellation = cancellation.clone();
    let result = tauri::async_runtime::spawn_blocking(move || {
        let _cancellation = worker_cancellation;
        tauri::async_runtime::block_on(desktop_ordinary_chat_v1::execute_streaming(
            request,
            secret,
            signal,
            |_| Ok(()),
        ))
    })
    .await
    .map_err(|_| json_error("历史资料库后台任务未返回"))?;
    let state = worker_app.area_state()?;
    let projection = {
        let store = state
            .store
            .lock()
            .map_err(|_| json_error("Desktop store 被锁定"))?;
        let mut connection = store.connection()?;
        match result {
            Ok(completed) => {
                let candidate = desktop_history_knowledge_v1::complete(
                    &mut connection,
                    &worker_prepared.reservation.candidate_id,
                    desktop_history_knowledge_v1::Completion {
                        provider_id: &worker_prepared.provider_id,
                        requested_model_id: &worker_prepared.model_id,
                        actual_model_id: completed.actual_model_id.as_deref(),
                        response_text: &completed.text,
                        input_tokens: completed.usage.input_tokens,
                        output_tokens: completed.usage.output_tokens,
                        cached_input_tokens: completed.usage.cached_input_tokens,
                        reasoning_tokens: completed.usage.reasoning_tokens,
                        charge_micros: completed.reported_cost_micros,
                    },
                    system_now_millis(),
                );
                // Provider measurements belong to this Attempt even if saving the
                // review candidate fails. Append independently before propagating
                // the original save error; never turn it into a successful review.
                let _ = store.complete_history_knowledge_usage(&worker_prepared, &completed);
                candidate?
            }
            Err(desktop_ordinary_chat_v1::Failure::MeasuredExplicit { code, measurement, .. }) => {
                let completed = measurement.content_free_completed();
                let candidate = desktop_history_knowledge_v1::fail_reported(
                    &mut connection,
                    &worker_prepared.reservation.candidate_id,
                    code,
                    desktop_history_knowledge_v1::Completion {
                        provider_id: &worker_prepared.provider_id,
                        requested_model_id: &worker_prepared.model_id,
                        actual_model_id: completed.actual_model_id.as_deref(),
                        response_text: "",
                        input_tokens: completed.usage.input_tokens,
                        output_tokens: completed.usage.output_tokens,
                        cached_input_tokens: completed.usage.cached_input_tokens,
                        reasoning_tokens: completed.usage.reasoning_tokens,
                        charge_micros: completed.reported_cost_micros,
                    },
                    system_now_millis(),
                );
                let _ = store.complete_history_knowledge_usage(&worker_prepared, &completed);
                candidate?
            }
            Err(desktop_ordinary_chat_v1::Failure::MeasuredUnknown { code, measurement }) => {
                let completed = measurement.content_free_completed();
                let candidate = desktop_history_knowledge_v1::unknown_reported(
                    &mut connection,
                    &worker_prepared.reservation.candidate_id,
                    code,
                    desktop_history_knowledge_v1::Completion {
                        provider_id: &worker_prepared.provider_id,
                        requested_model_id: &worker_prepared.model_id,
                        actual_model_id: completed.actual_model_id.as_deref(),
                        response_text: "",
                        input_tokens: completed.usage.input_tokens,
                        output_tokens: completed.usage.output_tokens,
                        cached_input_tokens: completed.usage.cached_input_tokens,
                        reasoning_tokens: completed.usage.reasoning_tokens,
                        charge_micros: completed.reported_cost_micros,
                    },
                    system_now_millis(),
                );
                let _ = store.complete_history_knowledge_usage(&worker_prepared, &completed);
                candidate?
            }
            Err(desktop_ordinary_chat_v1::Failure::MeasuredCancelled { measurement }) => {
                let code="CANCELLED";
                let completed = measurement.content_free_completed();
                let candidate = desktop_history_knowledge_v1::fail_reported(
                    &mut connection,
                    &worker_prepared.reservation.candidate_id,
                    code,
                    desktop_history_knowledge_v1::Completion {
                        provider_id: &worker_prepared.provider_id,
                        requested_model_id: &worker_prepared.model_id,
                        actual_model_id: completed.actual_model_id.as_deref(),
                        response_text: "",
                        input_tokens: completed.usage.input_tokens,
                        output_tokens: completed.usage.output_tokens,
                        cached_input_tokens: completed.usage.cached_input_tokens,
                        reasoning_tokens: completed.usage.reasoning_tokens,
                        charge_micros: completed.reported_cost_micros,
                    },
                    system_now_millis(),
                );
                let _ = store.complete_history_knowledge_usage(&worker_prepared, &completed);
                candidate?
            }
            Err(failure) => {
                let (unknown, code) = match failure {
                    desktop_ordinary_chat_v1::Failure::Cancelled | desktop_ordinary_chat_v1::Failure::MeasuredCancelled { .. } => (false, "CANCELLED"),
                    desktop_ordinary_chat_v1::Failure::Explicit { code, .. }
                    | desktop_ordinary_chat_v1::Failure::MeasuredExplicit { code, .. } => (false, code),
                    desktop_ordinary_chat_v1::Failure::Unknown { code } | desktop_ordinary_chat_v1::Failure::MeasuredUnknown { code, .. } => (true, code),
                };
                desktop_history_knowledge_v1::fail(
                    &connection,
                    &worker_prepared.reservation.candidate_id,
                    unknown,
                    code,
                    system_now_millis(),
                )?
            }
        }
    };
    let connection = state
        .store
        .lock()
        .map_err(|_| json_error("Desktop store 被锁定"))?
        .connection()?;
    let _ = projection;
    desktop_history_knowledge_v1::read_projection(&connection).map_err(|error| json_error(&error))
}

