async fn execute_desktop_reminder_draft_prepared(
    app: AreaAppHandle,
    prepared: DesktopReminderDraftPrepared,
) -> Result<desktop_reminders_v1::Projection, String> {
    let state = app.area_state()?;
    let signal = Arc::new(AtomicBool::new(false));
    let cancellation = Arc::new(BackgroundCancellationRegistration::begin(
        &state.reminder_cancellations,
        prepared.reservation.draft_id.clone(), signal.clone(),
    )?);
    let secret = if state.ordinary_chat_mock_endpoint.is_some() {
        Zeroizing::new(b"local-reminder-draft-mock-only".to_vec())
    } else {
        let credentials = &state.credentials;
        credentials.with_secret(&prepared.provider_id, |bytes| {
            Ok(Zeroizing::new(bytes.to_vec()))
        })?
    };
    let request = desktop_ordinary_chat_v1::TransportRequest {
        endpoint: prepared.endpoint.clone(),
        provider_id: prepared.provider_id.clone(),
        model_id: prepared.model_id.clone(),
        messages: desktop_reminders_v1::prompt(&prepared.reservation, system_now_millis()),
        idempotency_key: prepared.reservation.attempt_id.clone(),
        max_output_tokens: 1024,
        web_search_route: "NONE".into(),
        structured_json: false,
        disable_thinking: false,

        grounded_answer: false,
        explicit_search_query: None,
    };
    let worker = prepared.clone();
    let progress_app=app.clone();let progress_prepared=prepared.clone();
    let worker_cancellation = cancellation.clone();
    let result = tauri::async_runtime::spawn_blocking(move || {
        let _cancellation = worker_cancellation;
        tauri::async_runtime::block_on(desktop_ordinary_chat_v1::execute_streaming_observed(
            request,
            secret,
            signal,
            |_| Ok(()),
            |measurement| {
                use desktop_ordinary_chat_v1::Failure;
                let state=progress_app.area_state().map_err(|_|Failure::Unknown{code:"LOCAL_PERSISTENCE"})?;
                let store=state.store.lock().map_err(|_|Failure::Unknown{code:"LOCAL_PERSISTENCE"})?;
                let connection=store.connection().map_err(|_|Failure::Unknown{code:"LOCAL_PERSISTENCE"})?;
                desktop_reminders_v1::checkpoint_draft_measurement(&connection,&progress_prepared.reservation,&progress_prepared.provider_id,&progress_prepared.model_id,measurement,system_now_millis())
                    .map_err(|error|if error=="REMINDER_DRAFT_CHANGED"{Failure::Cancelled}else{Failure::Unknown{code:"LOCAL_PERSISTENCE"}})
            },
        ))
    })
    .await
    .map_err(|_| json_error("提醒草案后台任务未返回"))?;
    let state = app.area_state()?;
    {
        let store = state
            .store
            .lock()
            .map_err(|_| json_error("Desktop store 被锁定"))?;
        let connection = store.connection()?;
        desktop_reminders_v1::require_current_draft(&connection,&worker.reservation).map_err(|error|json_error(&error))?;
        match result {
            Ok(completed) => {
                let completion = desktop_reminders_v1::Completion {
                    provider_id: &worker.provider_id,
                    requested_model_id: &worker.model_id,
                    actual_model_id: completed.actual_model_id.as_deref(),
                    text: &completed.text,
                    input_tokens: completed.usage.input_tokens,
                    output_tokens: completed.usage.output_tokens,
                    cached_input_tokens: completed.usage.cached_input_tokens,
                    charge_micros: completed.reported_cost_micros,
                };
                if desktop_reminders_v1::complete_draft(
                    &connection,
                    &worker.reservation.draft_id,
                    completion,
                    system_now_millis(),
                )
                .is_err()
                {
                    let _ = desktop_reminders_v1::fail_draft_reported(&connection, &worker.reservation.draft_id, "REMINDER_DRAFT_FORMAT", desktop_reminders_v1::Completion {
                        provider_id: &worker.provider_id, requested_model_id: &worker.model_id,
                        actual_model_id: completed.actual_model_id.as_deref(), text: "",
                        input_tokens: completed.usage.input_tokens, output_tokens: completed.usage.output_tokens,
                        cached_input_tokens: completed.usage.cached_input_tokens, charge_micros: completed.reported_cost_micros,
                    }, system_now_millis());
                }
                {
                    let _ = store.complete_reminder_usage(
                        &worker.reservation.draft_id,
                        &worker.reservation.attempt_id,
                        Some(&worker.reservation.conversation_id),
                        &worker.model_id,
                        &completed,
                    );
                }
            }
            Err(desktop_ordinary_chat_v1::Failure::MeasuredExplicit { code, measurement, .. }) => {
                let completed = measurement.content_free_completed();
                let _ = desktop_reminders_v1::fail_draft_reported(&connection, &worker.reservation.draft_id, code, desktop_reminders_v1::Completion {
                        provider_id: &worker.provider_id, requested_model_id: &worker.model_id,
                        actual_model_id: completed.actual_model_id.as_deref(), text: "",
                        input_tokens: completed.usage.input_tokens, output_tokens: completed.usage.output_tokens,
                        cached_input_tokens: completed.usage.cached_input_tokens, charge_micros: completed.reported_cost_micros,
                    }, system_now_millis());
                let _ = store.complete_reminder_usage(&worker.reservation.draft_id, &worker.reservation.attempt_id, Some(&worker.reservation.conversation_id), &worker.model_id, &completed);
            }
            Err(desktop_ordinary_chat_v1::Failure::MeasuredUnknown { code, measurement }) => {
                let completed = measurement.content_free_completed();
                let _ = desktop_reminders_v1::unknown_draft_reported(&connection, &worker.reservation.draft_id, code, desktop_reminders_v1::Completion {
                        provider_id: &worker.provider_id, requested_model_id: &worker.model_id,
                        actual_model_id: completed.actual_model_id.as_deref(), text: "",
                        input_tokens: completed.usage.input_tokens, output_tokens: completed.usage.output_tokens,
                        cached_input_tokens: completed.usage.cached_input_tokens, charge_micros: completed.reported_cost_micros,
                    }, system_now_millis());
                let _ = store.complete_reminder_usage(&worker.reservation.draft_id, &worker.reservation.attempt_id, Some(&worker.reservation.conversation_id), &worker.model_id, &completed);
            }
            Err(desktop_ordinary_chat_v1::Failure::MeasuredCancelled { measurement }) => {
                let code="CANCELLED";
                let completed = measurement.content_free_completed();
                let _ = desktop_reminders_v1::fail_draft_reported(&connection, &worker.reservation.draft_id, code, desktop_reminders_v1::Completion {
                        provider_id: &worker.provider_id, requested_model_id: &worker.model_id,
                        actual_model_id: completed.actual_model_id.as_deref(), text: "",
                        input_tokens: completed.usage.input_tokens, output_tokens: completed.usage.output_tokens,
                        cached_input_tokens: completed.usage.cached_input_tokens, charge_micros: completed.reported_cost_micros,
                    }, system_now_millis());
                let _ = store.complete_reminder_usage(&worker.reservation.draft_id, &worker.reservation.attempt_id, Some(&worker.reservation.conversation_id), &worker.model_id, &completed);
            }
            Err(failure) => {
                let (unknown, code) = match failure {
                    desktop_ordinary_chat_v1::Failure::Cancelled | desktop_ordinary_chat_v1::Failure::MeasuredCancelled { .. } => (false, "CANCELLED"),
                    desktop_ordinary_chat_v1::Failure::Explicit { code, .. }
                    | desktop_ordinary_chat_v1::Failure::MeasuredExplicit { code, .. } => (false, code),
                    desktop_ordinary_chat_v1::Failure::Unknown { code } | desktop_ordinary_chat_v1::Failure::MeasuredUnknown { code, .. } => (true, code),
                };
                let _ = desktop_reminders_v1::fail_draft(
                    &connection,
                    &worker.reservation.draft_id,
                    Some(&worker.provider_id),
                    Some(&worker.model_id),
                    unknown,
                    code,
                    system_now_millis(),
                );
            }
        }
    }
    let connection = state
        .store
        .lock()
        .map_err(|_| json_error("Desktop store 被锁定"))?
        .connection()?;
    desktop_reminders_v1::read_projection(&connection).map_err(|error| json_error(&error))
}

async fn execute_desktop_reminder_run_prepared(
    app: AreaAppHandle,
    prepared: DesktopReminderRunPrepared,
) -> Result<desktop_reminders_v1::Projection, String> {
    #[cfg(all(windows, debug_assertions))]
    if app.config().identifier == desktop_windows_acceptance::IDENTIFIER {
        let root = app.root_state().account_root.clone();
        tauri::async_runtime::spawn_blocking(move ||
            desktop_windows_acceptance::reminder_registration_checkpoint(&root)
        ).await.map_err(|_| json_error("隔离提醒停点未返回"))??;
    }
    let state = app.area_state()?;
    let signal = Arc::new(AtomicBool::new(false));
    let cancellation = Arc::new(register_prepared_reminder_cancellation(
        &state.store, &state.reminder_cancellations, &prepared, signal.clone(),
    )?);
    let secret = if state.ordinary_chat_mock_endpoint.is_some() {
        Zeroizing::new(b"local-reminder-monitor-mock-only".to_vec())
    } else {
        let credentials = &state.credentials;
        credentials.with_secret(&prepared.provider_id, |bytes| {
            Ok(Zeroizing::new(bytes.to_vec()))
        })?
    };
    let request = desktop_ordinary_chat_v1::TransportRequest {
        endpoint: prepared.endpoint.clone(),
        provider_id: prepared.provider_id.clone(),
        model_id: prepared.model_id.clone(),
        messages: desktop_reminders_v1::run_prompt(&prepared.reservation, system_now_millis()),
        idempotency_key: prepared.reservation.attempt_id.clone(),
        max_output_tokens: 4096,
        web_search_route: "OPENROUTER_SERVER_TOOL".into(),
        structured_json: false,
        disable_thinking: false,

        grounded_answer: false,
        explicit_search_query: None,
    };
    let worker = prepared.clone();
    let progress_app=app.clone();let progress_prepared=prepared.clone();
    let worker_cancellation = cancellation.clone();
    let result = tauri::async_runtime::spawn_blocking(move || {
        let _cancellation = worker_cancellation;
        tauri::async_runtime::block_on(desktop_ordinary_chat_v1::execute_streaming_observed(
            request,
            secret,
            signal,
            |_| Ok(()),
            |measurement| {
                use desktop_ordinary_chat_v1::Failure;
                let state=progress_app.area_state().map_err(|_|Failure::Unknown{code:"LOCAL_PERSISTENCE"})?;
                let store=state.store.lock().map_err(|_|Failure::Unknown{code:"LOCAL_PERSISTENCE"})?;
                let connection=store.connection().map_err(|_|Failure::Unknown{code:"LOCAL_PERSISTENCE"})?;
                desktop_reminders_v1::checkpoint_run_measurement(&connection,&progress_prepared.reservation,&progress_prepared.provider_id,&progress_prepared.model_id,measurement)
                    .map_err(|error|if error=="REMINDER_RUN_CHANGED" {Failure::Cancelled}else{Failure::Unknown{code:"LOCAL_PERSISTENCE"}})
            },
        ))
    })
    .await
    .map_err(|_| json_error("计划监控后台任务未返回"))?;
    let plan = {
        let store = state
            .store
            .lock()
            .map_err(|_| json_error("Desktop store 被锁定"))?;
        let mut connection = store.connection()?;
        match result {
            Ok(completed) => {
                let plan = desktop_reminders_v1::complete_run(
                    &connection,
                    &worker.reservation,
                    desktop_reminders_v1::Completion {
                        provider_id: &worker.provider_id,
                        requested_model_id: &worker.model_id,
                        actual_model_id: completed.actual_model_id.as_deref(),
                        text: &completed.text,
                        input_tokens: completed.usage.input_tokens,
                        output_tokens: completed.usage.output_tokens,
                        cached_input_tokens: completed.usage.cached_input_tokens,
                        charge_micros: completed.reported_cost_micros,
                    },
                    system_now_millis(),
                )?;
                let _ = store.complete_reminder_usage(
                    &worker.reservation.plan.plan_id,
                    &worker.reservation.attempt_id,
                    worker.reservation.plan.conversation_id.as_deref(),
                    &worker.model_id,
                    &completed,
                );
                plan
            }
            Err(desktop_ordinary_chat_v1::Failure::MeasuredExplicit { code, measurement, .. }) => {
                let completed = measurement.content_free_completed();
                let plan = desktop_reminders_v1::fail_run_reported(&mut connection, &worker.reservation, code, desktop_reminders_v1::Completion {
                        provider_id: &worker.provider_id, requested_model_id: &worker.model_id,
                        actual_model_id: completed.actual_model_id.as_deref(), text: "",
                        input_tokens: completed.usage.input_tokens, output_tokens: completed.usage.output_tokens,
                        cached_input_tokens: completed.usage.cached_input_tokens, charge_micros: completed.reported_cost_micros,
                    }, system_now_millis())?;
                let _ = store.complete_reminder_usage(&worker.reservation.plan.plan_id, &worker.reservation.attempt_id, worker.reservation.plan.conversation_id.as_deref(), &worker.model_id, &completed);
                plan
            }
            Err(desktop_ordinary_chat_v1::Failure::MeasuredUnknown { code, measurement }) => {
                let completed = measurement.content_free_completed();
                let plan = desktop_reminders_v1::unknown_run_reported(&mut connection, &worker.reservation, code, desktop_reminders_v1::Completion {
                        provider_id: &worker.provider_id, requested_model_id: &worker.model_id,
                        actual_model_id: completed.actual_model_id.as_deref(), text: "",
                        input_tokens: completed.usage.input_tokens, output_tokens: completed.usage.output_tokens,
                        cached_input_tokens: completed.usage.cached_input_tokens, charge_micros: completed.reported_cost_micros,
                    }, system_now_millis())?;
                let _ = store.complete_reminder_usage(&worker.reservation.plan.plan_id, &worker.reservation.attempt_id, worker.reservation.plan.conversation_id.as_deref(), &worker.model_id, &completed);
                plan
            }
            Err(desktop_ordinary_chat_v1::Failure::MeasuredCancelled { measurement }) => {
                let code="CANCELLED";
                let completed = measurement.content_free_completed();
                let plan = desktop_reminders_v1::fail_run_reported(&mut connection, &worker.reservation, code, desktop_reminders_v1::Completion {
                        provider_id: &worker.provider_id, requested_model_id: &worker.model_id,
                        actual_model_id: completed.actual_model_id.as_deref(), text: "",
                        input_tokens: completed.usage.input_tokens, output_tokens: completed.usage.output_tokens,
                        cached_input_tokens: completed.usage.cached_input_tokens, charge_micros: completed.reported_cost_micros,
                    }, system_now_millis())?;
                let _ = store.complete_reminder_usage(&worker.reservation.plan.plan_id, &worker.reservation.attempt_id, worker.reservation.plan.conversation_id.as_deref(), &worker.model_id, &completed);
                plan
            }
            Err(failure) => {
                let (unknown, code) = match failure {
                    desktop_ordinary_chat_v1::Failure::Cancelled | desktop_ordinary_chat_v1::Failure::MeasuredCancelled { .. } => (false, "CANCELLED"),
                    desktop_ordinary_chat_v1::Failure::Explicit { code, .. }
                    | desktop_ordinary_chat_v1::Failure::MeasuredExplicit { code, .. } => (false, code),
                    desktop_ordinary_chat_v1::Failure::Unknown { code } | desktop_ordinary_chat_v1::Failure::MeasuredUnknown { code, .. } => (true, code),
                };
                desktop_reminders_v1::fail_run(
                    &connection,
                    &worker.reservation,
                    Some(&worker.provider_id),
                    Some(&worker.model_id),
                    unknown,
                    code,
                    system_now_millis(),
                )?
            }
        }
    };
    let _ = app.emit(
        "desktop-reminder-runtime-v1",
        DesktopReminderRuntimeEvent {
            plan_id: plan.plan_id.clone(),
            workspace_id: plan.workspace_id.clone(),
            conversation_id: plan.conversation_id.clone(),
            status: plan.status.clone(),
        },
    );
    let connection = state
        .store
        .lock()
        .map_err(|_| json_error("Desktop store 被锁定"))?
        .connection()?;
    desktop_reminders_v1::read_projection(&connection).map_err(|error| json_error(&error))
}

