#[tauri::command]
fn set_desktop_reminder_plan_paused(
    plan_id: String,
    paused: bool,
    app: AreaAppHandle,
) -> Result<desktop_reminders_v1::Projection, String> {
    let projection = {
        let state = app.area_state()?;
        // Match late registration's lock order: persistence and signal publication
        // form one boundary, so a saved pause cannot miss an unregistered run.
        let store = state.store.lock().map_err(|_| json_error("Desktop store 被锁定"))?;
        let connection = store.connection()?;
        let signals = state.reminder_cancellations.lock()
            .map_err(|_| json_error("后台任务停止状态被锁定"))?;
        if let Some(signal) = signals.get(&plan_id) {
            signal.store(true, Ordering::SeqCst);
        }
        let projection = desktop_reminders_v1::set_paused(&connection, &plan_id, paused, system_now_millis())
            .map_err(|error| json_error(&error))?;
        projection
    };
    let _ = reconcile_desktop_background_runtime(&app);
    Ok(projection)
}

