#[tauri::command]
async fn submit_desktop_ordinary_chat(
    app: AreaAppHandle,
    state: AreaState<'_>,
    args: DesktopOrdinaryChatSubmitArgs,
) -> Result<DesktopOrdinaryChatAttemptProjection, String> {
    let _execution = BlockingBusinessExecution::begin(&app.root_state().blocking_business_executions)?;
    let authorization = args
        .egress_authorization
        .as_ref()
        .ok_or_else(|| json_error("本次发送未形成外发授权事实；未向服务商建立连接"))?;
    if authorization.approved_at_ms <= 0
        || !(authorization.disclosure_version == "normal-chat-egress-v2"
            || (state.ordinary_chat_mock_endpoint.is_some()
                && authorization.disclosure_version == "normal-chat-egress-v1"))
    {
        return Err(json_error("本次发送授权事实无效；未向服务商建立连接"));
    }
    state.require_external_access()?;
    if args
        .conversation_id
        .as_ref()
        .is_some_and(|conversation_id| {
            state
                .ordinary_chat_cancellations
                .lock()
                .ok()
                .is_some_and(|values| values.contains_key(&ordinary_cancellation_key(&args.workspace_id, conversation_id)))
        })
    {
        return Err(json_error("当前会话仍在生成；请先停止或等待完成"));
    }
    if let Some(conversation_id) = args.conversation_id.as_deref() {
        if state
            .store
            .lock()
            .map_err(|_| json_error("Desktop store 被锁定"))?
            .has_active_compare_for_conversation(&args.workspace_id, conversation_id)?
        {
            return Err(json_error("当前 Compare 仍在生成；请先停止或等待完成"));
        }
    }
    let prepared = state
        .store
        .lock()
        .map_err(|_| json_error("Desktop store 被锁定"))?
        .prepare_ordinary_chat(args, state.ordinary_chat_mock_endpoint.as_deref())?;
    execute_desktop_ordinary_chat_prepared(app, prepared).await
}

