async fn execute_desktop_compare_prepared(
    app: AreaAppHandle,
    prepared: DesktopComparePrepared,
) -> Result<DesktopCompareExecutionProjection, String> {
    #[cfg(all(windows, debug_assertions))]
    if app.config().identifier == desktop_windows_acceptance::IDENTIFIER {
        let root = app.root_state().account_root.clone();
        tauri::async_runtime::spawn_blocking(move ||
            desktop_windows_acceptance::ordinary_registration_checkpoint(&root)
        ).await.map_err(|_| json_error("隔离 Compare 停点未返回"))??;
    }
    let execution_id = prepared.projection.execution_id.clone();
    let mut branches = prepared.branches.into_iter();
    let chatgpt = branches
        .next()
        .ok_or_else(|| json_error("Compare ChatGPT branch 缺失"))?;
    let claude = branches
        .next()
        .ok_or_else(|| json_error("Compare Claude branch 缺失"))?;
    if branches.next().is_some() {
        return Err(json_error("Compare branch 数量无效"));
    }
    let (chatgpt_result, claude_result) = tokio::join!(
        execute_desktop_ordinary_chat_prepared(app.clone(), chatgpt),
        execute_desktop_ordinary_chat_prepared(app.clone(), claude),
    );
    let projection = app
        .area_state()?
        .store
        .lock()
        .map_err(|_| json_error("Desktop store 被锁定"))?
        .refresh_compare_execution_state(&execution_id)?;
    chatgpt_result?;
    claude_result?;
    Ok(projection)
}

#[tauri::command]
async fn submit_desktop_compare(
    app: AreaAppHandle,
    state: AreaState<'_>,
    args: DesktopCompareSubmitArgs,
) -> Result<DesktopCompareExecutionProjection, String> {
    let authorization = args
        .egress_authorization
        .as_ref()
        .ok_or_else(|| json_error("本次 Compare 未形成外发授权事实；未向服务商建立连接"))?;
    if authorization.approved_at_ms <= 0
        || authorization.disclosure_version != "normal-chat-egress-v1"
    {
        return Err(json_error(
            "本次 Compare 外发授权事实无效；未向服务商建立连接",
        ));
    }
    state.require_external_access()?;
    if args
        .conversation_id
        .as_ref()
        .is_some_and(|conversation_id| {
            state
                .ordinary_chat_cancellations
                .lock()
                .ok()
                .is_some_and(|values| {
                    values
                        .get(&ordinary_cancellation_key(&args.workspace_id, conversation_id))
                        .is_some_and(|signals| !signals.is_empty())
                })
        })
    {
        return Err(json_error("当前会话仍在生成；请先停止或等待完成"));
    }
    if let Some(conversation_id) = args.conversation_id.as_deref() {
        if state
            .store
            .lock()
            .map_err(|_| json_error("Desktop store 被锁定"))?
            .has_active_compare_for_conversation(&args.workspace_id, conversation_id)?
        {
            return Err(json_error("当前 Compare 仍在生成；请先停止或等待完成"));
        }
    }
    let prepared = state
        .store
        .lock()
        .map_err(|_| json_error("Desktop store 被锁定"))?
        .prepare_compare(args, state.ordinary_chat_mock_endpoint.as_deref())?;
    execute_desktop_compare_prepared(app, prepared).await
}

#[tauri::command]
async fn retry_desktop_compare_branch(
    app: AreaAppHandle,
    state: AreaState<'_>,
    args: DesktopCompareRetryArgs,
) -> Result<DesktopCompareExecutionProjection, String> {
    state.require_external_access()?;
    let prepared = state
        .store
        .lock()
        .map_err(|_| json_error("Desktop store 被锁定"))?
        .prepare_ordinary_chat_retry(
            &args.attempt_id,
            state.ordinary_chat_mock_endpoint.as_deref(),
        )?;
    let execution_id = prepared
        .projection
        .compare_execution_id
        .clone()
        .ok_or_else(|| json_error("该 Attempt 不属于 Compare"))?;
    state
        .store
        .lock()
        .map_err(|_| json_error("Desktop store 被锁定"))?
        .refresh_compare_execution_state(&execution_id)?;
    execute_desktop_ordinary_chat_prepared(app.clone(), prepared).await?;
    app.area_state()?
        .store
        .lock()
        .map_err(|_| json_error("Desktop store 被锁定"))?
        .refresh_compare_execution_state(&execution_id)
}

