#[tauri::command]
async fn read_desktop_conversation_draft(
    app: AreaAppHandle,
    workspace_id: String,
    conversation_id: Option<String>,
) -> Result<Option<DesktopConversationDraft>, String> {
    #[cfg(all(windows, debug_assertions))]
    let unbound = conversation_id.is_none();
    #[cfg(all(windows, debug_assertions))]
    let pause_app = app.clone();
    let draft = run_desktop_store_blocking(
        app,
        "Desktop store 被锁定",
        "对话草稿后台读取线程异常",
        move |store| store.read_conversation_draft(&workspace_id, conversation_id.as_deref()),
    )
    .await?;
    #[cfg(all(windows, debug_assertions))]
    if unbound {
        let root = pause_app.area_state()?.store_paths.root.clone();
        tauri::async_runtime::spawn_blocking(move || pause_windows_draft_read_acceptance(&root))
            .await
            .map_err(|_| json_error("草稿读取验收停点线程异常"))??;
    }
    Ok(draft)
}

