#[tauri::command]
async fn refresh_desktop_openrouter_registry(
    app: AreaAppHandle,
) -> Result<desktop_openrouter_registry_v1::RegistryStatus, String> {
    let _execution = Arc::new(BlockingBusinessExecution::begin(
        &app.root_state().blocking_business_executions,
    )?);
    app.area_state()?.require_external_access()?;
    let worker_execution = _execution.clone();
    let catalog = tauri::async_runtime::spawn_blocking(move || {
        let _execution = worker_execution;
        desktop_openrouter_registry_v1::fetch()
    })
        .await.map_err(|_| json_error("模型目录只读核验未返回"))?
        .map_err(json_error)?;
    app.area_state()?.store.lock().map_err(|_| json_error("Desktop store 被锁定"))?
        .persist_openrouter_registry(catalog)
}

