/// Deliberately no-argument.  Production always reports disabled and never reveals the fixture
/// receipt; only an explicitly marked process has the dedicated `/tmp` root.
#[tauri::command]
fn read_p6e_temporary_maintenance_acceptance_status(
    state: AreaState<'_>,
) -> Result<P6eAcceptanceStatus, String> {
    if !state.p6e_acceptance_enabled {
        return Ok(P6eAcceptanceStatus {
            enabled: false,
            receipt: None,
        });
    }
    let store = state
        .store
        .lock()
        .map_err(|_| json_error("Desktop store 被锁定"))?;
    Ok(P6eAcceptanceStatus {
        enabled: true,
        receipt: store.p6e_acceptance_receipt()?,
    })
}

/// Deliberately no-argument.  The env marker and root selection happen before Tauri starts, so a
/// normal production window cannot use this controlled-clock maintenance fixture.
#[tauri::command]
fn run_p6e_temporary_maintenance_acceptance(
    state: AreaState<'_>,
) -> Result<P6eTemporaryMaintenanceAcceptanceReceipt, String> {
    if !state.p6e_acceptance_enabled {
        return Err(json_error("P6-E 维护验收仅限专用 acceptance 启动"));
    }
    state
        .store
        .lock()
        .map_err(|_| json_error("Desktop store 被锁定"))?
        .run_p6e_temporary_maintenance_acceptance()
}

fn validate_scoped_acceptance_root(root: PathBuf, _mac_prefix: &str) -> Result<PathBuf, String> {
    #[cfg(windows)]
    {
        desktop_windows_acceptance::resolve(
            Some(&root),
            true,
            desktop_windows_acceptance::IDENTIFIER,
            &std::env::temp_dir(),
        )?
        .ok_or_else(|| "Windows 独立验收根缺失".to_owned())
    }
    #[cfg(not(windows))]
    {
        if root.is_absolute()
            && !root
                .components()
                .any(|part| matches!(part, std::path::Component::ParentDir))
            && root
                .to_str()
                .is_some_and(|path| path.starts_with(_mac_prefix))
        {
            Ok(root)
        } else {
            Err("Scoped acceptance root invalid".into())
        }
    }
}

fn validate_p6_v2_picker_acceptance_root(root: PathBuf) -> Result<PathBuf, String> {
    validate_scoped_acceptance_root(root, P6_V2_PICKER_ACCEPTANCE_ROOT_PREFIX)
        .map_err(|_| "P6 v2 picker 验收根无效".to_owned())
}

fn p6_v2_picker_acceptance_root() -> Result<Option<PathBuf>, String> {
    std::env::var_os(P6_V2_PICKER_ACCEPTANCE_ROOT_ENV)
        .map(PathBuf::from)
        .map(validate_p6_v2_picker_acceptance_root)
        .transpose()
}

fn validate_ordinary_chat_acceptance_root(root: PathBuf) -> Result<PathBuf, String> {
    validate_scoped_acceptance_root(root, ORDINARY_CHAT_ACCEPTANCE_ROOT_PREFIX)
        .map_err(|_| "ordinary chat acceptance root invalid".to_owned())
}

fn resolve_windows_loopback_acceptance_endpoint(
    value: Option<String>,
    windows: bool,
    windows_acceptance_active: bool,
    isolated_normal_startup: bool,
    invalid: &'static str,
) -> Result<Option<String>, String> {
    let Some(value) = value else {
        return Ok(None);
    };
    if !windows || !windows_acceptance_active || !isolated_normal_startup {
        return Err(invalid.into());
    }
    let url = reqwest::Url::parse(&value).map_err(|_| invalid)?;
    let host = url.host_str().ok_or(invalid)?;
    if url.scheme() != "http"
        || !matches!(host, "127.0.0.1" | "localhost")
        || url.port().is_none()
        || !url.username().is_empty()
        || url.password().is_some()
        || !matches!(url.path(), "" | "/")
        || url.query().is_some()
        || url.fragment().is_some()
    {
        return Err(invalid.into());
    }
    Ok(Some(value.trim_end_matches('/').to_owned()))
}

