#[cfg(test)]
mod windows_model_service_test_endpoint_tests {
    use super::{
        resolve_windows_account_sync_test_endpoint, resolve_windows_model_service_test_endpoint,
        resolve_windows_ordinary_chat_test_endpoint, resolve_windows_ocr_test_endpoint,
    };

    #[test]
    fn loopback_endpoint_requires_windows_acceptance_normal_mode() {
        let endpoint = Some("http://127.0.0.1:19420".to_owned());
        assert_eq!(
            resolve_windows_model_service_test_endpoint(endpoint.clone(), true, true, true)
                .unwrap()
                .as_deref(),
            Some("http://127.0.0.1:19420")
        );
        for (windows, acceptance, normal) in [
            (false, true, true),
            (true, false, true),
            (true, true, false),
        ] {
            assert!(resolve_windows_model_service_test_endpoint(
                endpoint.clone(),
                windows,
                acceptance,
                normal
            )
            .is_err());
        }
        for invalid in [
            "https://127.0.0.1:19420",
            "http://0.0.0.0:19420",
            "http://127.0.0.1",
            "http://127.0.0.1:19420/path",
            "http://user@127.0.0.1:19420",
        ] {
            assert!(resolve_windows_model_service_test_endpoint(
                Some(invalid.to_owned()),
                true,
                true,
                true
            )
            .is_err());
        }
    }

    #[test]
    fn ordinary_chat_loopback_endpoint_uses_the_same_strict_gate() {
        assert_eq!(
            resolve_windows_ordinary_chat_test_endpoint(
                Some("http://localhost:19430/".to_owned()),
                true,
                true,
                true,
            )
            .unwrap()
            .as_deref(),
            Some("http://localhost:19430")
        );
        for invalid in [
            "https://localhost:19430",
            "http://0.0.0.0:19430",
            "http://localhost",
            "http://localhost:19430/chat/completions",
            "http://user@localhost:19430",
            "http://localhost:19430/?mode=test",
        ] {
            assert!(resolve_windows_ordinary_chat_test_endpoint(
                Some(invalid.to_owned()),
                true,
                true,
                true,
            )
            .is_err());
        }
        assert!(resolve_windows_ordinary_chat_test_endpoint(
            Some("http://127.0.0.1:19430".to_owned()),
            true,
            false,
            true,
        )
        .is_err());
    }

    #[test]
    fn ocr_fixture_requires_windows_debug_acceptance_and_loopback() {
        let endpoint = Some("http://127.0.0.1:19431".to_owned());
        assert_eq!(
            resolve_windows_ocr_test_endpoint(endpoint.clone(), true, true, true)
                .unwrap()
                .as_deref(),
            Some("http://127.0.0.1:19431")
        );
        for (debug_windows, acceptance, normal) in [
            (false, true, true),
            (true, false, true),
            (true, true, false),
        ] {
            assert!(resolve_windows_ocr_test_endpoint(endpoint.clone(), debug_windows, acceptance, normal).is_err());
        }
        for invalid in [
            "https://127.0.0.1:19431",
            "http://0.0.0.0:19431",
            "http://127.0.0.1:19431/path",
            "http://user@127.0.0.1:19431",
        ] {
            assert!(resolve_windows_ocr_test_endpoint(Some(invalid.to_owned()), true, true, true).is_err());
        }
    }

    #[test]
    fn account_sync_fixture_requires_windows_debug_acceptance_and_loopback() {
        let endpoint = Some("http://127.0.0.1:19440/".to_owned());
        assert_eq!(
            resolve_windows_account_sync_test_endpoint(endpoint.clone(), true, true, true)
                .unwrap()
                .as_deref(),
            Some("http://127.0.0.1:19440")
        );
        for (debug_windows, acceptance, normal) in [
            (false, true, true),
            (true, false, true),
            (true, true, false),
        ] {
            assert!(resolve_windows_account_sync_test_endpoint(
                endpoint.clone(), debug_windows, acceptance, normal,
            )
            .is_err());
        }
        for invalid in [
            "https://127.0.0.1:19440",
            "http://0.0.0.0:19440",
            "http://127.0.0.1",
            "http://127.0.0.1:19440/auth/v1/authorize",
            "http://user@127.0.0.1:19440",
            "http://127.0.0.1:19440/?secret=1",
        ] {
            assert!(resolve_windows_account_sync_test_endpoint(
                Some(invalid.to_owned()), true, true, true,
            )
            .is_err());
        }
    }
}

