#[tauri::command]
async fn reconcile_desktop_conversation_sync(
    workspace_id: String,
    conversation_id: String,
    expected_account_email: Option<String>,
    app: AreaAppHandle,
) -> Result<desktop_account_sync_v1::SyncReceipt, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let state = app.area_state()?;
        state.require_external_access()?;
        let _execution = BlockingBusinessExecution::begin(&state.blocking_business_executions)?;
        let (credentials, gateway) = desktop_account_cloud_gateway_for_expected_account(
            desktop_account_credentials(&state),
            state.account_sync_mock_enabled,
            &state.account_auth_generation,
            expected_account_email.as_deref(),
        )?;
        let mut connection =
            open_desktop_workspace_connection(&state.store_paths.root, &state.store_paths.database)?;
        desktop_account_sync_v1::reconcile_unknown_commit(
            &mut connection,
            &credentials,
            &gateway,
            &workspace_id,
            &conversation_id,
        )
    })
    .await
    .map_err(|_| json_error("会话同步核对任务未完成"))?
}

