/// Cloud-list pinning is account presentation data.  It deliberately does not
/// open or mutate a Desktop workspace conversation.
#[tauri::command]
async fn set_desktop_cloud_list_pinned(
    conversation_id: String,
    pinned: bool,
    app: AreaAppHandle,
) -> Result<Vec<String>, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let state = app.area_state()?;
        state.require_external_access()?;
        let _execution = BlockingBusinessExecution::begin(&state.blocking_business_executions)?;
        let (credentials, gateway) = desktop_account_cloud_gateway(
            desktop_account_credentials(&state),
            state.account_sync_mock_enabled,
            &state.account_auth_generation,
        )?;
        let connection =
            open_desktop_workspace_connection(&state.store_paths.root, &state.store_paths.database)?;
        desktop_account_sync_v1::set_cloud_list_pinned(
            &connection,
            &credentials,
            &gateway,
            &conversation_id,
            pinned,
        )
    })
    .await
    .map_err(|_| json_error("云端列表置顶任务未完成"))?
}

fn run_desktop_pending_title_sync_cycle(app: &AreaAppHandle) {
    let Ok(state) = app.area_state() else {
        return;
    };
    let Ok(_execution) = BlockingBusinessExecution::begin(&state.blocking_business_executions) else { return; };
    let Ok(generation) = state.account_auth_generation.lock().map(|value| *value) else { return; };
    let credentials = desktop_account_credentials(&state);
    let Ok(mut connection) = open_desktop_workspace_connection(&state.store_paths.root, &state.store_paths.database) else { return; };
    let Ok(targets) = desktop_account_sync_v1::pending_title_targets(&connection, &credentials) else { return; };
    if targets.is_empty() { return; }
    let Ok((credentials, gateway)) = desktop_account_cloud_gateway(credentials, state.account_sync_mock_enabled, &state.account_auth_generation) else { return; };
    if state.account_auth_generation.lock().map(|value| *value != generation).unwrap_or(true) { return; }
    for (job, workspace, conversation, marker) in targets {
        if credentials.require_current().is_err() { return; }
        let mut result = desktop_account_sync_v1::continue_selected_conversation(&mut connection, &credentials, &gateway, &workspace, &conversation);
        if result.as_ref().is_ok_and(|r| r.status == "UNKNOWN") {
            result = desktop_account_sync_v1::reconcile_unknown_commit(&mut connection, &credentials, &gateway, &workspace, &conversation);
        }
        let _ = sync_state_v1::CredentialStore::with_account_write(&credentials, ||
            desktop_account_sync_v1::finish_pending_title_attempt(&connection, &job, &marker, &result));
    }
}

fn run_desktop_periodic_sync_cycle(app: &AreaAppHandle) {
    let Ok(state) = app.area_state() else {
        return;
    };
    let Ok(_execution) = BlockingBusinessExecution::begin(&state.blocking_business_executions) else { return; };
    let Ok(generation) = state.account_auth_generation.lock().map(|value| *value) else { return; };
    let credentials = desktop_account_credentials(&state);
    let Ok(mut connection) =
        open_desktop_workspace_connection(&state.store_paths.root, &state.store_paths.database)
    else {
        return;
    };
    let Ok(targets) = desktop_account_sync_v1::periodic_targets(&connection, &credentials) else {
        return;
    };
    // Local authorization and selected targets precede any token refresh.
    if targets.is_empty() { return; }
    let Ok((credentials, gateway)) = desktop_account_cloud_gateway(
        credentials,
        state.account_sync_mock_enabled,
        &state.account_auth_generation,
    ) else {
        return;
    };
    if state.account_auth_generation.lock().map(|value| *value != generation).unwrap_or(true) { return; }
    for (workspace_id, conversation_id) in targets {
        if credentials.require_current().is_err() { return; }
        let _ = desktop_account_sync_v1::continue_selected_conversation(
            &mut connection,
            &credentials,
            &gateway,
            &workspace_id,
            &conversation_id,
        );
    }
}

fn wake_desktop_history_knowledge_cycle(app: &AreaAppHandle) {
    let app = app.clone();
    tauri::async_runtime::spawn(async move {
        // Eligibility, the global 12-hour window, checkpoint replay and UNKNOWN suppression
        // all live in the SQLite owner. A wake-up is therefore safe after startup or a timer.
        let _ = run_desktop_history_knowledge_due(app).await;
    });
}

fn wake_desktop_reminder_cycle(app: &AreaAppHandle) {
    let app = app.clone();
    tauri::async_runtime::spawn(async move {
        let _ = run_desktop_reminders_due(app).await;
    });
}

fn record_desktop_background_runtime_all(
    state: &AppState,
    desired: bool,
    installed: bool,
    safe_code: &str,
    label: &str,
) -> Result<desktop_background_runtime_v1::Projection, String> {
    let now = system_now_millis();
    let chat = desktop_background_runtime_v1::record_projection(
        &state.store.lock().map_err(|_| json_error("Desktop store 被锁定"))?.connection()?,
        desired, installed, safe_code, label, now,
    ).map_err(|error| json_error(&error))?;
    if let Some(work) = state.work_area.as_ref() {
        desktop_background_runtime_v1::record_projection(
            &work.store.lock().map_err(|_| json_error("WORK store 被锁定"))?.connection()?,
            desired, installed, safe_code, label, now,
        ).map_err(|error| json_error(&error))?;
    }
    Ok(chat)
}

fn reconcile_desktop_background_runtime(
    app: &tauri::AppHandle,
) -> Result<desktop_background_runtime_v1::Projection, String> {
    let state = app.state::<AppState>();
    if state.startup_mode == DesktopStartupMode::UiSchemaDiagnostic {
        let connection = state
            .store
            .lock()
            .map_err(|_| json_error("Desktop store 被锁定"))?
            .connection()?;
        return desktop_background_runtime_v1::read_projection(&connection)
            .map_err(|error| json_error(&error));
    }
    let (chat_desired, root, acceptance_endpoint) = {
        let store = state
            .store
            .lock()
            .map_err(|_| json_error("Desktop store 被锁定"))?;
        let connection = store.connection()?;
        (
            desktop_background_runtime_v1::desired_enabled(&connection)
                .map_err(|error| json_error(&error))?,
            store.root.clone(),
            state.ordinary_chat_mock_endpoint.clone(),
        )
    };
    let work_desired = state.work_area.as_ref().map(|work| {
        let connection = work.store.lock()
            .map_err(|_| json_error("WORK store 被锁定"))?.connection()?;
        desktop_background_runtime_v1::desired_enabled(&connection)
            .map_err(|error| json_error(&error))
    }).transpose()?.unwrap_or(false);
    let desired = chat_desired || work_desired;
    let runtime_identifier =
        desktop_background_runtime_v1::runtime_bundle_identifier(&app.config().identifier);
    let label = desktop_background_runtime_v1::launch_agent_label(&runtime_identifier)
        .map_err(|error| json_error(&error))?;
    let spec = desktop_background_runtime_v1::LaunchAgentSpec {
        label: label.clone(),
        executable: std::env::current_exe()
            .map_err(|_| json_error("Desktop 后台可执行文件不可用"))?,
        app_root: root,
        acceptance_endpoint,
    };
    let home = app
        .path()
        .home_dir()
        .map_err(|_| json_error("Desktop 用户目录不可用"))?;
    if !desired {
        record_desktop_background_runtime_all(&state, false, false, "NOT_REQUIRED", &label)?;
        let outcome = desktop_background_runtime_v1::reconcile_launch_agent(false, &home, &spec);
        if outcome.is_err() {
            return record_desktop_background_runtime_all(&state, false, true, "REMOVE_FAILED", &label);
        }
        return desktop_background_runtime_v1::read_projection(
            &state
                .store
                .lock()
                .map_err(|_| json_error("Desktop store 被锁定"))?
                .connection()?,
        )
        .map_err(|error| json_error(&error));
    }
    let outcome = desktop_background_runtime_v1::reconcile_launch_agent(desired, &home, &spec);
    let (installed, safe_code) = match outcome {
        Ok(true) => (true, "INSTALLED"),
        Ok(false) => (false, "NOT_REQUIRED"),
        Err(code) if code == "UNSUPPORTED" => (false, "UNSUPPORTED"),
        Err(code) if code == "REMOVE_FAILED" => (true, "REMOVE_FAILED"),
        Err(_) => (false, "INSTALL_FAILED"),
    };
    record_desktop_background_runtime_all(&state, desired, installed, safe_code, &label)
}

#[tauri::command]
fn read_desktop_background_runtime(
    state: AreaState<'_>,
) -> Result<desktop_background_runtime_v1::Projection, String> {
    let connection = state
        .store
        .lock()
        .map_err(|_| json_error("Desktop store 被锁定"))?
        .connection()?;
    desktop_background_runtime_v1::read_projection(&connection).map_err(|error| json_error(&error))
}

async fn run_desktop_background_cycle(app: AreaAppHandle) -> Result<(), String> {
    run_desktop_history_knowledge_due(app.clone()).await?;
    for _ in 0..32 {
        let due = {
            let state = app.area_state()?;
            let connection = state
                .store
                .lock()
                .map_err(|_| json_error("Desktop store 被锁定"))?
                .connection()?;
            let projection = desktop_reminders_v1::read_projection(&connection)
                .map_err(|error| json_error(&error))?;
            let now = system_now_millis();
            projection.plans.iter().any(|plan| {
                plan.status == "ACTIVE"
                    && plan.next_run_at_ms.is_some_and(|next| next <= now)
            })
        };
        if !due {
            break;
        }
        run_desktop_reminders_due(app.clone()).await?;
    }
    let (notifications_enabled, pending) = {
        let state = app.area_state()?;
        let connection = state.store.lock()
            .map_err(|_| json_error("Desktop store 被锁定"))?
            .connection()?;
        let enabled = desktop_app_settings_v1::read(&connection)
            .map_err(|error| json_error(&error))?.product.monitor_notifications;
        let pending = desktop_reminders_v1::pending_notifications(&connection)
            .map_err(|error| json_error(&error))?;
        (enabled, pending)
    };
    for notification in pending.into_iter().take(32) {
        if notifications_enabled {
            send_pending_desktop_reminder_notification(
                notification.run_id.clone(),
                app.clone(),
            )
            .await?;
        } else {
            let state = app.area_state()?;
            let connection = state.store.lock()
                .map_err(|_| json_error("Desktop store 被锁定"))?
                .connection()?;
            desktop_reminders_v1::acknowledge_notification(
                &connection,
                &notification.run_id,
                false,
                Some("SETTING_DISABLED"),
            ).map_err(|error| json_error(&error))?;
        }
    }
    let still_desired = {
        let state = app.area_state()?;
        let connection = state
            .store
            .lock()
            .map_err(|_| json_error("Desktop store 被锁定"))?
            .connection()?;
        desktop_background_runtime_v1::desired_enabled(&connection)
            .map_err(|error| json_error(&error))?
    };
    if !still_desired && app.area() == DesktopDataArea::Chat {
        reconcile_desktop_background_runtime(&app)?;
    }
    Ok(())
}

#[cfg(target_os = "macos")]
const MACOS_WINDOW_RESTORATION_DEFAULTS: [(&str, bool); 2] = [
    ("ApplePersistenceIgnoreState", true),
    ("ApplePersistenceIgnoreStateQuietly", true),
];

#[cfg(target_os = "macos")]
fn disable_macos_native_window_restoration() {
    use objc2_foundation::{NSString, NSUserDefaults};

    // Tauri owns the only main window. Domain state and the separately local window geometry
    // are restored by explicit application owners, never by AppKit crash restoration.
    // AppKit's crash-recovery window restoration can otherwise stop the process before
    // Tauri setup and repeatedly offer a "Reopen" path that Tao cannot safely unwind.
    let defaults = NSUserDefaults::standardUserDefaults();
    for (key, value) in MACOS_WINDOW_RESTORATION_DEFAULTS {
        defaults.setBool_forKey(value, &NSString::from_str(key));
    }
}

#[cfg(not(target_os = "macos"))]
fn disable_macos_native_window_restoration() {}

#[cfg(windows)]
fn show_windows_startup_recovery_error(message: &'static str) {
    // Setup has not finished, so the WebView cannot provide an error page. A
    // modal MessageBox on Tauri's main thread would pump WebView2 messages
    // before AppState exists. Own its message loop on a separate thread.
    if let Ok(dialog) = std::thread::Builder::new()
        .name("nanfeng-startup-recovery-error".into())
        .spawn(move || {
            use windows_sys::Win32::UI::WindowsAndMessaging::{
                MessageBoxW, MB_ICONERROR, MB_OK, MB_SETFOREGROUND,
            };

            // Never put the underlying error or a private path in the dialog.
            let title: Vec<u16> = "南枫 AI · 无法启动"
                .encode_utf16()
                .chain(std::iter::once(0))
                .collect();
            let message: Vec<u16> = message
                .encode_utf16()
                .chain(std::iter::once(0))
                .collect();
            unsafe {
                MessageBoxW(
                    std::ptr::null_mut(),
                    message.as_ptr(),
                    title.as_ptr(),
                    MB_OK | MB_ICONERROR | MB_SETFOREGROUND,
                );
            }
        })
    {
        let _ = dialog.join();
    }
}

