    fn duplicate_conversation_stop_fixture() -> (tempfile::TempDir, DesktopWorkspaceStore, DesktopOrdinaryChatPrepared, DesktopOrdinaryChatPrepared) {
        let (directory,store,first)=imported_store();
        let mut copy=preflight_package(golden()).unwrap();
        copy.exchange["export"]["id"]=json!("export-stop-workspace-copy");
        copy.exchange["export"]["semanticHash"]=json!(semantic_hash(&copy.exchange).unwrap());
        let path=directory.path().join("second-source.nfai-exchange");fs::write(&path,package_exchange(&copy.exchange,&copy.assets).unwrap()).unwrap();
        let staged=store.stage_selected_file(path.to_str().unwrap()).unwrap();
        let second=store.import_staged(ImportArgs{staging_id:staged.staging_id,workspace_title:"第二份相同会话ID的合成导入".into()}).unwrap();
        assert_ne!(first.summary.id,second.summary.id);
        let make=|workspace:&WorkspaceProjection| {
            let conversation=&workspace.exchange["conversations"][0];
            store.prepare_ordinary_chat(DesktopOrdinaryChatSubmitArgs{
                workspace_id:workspace.summary.id.clone(),conversation_id:Some(conversation["id"].as_str().unwrap().into()),project_id:None,
                expected_revision:Some(conversation["revision"].as_u64().unwrap()),text:"synthetic exact workspace Stop".into(),attachment_ids:vec![],model_id:None,tone_override:None,web_search_override:None,egress_authorization:None,
            },Some("http://127.0.0.1:1/chat/completions")).unwrap()
        };
        let a=make(&first);let b=make(&second);assert_eq!(a.projection.conversation_id,b.projection.conversation_id);
        (directory,store,a,b)
    }

    #[test]
    fn ordinary_stop_attempt_stale_identity_preserves_pending_and_running() {
        for running in [false,true] {
            let (_directory,store,a,b)=duplicate_conversation_stop_fixture();
            let store=Mutex::new(store);let active=Arc::new(Mutex::new(BTreeMap::new()));
            let signal=Arc::new(AtomicBool::new(false));
            let guard=if running {begin_prepared_ordinary_chat_execution(&store,&active,&a,signal.clone()).unwrap().0}else{None};
            let args:DesktopOrdinaryChatCancelArgs=serde_json::from_value(json!({"workspaceId":a.projection.workspace_id,"conversationId":a.projection.conversation_id,"expectedAttemptId":"old-completed-stop-attempt"})).unwrap();
            assert!(!cancel_ordinary_chat_for_args(&store,&active,args).unwrap(),"a delayed Stop for an old Attempt must not stop its successor");
            assert!(!signal.load(Ordering::SeqCst));
            let owner=store.lock().unwrap();let connection=owner.connection().unwrap();
            assert_eq!(DesktopWorkspaceStore::ordinary_chat_projection(&connection,&a.projection.attempt_id).unwrap().state,if running{"RUNNING"}else{"PENDING"});
            assert_eq!(DesktopWorkspaceStore::ordinary_chat_projection(&connection,&b.projection.attempt_id).unwrap().state,"PENDING");
            drop(guard);
        }
    }

