    fn continuation_outcome_seed() -> (tempfile::TempDir, DesktopWorkspaceStore, DesktopOrdinaryChatPrepared) {
        let (dir,store,imported)=imported_store();
        let p=call_window_test_prepare(&store,&imported.summary.id);
        store.record_answer_pending(&p.projection,p.context_window_tokens).unwrap();
        let mut reply=call_window_test_reply(&p.model_id);reply.text="durable checkpoint retained before explicit continuation".into();
        store.update_ordinary_chat_message(&p.projection.attempt_id,&reply.text,"UNKNOWN",None,Some(&reply),Some("NETWORK")).unwrap();
        store.complete_ordinary_chat_accounting(&p.projection.attempt_id,&reply).unwrap();
        (dir,store,p)
    }
    #[test]
    fn continuation_outcome_keeps_first_unknown_after_success_and_cold_snapshot() {
        use chat_call_accounting_v1::CallOutcomeState;
        let (_dir,store,p)=continuation_outcome_seed();let id=&p.projection.attempt_id;
        let retry=store.prepare_ordinary_chat_retry(id,Some("http://127.0.0.1:1/chat/completions")).unwrap();
        let ledger=usage_ledger_v1::Ledger::open(&store.root.join("usage-ledger")).unwrap();
        let pending=ledger.entry(&format!("usage-{id}-answer-0-pending")).unwrap().unwrap();
        let original=ledger.call_outcome(&pending).unwrap().expect("first physical call must keep its UNKNOWN outcome");
        assert_eq!(original.state,CallOutcomeState::Unknown);assert_eq!(original.safe_error_code.as_deref(),Some("NETWORK"));
        let quantities=ledger.entries_for_execution(id).unwrap();drop(ledger);
        store.record_answer_pending(&retry.projection,retry.context_window_tokens).unwrap();
        let reply=call_window_test_reply(&retry.model_id);
        store.update_ordinary_chat_message(id,&reply.text,"COMPLETE",None,Some(&reply),None).unwrap();
        store.complete_ordinary_chat_accounting(id,&reply).unwrap();
        let root=store.root.clone();drop(store);let store=DesktopWorkspaceStore::open(root).unwrap();
        let ledger=usage_ledger_v1::Ledger::open(&store.root.join("usage-ledger")).unwrap();
        assert_eq!(ledger.call_outcome(&pending).unwrap(),Some(original.clone()));
        for row in quantities {assert_eq!(ledger.entry(&row.entry_id).unwrap(),Some(row));}
        let mut wrong=pending.clone();wrong.branch_leaf_message_id="wrong-leaf".into();assert!(ledger.call_outcome(&wrong).is_err());
        let mut conflict=original;conflict.state=CallOutcomeState::Failed;assert!(ledger.append_call_outcome(&pending,&conflict).is_err());
        drop(ledger);usage_ledger_v1::Ledger::validate_recovery_snapshot(&store.root.join("usage-ledger/usage-ledger-v1.sqlite3")).unwrap();
    }
    #[test]
    fn continuation_outcome_write_failure_blocks_retry_without_changing_attempt() {
        let (_dir,store,p)=continuation_outcome_seed();let id=&p.projection.attempt_id;
        let before=DesktopWorkspaceStore::ordinary_chat_projection(&store.connection().unwrap(),id).unwrap();
        let db=rusqlite::Connection::open(store.root.join("usage-ledger/usage-ledger-v1.sqlite3")).unwrap();
        db.execute_batch("CREATE TRIGGER reject_continuation_outcome BEFORE INSERT ON usage_ledger_call_outcomes BEGIN SELECT RAISE(ABORT,'synthetic blocked');END;").unwrap();
        assert!(store.prepare_ordinary_chat_retry(id,Some("http://127.0.0.1:1/chat/completions")).is_err(),"no new continuation may replace an unrecorded terminal outcome");
        let after=DesktopWorkspaceStore::ordinary_chat_projection(&store.connection().unwrap(),id).unwrap();
        assert_eq!(serde_json::to_value(&before).unwrap(),serde_json::to_value(&after).unwrap());
        db.execute_batch("DROP TRIGGER reject_continuation_outcome;").unwrap();
        let retry=store.prepare_ordinary_chat_retry(id,Some("http://127.0.0.1:1/chat/completions")).unwrap();
        assert_eq!(retry.projection.retry_count,1);assert_ne!(retry.projection.assistant_message_id,before.assistant_message_id);
    }

    #[test]
    fn continuation_reverification_uses_new_call_and_keeps_failed_outcome_after_cold() {
        use chat_call_accounting_v1::CallOutcomeState;
        for code in ["WEB_SEARCH_NO_SOURCES","WEB_SEARCH_NO_VERIFIED_SOURCES","WEB_SEARCH_SCOPE_INCOMPLETE"] {
            let (_dir,store,imported)=imported_store();
            let first=call_window_test_prepare(&store,&imported.summary.id);let id=&first.projection.attempt_id;
            store.record_answer_pending(&first.projection,first.context_window_tokens).unwrap();
            let mut reply=call_window_test_reply(&first.model_id);reply.text="LEGACY_UNVERIFIED_SAVED_TEXT".into();
            store.update_ordinary_chat_message(id,&reply.text,"FAILED",None,Some(&reply),Some(code)).unwrap();
            store.complete_ordinary_chat_accounting(id,&reply).unwrap();
            let retry=store.prepare_ordinary_chat_retry(id,Some("http://127.0.0.1:1/chat/completions")).unwrap();
            assert_ne!(retry.idempotency_key,first.idempotency_key,"An explicit material regeneration cannot replay the old physical answer");
            assert_eq!(chat_continuation_v1::checkpoint_text(&retry.messages),"");
            assert!(!retry.messages.to_string().contains("LEGACY_UNVERIFIED_SAVED_TEXT"));
            let users=|messages:&Value|messages.as_array().unwrap().iter().filter(|m|m["role"]=="user").cloned().collect::<Vec<_>>();
            assert_eq!(users(&retry.messages),users(&first.messages),"Regeneration retains the complete original user input");
            let ledger=usage_ledger_v1::Ledger::open(&store.root.join("usage-ledger")).unwrap();
            let pending=ledger.entry(&format!("usage-{id}-answer-0-pending")).unwrap().unwrap();
            let original=ledger.call_outcome(&pending).unwrap().expect("Previous answer failure must remain attributable");
            assert_eq!(original.state,CallOutcomeState::Failed);assert_eq!(original.safe_error_code.as_deref(),Some(code));
            let quantities=ledger.entries_for_execution(id).unwrap();drop(ledger);
            store.record_answer_pending(&retry.projection,retry.context_window_tokens).unwrap();
            reply.text="REGENERATED_FROM_ORIGINAL".into();
            store.update_ordinary_chat_message(id,&reply.text,"COMPLETE",None,Some(&reply),None).unwrap();
            store.complete_ordinary_chat_accounting(id,&reply).unwrap();
            let root=store.root.clone();drop(store);let store=DesktopWorkspaceStore::open(root).unwrap();
            let ledger=usage_ledger_v1::Ledger::open(&store.root.join("usage-ledger")).unwrap();
            assert_eq!(ledger.call_outcome(&pending).unwrap(),Some(original));
            for row in quantities {assert_eq!(ledger.entry(&row.entry_id).unwrap(),Some(row));}
            let exchange:String=store.connection().unwrap().query_row("SELECT exchange_json FROM workspace_exchange WHERE workspace_id=?1",[&imported.summary.id],|row|row.get(0)).unwrap();
            assert!(exchange.contains("LEGACY_UNVERIFIED_SAVED_TEXT"),"Old failed branch remains inspectable");
        }
    }

