    fn ordinary_unsupported_tool_accounting_contract(recover_before_settlement: bool) {
        let (_dir, store, imported) = imported_store();
        let prepared = store.prepare_ordinary_chat(DesktopOrdinaryChatSubmitArgs {
            workspace_id: imported.summary.id.clone(), conversation_id: None, project_id: None,
            expected_revision: None, text: "synthetic unsupported tool".into(), attachment_ids: vec![],
            model_id: None, tone_override: None, web_search_override: Some(false), egress_authorization: None,
        }, Some("http://127.0.0.1:1/chat/completions")).unwrap();
        let id = &prepared.projection.attempt_id;
        store.record_answer_pending(&prepared.projection, prepared.context_window_tokens).unwrap();
        let completed = desktop_ordinary_chat_v1::Completed {
            text: String::new(), reasoning: None,
            usage: desktop_ordinary_chat_v1::Usage {
                input_tokens: Some(29), output_tokens: Some(11), cached_input_tokens: Some(7),
                ..Default::default()
            },
            reported_cost_micros: Some(17), actual_model_id: Some("fixture-actual".into()),
            web_search_verified: false, native_sources: vec![], elapsed_ms: 7,
        };
        store.update_ordinary_chat_message(id, "", "FAILED", None, Some(&completed), Some("TOOL_CALL_UNSUPPORTED")).unwrap();
        if !recover_before_settlement {
            let settled = store.complete_ordinary_chat_accounting(id, &completed).expect("measured tool rejection must settle");
            assert_eq!(settled.state, "FAILED");
        }
        let root = store.root.clone();
        drop(store);
        let reopened = DesktopWorkspaceStore::open(root.clone()).unwrap();
        reopened.recover_ordinary_chat_accounting().unwrap();
        let projection = DesktopWorkspaceStore::ordinary_chat_projection(&reopened.connection().unwrap(), id).unwrap();
        assert_eq!(projection.state, "FAILED");
        assert_eq!(projection.safe_error_code.as_deref(), Some("TOOL_CALL_UNSUPPORTED"));
        let ledger = usage_ledger_v1::Ledger::open(&root.join("usage-ledger")).unwrap();
        let rows = ledger.entries_for_execution(id).unwrap();
        let finals: Vec<_> = rows.iter().filter(|e| e.kind == usage_ledger_v1::Kind::FinalMeasured).collect();
        assert_eq!(finals.len(), 1, "cold recovery must retain one measured final receipt");
        let final_entry = (*finals[0]).clone();
        assert_eq!((final_entry.input_tokens, final_entry.output_tokens, final_entry.cached_input_tokens), (Some(29), Some(11), Some(7)));
        assert_eq!(final_entry.charge_micros, Some(17));
        assert_eq!(final_entry.currency_code.as_deref(), Some("USD"));
        assert_eq!(final_entry.cost_source.as_deref(), Some("PROVIDER_RESPONSE"));
        assert_eq!(final_entry.actual_model_id.as_deref(), Some("fixture-actual"));
        drop(ledger);
        reopened.complete_ordinary_chat_accounting(id, &completed).unwrap();
        reopened.recover_ordinary_chat_accounting().unwrap();
        let replayed = usage_ledger_v1::Ledger::open(&root.join("usage-ledger")).unwrap();
        let finals: Vec<_> = replayed.entries_for_execution(id).unwrap().into_iter()
            .filter(|e| e.kind == usage_ledger_v1::Kind::FinalMeasured).collect();
        assert_eq!(finals, vec![final_entry]);
        let count: i64 = reopened.connection().unwrap().query_row("SELECT count(*) FROM desktop_ordinary_chat_attempts", [], |row| row.get(0)).unwrap();
        assert_eq!(count, 1, "accounting recovery cannot resend or create an Attempt");
        let projected = reopened.workspace_projection(&imported.summary.id).unwrap();
        let message = projected.exchange["conversations"].as_array().unwrap().iter()
            .flat_map(|c| c["messages"].as_array().unwrap())
            .find(|m| m["id"] == prepared.projection.assistant_message_id).unwrap();
        assert_ne!(message["delivery"], "COMPLETE");
        assert_eq!(message["usage"]["inputTokens"], 29);
        assert_eq!(message["actualModelId"], "fixture-actual");
    }

    #[test]
    fn ordinary_unsupported_tool_measured_failure_settles_once() {
        ordinary_unsupported_tool_accounting_contract(false);
    }

    #[test]
    fn ordinary_unsupported_tool_measured_failure_recovers_after_reopen() {
        ordinary_unsupported_tool_accounting_contract(true);
    }

