    #[test]
    fn ordinary_cancellation_failed_worker_preserves_sibling_and_detached_transport() {
        let active = Arc::new(Mutex::new(BTreeMap::new()));
        let sibling_signal = Arc::new(AtomicBool::new(false));
        let sibling = OrdinaryCancellationRegistration::begin(
            &active, "conversation".into(), sibling_signal.clone(),
        ).unwrap();
        let waiter = Arc::new(OrdinaryCancellationRegistration::begin(
            &active, "conversation".into(), Arc::new(AtomicBool::new(false)),
        ).unwrap());
        let registration = waiter.clone();
        let (release, wait) = std::sync::mpsc::channel();
        let worker = std::thread::spawn(move || -> Result<(), String> {
            let _registration = registration;
            wait.recv().unwrap();
            Err("synthetic completion write denied".into())
        });
        drop(waiter);
        assert_eq!(active.lock().unwrap()["conversation"].len(), 2);
        release.send(()).unwrap();
        assert!(worker.join().unwrap().is_err());
        let signals = active.lock().unwrap()["conversation"].clone();
        assert_eq!(signals.len(), 1);
        assert!(Arc::ptr_eq(&signals[0], &sibling_signal));
        drop(sibling);
        assert!(active.lock().unwrap().is_empty());
    }

    #[test]
    fn background_cancellation_releases_after_completion_error_and_unwind() {
        let active = Arc::new(Mutex::new(BTreeMap::new()));
        let fail = || -> Result<(), String> {
            let _registration = BackgroundCancellationRegistration::begin(
                &active, "attempt".into(), Arc::new(AtomicBool::new(false)),
            )?;
            assert_eq!(active.lock().unwrap().len(), 1);
            Err("synthetic completion write denied".into())
        };
        assert!(fail().is_err());
        assert!(active.lock().unwrap().is_empty());
        assert!(std::panic::catch_unwind(|| {
            let _registration = BackgroundCancellationRegistration::begin(
                &active, "attempt".into(), Arc::new(AtomicBool::new(false)),
            ).unwrap();
            panic!("synthetic transport unwind");
        }).is_err());
        assert!(active.lock().unwrap().is_empty());
    }

    #[test]
    fn background_cancellation_waiter_drop_keeps_transport_visible() {
        let active = Arc::new(Mutex::new(BTreeMap::new()));
        let signal = Arc::new(AtomicBool::new(false));
        let waiter = Arc::new(BackgroundCancellationRegistration::begin(
            &active, "attempt".into(), signal.clone(),
        ).unwrap());
        let registration = waiter.clone();
        let worker_signal = signal.clone();
        let (release, wait) = std::sync::mpsc::channel();
        let worker = std::thread::spawn(move || {
            let _registration = registration;
            wait.recv().unwrap();
            assert!(worker_signal.load(Ordering::SeqCst));
        });
        drop(waiter);
        active.lock().unwrap().get("attempt").unwrap().store(true, Ordering::SeqCst);
        assert_eq!(active.lock().unwrap().len(), 1);
        release.send(()).unwrap();
        worker.join().unwrap();
        assert!(active.lock().unwrap().is_empty());
    }

    #[test]
    fn background_cancellation_old_attempt_cannot_remove_replacement() {
        let active = Arc::new(Mutex::new(BTreeMap::new()));
        let old = BackgroundCancellationRegistration::begin(
            &active, "plan".into(), Arc::new(AtomicBool::new(false)),
        ).unwrap();
        let signal = Arc::new(AtomicBool::new(false));
        let current = BackgroundCancellationRegistration::begin(
            &active, "plan".into(), signal.clone(),
        ).unwrap();
        drop(old);
        assert!(Arc::ptr_eq(active.lock().unwrap().get("plan").unwrap(), &signal));
        assert!(!signal.load(Ordering::SeqCst));
        drop(current);
        assert!(active.lock().unwrap().is_empty());
    }

    #[test]
    fn blocking_business_execution_tracks_worker_until_return_and_unwind() {
        let active = Arc::new(Mutex::new(0));
        let execution = BlockingBusinessExecution::register(&active).unwrap();
        let (release, wait) = std::sync::mpsc::channel();
        let worker = std::thread::spawn(move || {
            let _execution = execution;
            wait.recv().unwrap();
        });
        assert_eq!(*active.lock().unwrap(), 1);
        release.send(()).unwrap();
        worker.join().unwrap();
        assert_eq!(*active.lock().unwrap(), 0);
        let guard = BlockingBusinessExecution::register(&active).unwrap();
        assert!(std::panic::catch_unwind(move || {
            let _guard = guard;
            panic!("synthetic worker failure");
        }).is_err());
        assert_eq!(*active.lock().unwrap(), 0);
    }

    #[test]
    fn cancelled_waiter_does_not_release_a_detached_business_worker() {
        let active = Arc::new(Mutex::new(0));
        let waiter = Arc::new(BlockingBusinessExecution::register(&active).unwrap());
        let execution = waiter.clone();
        let (release, wait) = std::sync::mpsc::channel();
        let worker = std::thread::spawn(move || {
            let _execution = execution;
            wait.recv().unwrap();
        });
        drop(waiter);
        assert_eq!(*active.lock().unwrap(), 1);
        release.send(()).unwrap();
        worker.join().unwrap();
        assert_eq!(*active.lock().unwrap(), 0);
    }

    #[test]
    fn p6k_official_occurrences_keep_exact_messages_and_deduplicate_metadata_pointer() {
        let export = json!([{"id":"conv-a","title":"Synthetic","create_time":1,"update_time":2,"mapping":{
            "m-user":{"parent":null,"message":{"author":{"role":"user"},"content":{"parts":["look",{"asset_pointer":"file-service://file-a"}]},"metadata":{"attachments":[{"id":"file-a","name":"photo.png"},{"id":"file-missing","name":"lost.pdf"}]}}},
            "m-assistant":{"parent":"m-user","message":{"author":{"role":"assistant"},"content":{"parts":["reply"]},"metadata":{"attachments":[{"id":"file-a","name":"photo.png"}]}}}
        }}]);
        let bytes = serde_json::to_vec(&export).unwrap();
        let present = BTreeSet::from(["file-a.dat".to_owned()]);
        let occurrences = p6k_official_occurrences_from_json(&bytes, &present).unwrap();
        assert_eq!(occurrences.len(), 3);
        assert_eq!(occurrences.iter().filter(|item| item.present).count(), 2);
        assert_eq!(occurrences.iter().filter(|item| item.entry_name == "file-a.dat").count(), 2);
        assert!(occurrences.iter().any(|item| item.source_message_id == "m-user" && item.entry_name == "file-a.dat" && item.display_name == "photo.png"));
        assert!(occurrences.iter().any(|item| item.source_message_id == "m-assistant" && item.entry_name == "file-a.dat"));
        assert!(occurrences.iter().any(|item| item.source_message_id == "m-user" && item.entry_name == "file-missing.dat" && !item.present));
        assert!(parse_p6k_chatgpt_export_with_limit(&bytes, 1024 * 1024, &present).unwrap()[0].is_ok());
        assert!(parse_chatgpt_export_with_limit(&bytes, 1024 * 1024).unwrap()[0].is_err());
    }

