    #[test]
    fn v1_export_roundtrips_legacy_local_attachment_without_classification() {
        let original = preflight_package(golden()).unwrap();
        let mut local = original.exchange;
        let bytes = b"W14 synthetic legacy local attachment".to_vec();
        let digest = sha256(&bytes);
        let entry = format!("assets/{digest}");
        local["conversations"][0]["messages"][1]["blocks"] = json!([{
            "kind":"ASSET_REF", "ordinal":0, "asset":{
                "id":"attachment-legacy-export", "entry":entry,
                "mimeType":"text/plain", "displayName":"legacy.txt",
                "byteCount":bytes.len(), "sha256":digest
            }
        }]);
        local["export"]["semanticHash"] = json!(semantic_hash(&local).unwrap());
        let unchanged = local.clone();
        let portable = portable_exchange_v1(&local).unwrap();
        assert_eq!(local, unchanged, "export must not mutate local history");
        assert_eq!(portable["conversations"][0]["messages"][1]["blocks"][0]["asset"]["classification"], "NORMAL");
        let assets = BTreeMap::from([(entry, bytes)]);
        let package = package_exchange(&portable, &assets).unwrap();
        let restored = preflight_package(package).unwrap();
        assert_eq!(restored.exchange, portable);
        assert_eq!(restored.assets, assets);
        local["export"]["sensitivity"] = json!("HIGH_SENSITIVE");
        let inherited = portable_exchange_v1(&local).unwrap();
        assert_eq!(inherited["conversations"][0]["messages"][1]["blocks"][0]["asset"]["classification"], "HIGH_SENSITIVE");
        local["conversations"][0]["messages"][1]["blocks"][0]["asset"]["classification"] = json!("HIGH_SENSITIVE");
        let sensitive = portable_exchange_v1(&local).unwrap();
        assert_eq!(sensitive["conversations"][0]["messages"][1]["blocks"][0]["asset"]["classification"], "HIGH_SENSITIVE");
        local["conversations"][0]["messages"][1]["blocks"][0]["asset"]["classification"] = json!("INVALID");
        assert!(portable_exchange_v1(&local).is_err());
    }

