    #[test]
    fn upstream_schema_43_area_identity_is_not_rewritten_as_windows_draft_schema() {
        let directory = tempdir().unwrap();
        let root = directory.path().join("app-data");
        let store = DesktopWorkspaceStore::open(root.clone()).unwrap();
        let connection = store.connection().unwrap();
        connection
            .execute_batch(
                "ALTER TABLE desktop_conversation_drafts_v1 DROP COLUMN model_id;
                 ALTER TABLE desktop_conversation_drafts_v1 DROP COLUMN tone_override;
                 ALTER TABLE desktop_conversation_drafts_v1 DROP COLUMN web_search_override;
                 CREATE TABLE desktop_data_area_v1(id INTEGER PRIMARY KEY CHECK(id=1), area TEXT NOT NULL, split_done INTEGER NOT NULL DEFAULT 0);
                 INSERT INTO desktop_data_area_v1(id,area,split_done) VALUES(1,'CHAT',0);
                 PRAGMA user_version=43;",
            )
            .unwrap();
        drop(connection);
        drop(store);

        let error = DesktopWorkspaceStore::open(root.clone()).err().expect("must reject area schema");
        assert!(error.contains("区域") || error.contains("分叉"), "{error}");
        let unchanged = Connection::open(root.join("workspace.sqlite3")).unwrap();
        let version: u32 = unchanged.pragma_query_value(None, "user_version", |row| row.get(0)).unwrap();
        assert_eq!(version, 43);
        let columns: i64 = unchanged
            .query_row(
                "SELECT COUNT(*) FROM pragma_table_info('desktop_conversation_drafts_v1') WHERE name IN ('model_id','tone_override','web_search_override')",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(columns, 0);
        let area: String = unchanged.query_row("SELECT area FROM desktop_data_area_v1 WHERE id=1", [], |row| row.get(0)).unwrap();
        assert_eq!(area, "CHAT");
    }

