    #[test]
    fn reminder_route_rejection_reports_failed_terminal_persistence() {
        let directory = tempdir().unwrap();
        let store = DesktopWorkspaceStore::open(directory.path().join("app-data")).unwrap();
        let workspace = store.ensure_local_workspace().unwrap();
        let connection = store.connection().unwrap();
        let now = system_now_millis();
        connection.execute("INSERT INTO desktop_reminder_drafts_v1(draft_id,workspace_id,status,title,instruction,schedule_kind,anchor_local,timezone_id,missed_policy,retry_count,created_at_ms,updated_at_ms) VALUES('route-reject-draft',?1,'CONFIRMED','synthetic','synthetic','ONCE','2026-09-26T12:00','Asia/Shanghai','RUN_ONCE',0,?2,?2)", params![workspace.summary.id, now]).unwrap();
        connection.execute("INSERT INTO desktop_reminder_plans_v1(plan_id,source_draft_id,workspace_id,title,instruction,schedule_kind,anchor_local,timezone_id,missed_policy,status,next_run_at_ms,created_at_ms,updated_at_ms) VALUES('route-reject-plan','route-reject-draft',?1,'synthetic','synthetic','ONCE','2026-09-26T12:00','Asia/Shanghai','RUN_ONCE','ACTIVE',?2,?3,?3)", params![workspace.summary.id, now - 1000, now]).unwrap();
        connection.execute_batch("CREATE TRIGGER reject_reminder_failure BEFORE UPDATE ON desktop_reminder_runs_v1 WHEN NEW.status='FAILED' BEGIN SELECT RAISE(ABORT,'synthetic-only'); END;").unwrap();
        let error = store.prepare_due_reminder(None).err().unwrap();
        assert!(error.contains("计划失败状态未保存"), "{error}");
        let status: String = connection.query_row("SELECT status FROM desktop_reminder_runs_v1 WHERE plan_id='route-reject-plan'", [], |row| row.get(0)).unwrap();
        assert_eq!(status, "RUNNING");
        connection.execute_batch("DROP TRIGGER reject_reminder_failure;").unwrap();
        drop(connection);
        drop(store);
        let reopened = DesktopWorkspaceStore::open(directory.path().join("app-data")).unwrap();
        let connection = reopened.connection().unwrap();
        let status: String = connection.query_row("SELECT status FROM desktop_reminder_runs_v1 WHERE plan_id='route-reject-plan'", [], |row| row.get(0)).unwrap();
        assert_eq!(status, "UNKNOWN");
        assert!(reopened.prepare_due_reminder(None).unwrap().is_none());
        assert_eq!(connection.query_row("SELECT count(*) FROM desktop_reminder_runs_v1 WHERE plan_id='route-reject-plan'", [], |row| row.get::<_, i64>(0)).unwrap(), 1);
    }

    #[test]
    fn reminder_pause_between_prepare_and_registration_cancels_before_transport() {
        let directory = tempdir().unwrap();
        let root = directory.path().join("app-data");
        let store = DesktopWorkspaceStore::open(root.clone()).unwrap();
        let workspace = store.ensure_local_workspace().unwrap();
        let connection = store.connection().unwrap();
        let now = system_now_millis();
        connection.execute("INSERT INTO desktop_reminder_drafts_v1(draft_id,workspace_id,status,title,instruction,schedule_kind,anchor_local,timezone_id,missed_policy,retry_count,created_at_ms,updated_at_ms) VALUES('pause-gap-draft',?1,'CONFIRMED','synthetic','synthetic','ONCE','2026-09-26T12:00','Asia/Shanghai','RUN_ONCE',0,?2,?2)", params![workspace.summary.id, now]).unwrap();
        connection.execute("INSERT INTO desktop_reminder_plans_v1(plan_id,source_draft_id,workspace_id,title,instruction,schedule_kind,anchor_local,timezone_id,missed_policy,status,next_run_at_ms,created_at_ms,updated_at_ms) VALUES('pause-gap-plan','pause-gap-draft',?1,'synthetic','synthetic','ONCE','2026-09-26T12:00','Asia/Shanghai','RUN_ONCE','ACTIVE',?2,?3,?3)", params![workspace.summary.id, now - 1000, now]).unwrap();
        let prepared = store.prepare_due_reminder(Some("http://127.0.0.1:1/chat/completions")).unwrap().unwrap();
        let active = Arc::new(Mutex::new(BTreeMap::new()));
        assert!(active.lock().unwrap().is_empty());
        desktop_reminders_v1::set_paused(&connection, "pause-gap-plan", true, now + 1).unwrap();
        let store = Mutex::new(store);
        let signal = Arc::new(AtomicBool::new(false));
        let registration = register_prepared_reminder_cancellation(&store, &active, &prepared, signal.clone()).unwrap();
        assert!(signal.load(Ordering::SeqCst), "暂停已保存，迟到登记不能启动新的外部请求");
        let result = tauri::async_runtime::block_on(desktop_ordinary_chat_v1::execute_streaming(
            desktop_ordinary_chat_v1::TransportRequest {
                endpoint: prepared.endpoint.clone(), provider_id: prepared.provider_id.clone(),
                model_id: prepared.model_id.clone(), messages: json!([]),
                idempotency_key: prepared.reservation.attempt_id.clone(), max_output_tokens: 4096,
                web_search_route: "OPENROUTER_SERVER_TOOL".into(), structured_json: false, disable_thinking: false,

                grounded_answer: false,
                explicit_search_query: None,
            }, Zeroizing::new(vec![]), signal, |_| panic!("取消后不得收到流"),
        ));
        assert!(matches!(result, Err(desktop_ordinary_chat_v1::Failure::Cancelled)));
        desktop_reminders_v1::fail_run(&connection, &prepared.reservation, Some(&prepared.provider_id), Some(&prepared.model_id), false, "CANCELLED", now + 2).unwrap();
        drop(registration);
        assert!(active.lock().unwrap().is_empty());
        drop(connection);
        drop(store);
        let reopened = DesktopWorkspaceStore::open(root).unwrap();
        let connection = reopened.connection().unwrap();
        assert_eq!(desktop_reminders_v1::read_plan(&connection, "pause-gap-plan").unwrap().status, "PAUSED");
        assert_eq!(connection.query_row("SELECT status || ':' || safe_error_code FROM desktop_reminder_runs_v1 WHERE plan_id='pause-gap-plan'", [], |row| row.get::<_, String>(0)).unwrap(), "FAILED:CANCELLED");
        assert!(reopened.prepare_due_reminder(Some("http://127.0.0.1:1/chat/completions")).unwrap().is_none());
    }

    #[test]
    fn c07_c12_fixture_persists_reminder_transcription_and_redacted_call_states() {
        let directory = tempdir().unwrap();
        let root = directory.path().join("app-data");
        let store = DesktopWorkspaceStore::open(root.clone()).unwrap();
        seed_c07_c12_offline_acceptance(&store).unwrap();
        assert_eq!(
            fs::read(root.join(C07_C12_ACCEPTANCE_COMPLETE_MARKER)).unwrap(),
            C07_C12_ACCEPTANCE_COMPLETE_BYTES
        );

        let reminders =
            desktop_reminders_v1::read_projection(&store.connection().unwrap()).unwrap();
        assert_eq!(reminders.plans.len(), 4);
        for status in ["ACTIVE", "PAUSED", "FAILED", "COMPLETED"] {
            assert!(reminders.plans.iter().any(|item| item.status == status));
        }
        let transcription = desktop_transcription_v1::read_state(
            &store.database,
            Some(C07_C12_ACCEPTANCE_WORKSPACE_ID),
        )
        .unwrap();
        for state in ["TRANSCRIBING", "FAILED", "COMPLETED"] {
            assert!(transcription.tasks.iter().any(|item| item.state == state));
        }
        assert_eq!(store.ordinary_chat_context_records().unwrap().len(), 1);
        assert_eq!(store.ordinary_chat_diagnostic_records().unwrap().len(), 1);
        let usage = usage_ledger_v1::Ledger::open(&root.join("usage-ledger"))
            .unwrap()
            .all_entries()
            .unwrap();
        assert_eq!(usage.len(), 1);
        assert_eq!(usage[0].input_tokens, Some(1_240));
        assert_eq!(usage[0].output_tokens, Some(680));
        drop(store);

        let reopened = DesktopWorkspaceStore::open(root).unwrap();
        seed_c07_c12_offline_acceptance(&reopened).unwrap();
        let readback = desktop_transcription_v1::read_state(
            &reopened.database,
            Some(C07_C12_ACCEPTANCE_WORKSPACE_ID),
        )
        .unwrap();
        assert!(readback
            .tasks
            .iter()
            .any(|item| item.state == "RECOVERY_REQUIRED"));
        assert!(readback.tasks.iter().any(|item| item.state == "FAILED"));
        assert!(readback.tasks.iter().any(|item| item.state == "COMPLETED"));
        assert_eq!(
            reopened
                .connection()
                .unwrap()
                .query_row("PRAGMA integrity_check", [], |row| row.get::<_, String>(0))
                .unwrap(),
            "ok"
        );
    }

    #[test]
    fn c13_fixture_owns_lifecycle_state_and_preserves_mutations_on_reopen() {
        let directory = tempdir().unwrap();
        let root = directory.path().join("app-data");
        let store = DesktopWorkspaceStore::open(root.clone()).unwrap();
        seed_c13_conversation_lifecycle_acceptance(&store).unwrap();

        let projection = store
            .workspace_projection(C13_ACCEPTANCE_WORKSPACE_ID)
            .unwrap();
        let conversations = projection.exchange["conversations"].as_array().unwrap();
        assert_eq!(conversations.len(), 3);
        let favorite = conversations
            .iter()
            .find(|item| item["title"] == "C13 Favorite")
            .unwrap();
        let archived = conversations
            .iter()
            .find(|item| item["title"] == "C13 Archived")
            .unwrap();
        let recycle = conversations
            .iter()
            .find(|item| item["title"] == "C13 Recycle")
            .unwrap();
        assert_ne!(favorite["archived"], Value::Bool(true));
        assert_eq!(archived["archived"], Value::Bool(true));
        assert_ne!(archived["deleted"], Value::Bool(true));
        assert_eq!(recycle["archived"], Value::Bool(true));
        assert_eq!(recycle["deleted"], Value::Bool(true));
        assert_eq!(
            desktop_app_settings_v1::read_favorite_conversation_ids(
                &store.connection().unwrap(),
                C13_ACCEPTANCE_WORKSPACE_ID,
            )
            .unwrap(),
            vec![favorite["id"].as_str().unwrap().to_owned()]
        );

        let restored = store
            .mutate_domain(DomainMutationArgs {
                intent_id: "c13-test-restore-archived".into(),
                workspace_id: C13_ACCEPTANCE_WORKSPACE_ID.into(),
                entity: "conversation".into(),
                action: "restore".into(),
                object_id: Some(archived["id"].as_str().unwrap().to_owned()),
                expected_revision: archived["revision"].as_u64(),
                fields: json!({}),
            })
            .unwrap();
        assert!(restored.revision > archived["revision"].as_u64().unwrap());
        let purge = store
            .permanently_delete_conversation(DesktopConversationPurgeArgs {
                workspace_id: C13_ACCEPTANCE_WORKSPACE_ID.into(),
                conversation_id: recycle["id"].as_str().unwrap().to_owned(),
                expected_revision: recycle["revision"].as_u64().unwrap(),
            })
            .unwrap();
        assert_eq!(purge.conversation_id, recycle["id"].as_str().unwrap());
        drop(store);

        let reopened = DesktopWorkspaceStore::open(root).unwrap();
        seed_c13_conversation_lifecycle_acceptance(&reopened).unwrap();
        let readback = reopened
            .workspace_projection(C13_ACCEPTANCE_WORKSPACE_ID)
            .unwrap();
        let conversations = readback.exchange["conversations"].as_array().unwrap();
        assert_eq!(
            conversations.len(),
            2,
            "reopen must not reseed the purged fixture"
        );
        assert_eq!(
            conversations
                .iter()
                .find(|item| item["title"] == "C13 Archived")
                .unwrap()["archived"],
            Value::Bool(false),
            "restore must survive reopen"
        );
        assert!(conversations
            .iter()
            .all(|item| item["title"] != "C13 Recycle"));
        assert_eq!(
            reopened
                .connection()
                .unwrap()
                .query_row("PRAGMA integrity_check", [], |row| row.get::<_, String>(0),)
                .unwrap(),
            "ok"
        );
    }

