    #[test]
    fn p6k_duplicate_source_message_is_rejected_before_official_attachment_link_and_reopen() {
        let (directory, store, imported) = imported_store();
        let before = store.workspace_projection(&imported.summary.id).unwrap().exchange;
        let original_assets: i64 = store.connection().unwrap().query_row(
            "SELECT COUNT(*) FROM desktop_conversation_attachments WHERE workspace_id=?1",
            [&imported.summary.id], |row| row.get(0),
        ).unwrap();
        let source = directory.path().join("exact-occurrence.zip");
        let png = base64::engine::general_purpose::STANDARD.decode("iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAIAAAD91JpzAAAAFElEQVR4nGP8z8DAwMDAxMDAwMDAAAANHQEDasKb6QAAAABJRU5ErkJggg==").unwrap();
        let export = json!([
            {"id":"source-a","title":"A","create_time":1,"update_time":2,"mapping":{
                "shared-message":{"parent":null,"message":{"author":{"role":"user"},"content":{"parts":["A text"]}}}
            }},
            {"id":"source-b","title":"B","create_time":1,"update_time":2,"mapping":{
                "shared-message":{"parent":null,"message":{"author":{"role":"user"},"content":{"parts":["B text"]},"metadata":{"attachments":[{"id":"file-exact","name":"exact.png"}]}}}
            }}
        ]);
        let mut writer = ZipWriter::new(fs::File::create(&source).unwrap());
        writer.start_file("conversations.json", SimpleFileOptions::default()).unwrap();
        writer.write_all(&serde_json::to_vec(&export).unwrap()).unwrap();
        writer.start_file("file-exact.dat", SimpleFileOptions::default()).unwrap();
        writer.write_all(&png).unwrap();
        writer.finish().unwrap();
        let task = store.stage_p6k_zip_import_selected(P6kZipImportSelectionArgs {
            workspace_id: imported.summary.id.clone(), provider: "CHATGPT".into(),
            selected_path: source.to_string_lossy().into_owned(),
        }).unwrap();
        assert_eq!(task.imported_count, 0);
        assert_eq!(task.failed_count, 2);
        let check = |store: &DesktopWorkspaceStore| {
            let projection = store.workspace_projection(&imported.summary.id).unwrap();
            assert_eq!(projection.exchange, before);
            assert!(projection.exchange["conversations"].as_array().unwrap().iter()
                .all(|conversation| conversation["title"] != "A" && conversation["title"] != "B"));
            let count: i64 = store.connection().unwrap().query_row(
                "SELECT COUNT(*) FROM desktop_conversation_attachments WHERE workspace_id=?1",
                [&imported.summary.id], |row| row.get(0),
            ).unwrap();
            assert_eq!(count, original_assets);
            assert_eq!(store.read_p6k_zip_import_task(&task.id).unwrap().failed_count, 2);
        };
        check(&store);
        store.link_p6k_zip_official_assets(&task.id).unwrap();
        check(&store);
        drop(store);
        let reopened = DesktopWorkspaceStore::open(directory.path().join("app-data")).unwrap();
        check(&reopened);
    }

    #[test]
    fn p6k_chatgpt_zip_direct_commit_is_private_idempotent_and_batch_soft_deletable() {
        let (directory, store, imported) = imported_store();
        let source = directory.path().join("fixture-chatgpt.zip");
        {
            let file = fs::File::create(&source).unwrap();
            let mut writer = ZipWriter::new(file);
            writer
                .start_file("conversations.json", SimpleFileOptions::default())
                .unwrap();
            writer.write_all(br#"[{"id":"p6k-alpha","title":"P6K Alpha","create_time":1,"update_time":2,"mapping":{"m-user":{"parent":null,"message":{"author":{"role":"user"},"content":{"parts":["fixture user"]}}},"m-assistant":{"parent":"m-user","message":{"author":{"role":"assistant"},"content":{"parts":["fixture assistant"]}}}}},{"id":"p6k-rejected","title":"P6K Rejected","create_time":1,"update_time":2,"mapping":{"m":{"parent":null,"message":{"author":{"role":"system"},"content":{"parts":["must reject"]}}}}}]"#).unwrap();
            writer
                .start_file("assets/unmapped.png", SimpleFileOptions::default())
                .unwrap();
            writer.write_all(b"pixels").unwrap();
            writer.finish().unwrap();
        }
        let task = store
            .stage_p6k_zip_import_selected(P6kZipImportSelectionArgs {
                workspace_id: imported.summary.id.clone(),
                provider: "CHATGPT".into(),
                selected_path: source.to_string_lossy().into_owned(),
            })
            .unwrap();
        assert_eq!(task.status, "PARTIALLY_COMPLETED");
        assert_eq!(task.imported_count, 1);
        assert_eq!(task.failed_count, 1);
        assert_eq!(task.unmapped_asset_count, 1);
        assert_eq!(task.profile_status, "NO_SAFE_PROFILE_FIELDS");
        assert_eq!(task.profile_mapped_field_count, 0);
        let second_workspace = "workspace-p6k-second";
        let connection = store.connection().unwrap();
        connection.execute("INSERT INTO workspaces(id,title,semantic_hash,package_hash,created_at) SELECT ?1,'P6K second',semantic_hash,package_hash,created_at FROM workspaces WHERE id=?2", params![second_workspace, imported.summary.id]).unwrap();
        connection.execute("INSERT INTO workspace_exchange(workspace_id,exchange_json) SELECT ?1,exchange_json FROM workspace_exchange WHERE workspace_id=?2", params![second_workspace, imported.summary.id]).unwrap();
        drop(connection);
        let second_task = store.stage_p6k_zip_import_selected(P6kZipImportSelectionArgs {
            workspace_id: second_workspace.into(),
            provider: "CHATGPT".into(),
            selected_path: source.to_string_lossy().into_owned(),
        }).unwrap();
        assert_eq!(second_task.imported_count, 1);
        assert_ne!(second_task.items[0].conversation_id, task.items[0].conversation_id);
        assert_eq!(store.read_latest_p6k_zip_import_task(&imported.summary.id).unwrap().unwrap().id, task.id);
        assert_eq!(store.read_latest_p6k_zip_import_task(second_workspace).unwrap().unwrap().id, second_task.id);
        assert_eq!(store.connection().unwrap().query_row("SELECT COUNT(*) FROM p6k_zip_import_provenance", [], |row| row.get::<_, i64>(0)).unwrap(), 2);
        let stored: String = store
            .connection()
            .unwrap()
            .query_row(
                "SELECT storage_key FROM p6k_zip_import_tasks WHERE id=?1",
                [&task.id],
                |row| row.get(0),
            )
            .unwrap();
        assert!(!stored.contains(source.to_str().unwrap()));
        assert!(store.root.join(&stored).is_file());
        let conversation_id = task.items[0].conversation_id.clone().unwrap();
        assert_eq!(
            store.skip_p6k_zip_import_failures(&task.id).unwrap().status,
            "COMPLETED"
        );
        store.retry_p6k_zip_import_task(&task.id).unwrap();
        assert_eq!(
            store
                .workspace_projection(&imported.summary.id)
                .unwrap()
                .exchange["conversations"]
                .as_array()
                .unwrap()
                .iter()
                .filter(|value| value["id"] == conversation_id)
                .count(),
            1
        );
        assert_eq!(
            store
                .connection()
                .unwrap()
                .query_row(
                    "SELECT COUNT(*) FROM desktop_conversation_attachments WHERE workspace_id=?1 AND display_name='unmapped.png'",
                    [&imported.summary.id],
                    |row| row.get::<_, i64>(0)
                )
                .unwrap(),
            0
        );
        drop(store);
        let reopened = DesktopWorkspaceStore::open(directory.path().join("app-data")).unwrap();
        assert_eq!(
            reopened
                .read_latest_p6k_zip_import_task(&imported.summary.id)
                .unwrap()
                .unwrap()
                .id,
            task.id
        );
        reopened.delete_p6k_zip_import_batch(&task.id).unwrap();
        assert!(reopened
            .workspace_projection(&imported.summary.id)
            .unwrap()
            .exchange["conversations"]
            .as_array()
            .unwrap()
            .iter()
            .find(|value| value["id"] == conversation_id)
            .unwrap()["deleted"]
            .as_bool()
            .unwrap());
        assert!(!reopened.root.join(stored).exists());
    }

    #[test]
    fn p6k_partially_committed_task_becomes_unknown_and_retries_remaining_item() {
        let (directory, store, imported) = imported_store();
        let source = directory.path().join("fixture-interrupted.zip");
        let file = fs::File::create(&source).unwrap();
        let mut writer = ZipWriter::new(file);
        writer.start_file("conversations.json", SimpleFileOptions::default()).unwrap();
        writer.write_all(br#"[{"id":"interrupted-first","title":"First","create_time":1,"update_time":2,"mapping":{"m-first":{"parent":null,"message":{"author":{"role":"user"},"content":{"parts":["first"]}}}}},{"id":"interrupted-second","title":"Second","create_time":1,"update_time":2,"mapping":{"m-second":{"parent":null,"message":{"author":{"role":"user"},"content":{"parts":["second"]}}}}}]"#).unwrap();
        writer.finish().unwrap();
        let task = store.stage_p6k_zip_import_selected_with_run(P6kZipImportSelectionArgs {
            workspace_id: imported.summary.id.clone(),
            provider: "CHATGPT".into(),
            selected_path: source.to_string_lossy().into_owned(),
        }, false).unwrap();
        assert_eq!(task.status, "STAGED");
        assert_eq!(task.items.len(), 2);
        store.commit_p6k_zip_import_item(&task.id, &task.items[0].id).unwrap();
        drop(store);
        let reopened = DesktopWorkspaceStore::open(directory.path().join("app-data")).unwrap();
        let interrupted = reopened.read_p6k_zip_import_task(&task.id).unwrap();
        assert_eq!(interrupted.status, "UNKNOWN");
        assert_eq!(interrupted.imported_count, 1);
        assert_eq!(interrupted.items.iter().filter(|item| item.status == "PENDING").count(), 1);
        assert_eq!(reopened.workspace_projection(&imported.summary.id).unwrap().exchange["conversations"].as_array().unwrap().iter().filter(|item| item["importedFrom"] == "CHATGPT_ZIP").count(), 1);
        assert_eq!(reopened.retry_p6k_zip_import_task(&task.id).unwrap().status, "COMPLETED");
        assert_eq!(reopened.retry_p6k_zip_import_task(&task.id).unwrap().imported_count, 2);
        let conversations = reopened.workspace_projection(&imported.summary.id).unwrap().exchange["conversations"].as_array().unwrap().clone();
        assert_eq!(conversations.iter().filter(|item| item["importedFrom"] == "CHATGPT_ZIP").count(), 2);
    }

    #[test]
    fn p6k_retry_replays_failed_commit_item_after_transient_sqlite_error() {
        let (directory, store, imported) = imported_store();
        let source = directory.path().join("fixture-transient-failure.zip");
        let file = fs::File::create(&source).unwrap();
        let mut writer = ZipWriter::new(file);
        writer.start_file("conversations.json", SimpleFileOptions::default()).unwrap();
        writer.write_all(br#"[{"id":"transient-first","title":"First","create_time":1,"update_time":2,"mapping":{"m-first":{"parent":null,"message":{"author":{"role":"user"},"content":{"parts":["first"]}}}}},{"id":"transient-second","title":"Second","create_time":1,"update_time":2,"mapping":{"m-second":{"parent":null,"message":{"author":{"role":"user"},"content":{"parts":["second"]}}}}}]"#).unwrap();
        writer.finish().unwrap();
        let task = store.stage_p6k_zip_import_selected_with_run(P6kZipImportSelectionArgs {
            workspace_id: imported.summary.id.clone(), provider: "CHATGPT".into(),
            selected_path: source.to_string_lossy().into_owned(),
        }, false).unwrap();
        store.commit_p6k_zip_import_item(&task.id, &task.items[0].id).unwrap();
        store.connection().unwrap().execute_batch("CREATE TRIGGER synthetic_p6k_transient_failure BEFORE INSERT ON p6k_zip_import_provenance BEGIN SELECT RAISE(ABORT,'synthetic transient failure'); END;").unwrap();
        store.run_p6k_zip_import_task(&task.id).unwrap();
        let failed = store.read_p6k_zip_import_task(&task.id).unwrap();
        assert_eq!(failed.imported_count, 1);
        assert_eq!(failed.failed_count, 1);
        store.connection().unwrap().execute_batch("DROP TRIGGER synthetic_p6k_transient_failure;").unwrap();
        store.prepare_p6k_zip_retry(&task.id).unwrap();
        drop(store);
        let reopened = DesktopWorkspaceStore::open(directory.path().join("app-data")).unwrap();
        assert_eq!(reopened.read_p6k_zip_import_task(&task.id).unwrap().status, "UNKNOWN");
        let retried = reopened.retry_p6k_zip_import_task(&task.id).unwrap();
        assert_eq!(retried.imported_count, 2);
        assert_eq!(retried.failed_count, 0);
        assert_eq!(retried.status, "COMPLETED");
        assert_eq!(reopened.workspace_projection(&imported.summary.id).unwrap().exchange["conversations"].as_array().unwrap().iter().filter(|item| item["importedFrom"] == "CHATGPT_ZIP").count(), 2);
    }

    #[test]
    fn p6k_official_identity_deduplicates_across_packages_and_user_delete_never_resurrects() {
        let (directory, store, imported) = imported_store();
        let first = directory.path().join("fixture-identity-first.zip");
        let second = directory.path().join("fixture-identity-second.zip");
        let cumulative = directory.path().join("fixture-identity-cumulative.zip");
        let conflict = directory.path().join("fixture-identity-conflict.zip");
        let payload = br#"[{"id":"official-conversation","title":"Official","create_time":1,"update_time":2,"mapping":{"official-user":{"parent":null,"message":{"author":{"role":"user"},"content":{"parts":["fixture"]}}}}}]"#;
        for path in [&first, &second] {
            let file = fs::File::create(path).unwrap();
            let mut writer = ZipWriter::new(file);
            writer
                .start_file("conversations.json", SimpleFileOptions::default())
                .unwrap();
            writer.write_all(payload).unwrap();
            if path == &second {
                writer
                    .start_file("unrelated.json", SimpleFileOptions::default())
                    .unwrap();
                writer.write_all(b"{}").unwrap();
            }
            writer.finish().unwrap();
        }
        {
            let file = fs::File::create(&conflict).unwrap();
            let mut writer = ZipWriter::new(file);
            writer
                .start_file("conversations.json", SimpleFileOptions::default())
                .unwrap();
            writer.write_all(br#"[{"id":"official-conversation","title":"Official","create_time":1,"update_time":4,"mapping":{"official-user":{"parent":null,"message":{"author":{"role":"user"},"content":{"parts":["rewritten"]}}},"official-assistant":{"parent":"official-user","message":{"author":{"role":"assistant"},"content":{"parts":["new reply"]},"create_time":3}}}}]"#).unwrap();
            writer.finish().unwrap();
        }
        {
            let file = fs::File::create(&cumulative).unwrap();
            let mut writer = ZipWriter::new(file);
            writer
                .start_file("conversations.json", SimpleFileOptions::default())
                .unwrap();
            writer.write_all(br#"[{"id":"official-conversation","title":"Official","create_time":1,"update_time":3,"mapping":{"official-user":{"parent":null,"message":{"author":{"role":"user"},"content":{"parts":["fixture"]}}},"official-assistant":{"parent":"official-user","message":{"author":{"role":"assistant"},"content":{"parts":["new reply"]},"create_time":3}}}}]"#).unwrap();
            writer.finish().unwrap();
        }

        let first_task = store
            .stage_p6k_zip_import_selected(P6kZipImportSelectionArgs {
                workspace_id: imported.summary.id.clone(),
                provider: "CHATGPT".into(),
                selected_path: first.to_string_lossy().into_owned(),
            })
            .unwrap();
        assert_eq!(first_task.imported_count, 1);
        let conversation_id = first_task.items[0].conversation_id.clone().unwrap();

        let duplicate_task = store
            .stage_p6k_zip_import_selected(P6kZipImportSelectionArgs {
                workspace_id: imported.summary.id.clone(),
                provider: "CHATGPT".into(),
                selected_path: second.to_string_lossy().into_owned(),
            })
            .unwrap();
        assert_eq!(duplicate_task.imported_count, 0);
        assert_eq!(duplicate_task.skipped_count, 1);
        assert_eq!(
            duplicate_task.items[0].failure.as_deref(),
            Some("ALREADY_IMPORTED")
        );
        assert_eq!(
            duplicate_task.items[0].conversation_id.as_deref(),
            Some(conversation_id.as_str())
        );

        let cumulative_task = store
            .stage_p6k_zip_import_selected(P6kZipImportSelectionArgs {
                workspace_id: imported.summary.id.clone(),
                provider: "CHATGPT".into(),
                selected_path: cumulative.to_string_lossy().into_owned(),
            })
            .unwrap();
        assert_eq!(cumulative_task.imported_count, 1);
        let merged = store
            .workspace_projection(&imported.summary.id)
            .unwrap()
            .exchange;
        assert_eq!(
            merged["conversations"]
                .as_array()
                .unwrap()
                .iter()
                .find(|value| value["id"] == conversation_id)
                .unwrap()["messages"]
                .as_array()
                .unwrap()
                .len(),
            2
        );
        assert_eq!(
            merged["conversations"]
                .as_array()
                .unwrap()
                .iter()
                .filter(|value| value["id"] == conversation_id)
                .count(),
            1
        );
        let conflict_task = store
            .stage_p6k_zip_import_selected(P6kZipImportSelectionArgs {
                workspace_id: imported.summary.id.clone(),
                provider: "CHATGPT".into(),
                selected_path: conflict.to_string_lossy().into_owned(),
            })
            .unwrap();
        assert_eq!(conflict_task.imported_count, 0);
        assert_eq!(conflict_task.failed_count, 1);
        assert!(conflict_task.items[0]
            .failure
            .as_deref()
            .unwrap()
            .contains("OFFICIAL_IDENTITY_CONFLICT"));
        let after_conflict = store
            .workspace_projection(&imported.summary.id)
            .unwrap()
            .exchange;
        assert!(after_conflict["conversations"]
            .as_array()
            .unwrap()
            .iter()
            .find(|value| value["id"] == conversation_id)
            .unwrap()["messages"]
            .as_array()
            .unwrap()
            .iter()
            .any(|message| message["blocks"][0]["text"] == "fixture"));

        store
            .delete_p6k_zip_import_batch(&cumulative_task.id)
            .unwrap();
        let deleted_task = store
            .stage_p6k_zip_import_selected(P6kZipImportSelectionArgs {
                workspace_id: imported.summary.id.clone(),
                provider: "CHATGPT".into(),
                selected_path: first.to_string_lossy().into_owned(),
            })
            .unwrap();
        assert_eq!(deleted_task.imported_count, 0);
        assert_eq!(deleted_task.skipped_count, 1);
        assert_eq!(
            deleted_task.items[0].failure.as_deref(),
            Some("USER_DELETED")
        );
        let exchange = store
            .workspace_projection(&imported.summary.id)
            .unwrap()
            .exchange;
        assert_eq!(
            exchange["conversations"]
                .as_array()
                .unwrap()
                .iter()
                .filter(|value| {
                    value["id"] == conversation_id && !value["deleted"].as_bool().unwrap_or(false)
                })
                .count(),
            0
        );
    }

    #[test]
    fn p6k_manual_asset_link_uses_explicit_message_receipts_for_image_video_and_pdf() {
        let (directory, store, imported) = imported_store();
        let source = directory.path().join("fixture-manual-media.zip");
        {
            let file = fs::File::create(&source).unwrap();
            let mut writer = ZipWriter::new(file);
            writer
                .start_file("conversations.json", SimpleFileOptions::default())
                .unwrap();
            writer.write_all(br#"[{"id":"manual-media","title":"Manual media","create_time":1,"update_time":2,"mapping":{"user":{"parent":null,"message":{"author":{"role":"user"},"content":{"parts":["fixture"]}}},"assistant":{"parent":"user","message":{"author":{"role":"assistant"},"content":{"parts":["fixture"]}}}}}]"#).unwrap();
            writer
                .start_file("assets/image.png", SimpleFileOptions::default())
                .unwrap();
            writer.write_all(b"\x89PNG\r\n\x1a\nfixture").unwrap();
            writer
                .start_file("assets/video.mp4", SimpleFileOptions::default())
                .unwrap();
            writer
                .write_all(b"\0\0\0\x20ftypisom\0\0\x02\0isomiso2")
                .unwrap();
            writer
                .start_file("assets/document.pdf", SimpleFileOptions::default())
                .unwrap();
            writer.write_all(b"%PDF-1.4\nfixture").unwrap();
            writer.finish().unwrap();
        }
        let task = store
            .stage_p6k_zip_import_selected(P6kZipImportSelectionArgs {
                workspace_id: imported.summary.id.clone(),
                provider: "CHATGPT".into(),
                selected_path: source.to_string_lossy().into_owned(),
            })
            .unwrap();
        assert_eq!(task.unmapped_asset_count, 3);
        assert!(task
            .manual_assets
            .iter()
            .all(|asset| asset.status == "UNMAPPED_REJECTED"));
        let conversation_id = task.items[0].conversation_id.clone().unwrap();
        let user_message = store
            .workspace_projection(&imported.summary.id)
            .unwrap()
            .exchange["conversations"]
            .as_array()
            .unwrap()
            .iter()
            .find(|value| value["id"] == conversation_id)
            .unwrap()["messages"]
            .as_array()
            .unwrap()
            .iter()
            .find(|message| message["role"] == "user")
            .unwrap()["id"]
            .as_str()
            .unwrap()
            .to_owned();
        let before_link = store.workspace_projection(&imported.summary.id).unwrap().exchange;
        let asset_sha: String = store.connection().unwrap().query_row(
            "SELECT sha256 FROM p6k_zip_import_asset_candidates WHERE task_id=?1 AND ordinal=0",
            [&task.id], |row| row.get(0),
        ).unwrap();
        let private_asset = store.root.join("assets").join(&asset_sha);
        fs::create_dir_all(private_asset.parent().unwrap()).unwrap();
        fs::write(&private_asset, b"corrupt-existing-private-asset").unwrap();
        assert!(store.link_p6k_zip_manual_asset(P6kManualAssetLinkArgs {
            task_id: task.id.clone(), asset_ordinal: 0,
            workspace_id: imported.summary.id.clone(),
            conversation_id: conversation_id.clone(), message_id: user_message.clone(),
        }).is_err(), "corrupt hash-addressed asset must not be linked successfully");
        assert_eq!(store.workspace_projection(&imported.summary.id).unwrap().exchange, before_link);
        assert_eq!(store.connection().unwrap().query_row(
            "SELECT COUNT(*) FROM p6k_zip_asset_link_receipts WHERE task_id=?1",
            [&task.id], |row| row.get::<_, i64>(0),
        ).unwrap(), 0);
        fs::write(&private_asset, b"\x89PNG\r\n\x1a\nfixture").unwrap();
        for ordinal in 0..3 {
            store
                .link_p6k_zip_manual_asset(P6kManualAssetLinkArgs {
                    task_id: task.id.clone(),
                    asset_ordinal: ordinal,
                    workspace_id: imported.summary.id.clone(),
                    conversation_id: conversation_id.clone(),
                    message_id: user_message.clone(),
                })
                .unwrap();
        }
        let replay = store
            .link_p6k_zip_manual_asset(P6kManualAssetLinkArgs {
                task_id: task.id.clone(),
                asset_ordinal: 0,
                workspace_id: imported.summary.id.clone(),
                conversation_id: conversation_id.clone(),
                message_id: user_message.clone(),
            })
            .unwrap();
        assert_eq!(
            replay
                .manual_assets
                .iter()
                .filter(|asset| asset.status == "MANUAL_LINKED")
                .count(),
            3
        );
        let linked_projection = store.workspace_projection(&imported.summary.id).unwrap();
        let target = linked_projection.exchange["conversations"]
            .as_array()
            .unwrap()
            .iter()
            .find(|value| value["id"] == conversation_id)
            .unwrap()["messages"]
            .as_array()
            .unwrap()
            .iter()
            .find(|message| message["id"] == user_message)
            .unwrap();
        assert_eq!(
            target["blocks"]
                .as_array()
                .unwrap()
                .iter()
                .filter(|block| block["kind"] == "ASSET_REF")
                .count(),
            3
        );
        assert_eq!(
            store
                .connection()
                .unwrap()
                .query_row(
                    "SELECT COUNT(*) FROM p6k_zip_asset_link_receipts WHERE task_id=?1",
                    [&task.id],
                    |row| row.get::<_, i64>(0)
                )
                .unwrap(),
            3
        );
        let removed_attachment_id: String = store.connection().unwrap().query_row(
            "SELECT attachment_id FROM p6k_zip_asset_link_receipts WHERE task_id=?1 AND ordinal=0",
            [&task.id],
            |row| row.get(0),
        ).unwrap();
        let revision = linked_projection.exchange["conversations"]
            .as_array()
            .unwrap()
            .iter()
            .find(|value| value["id"] == conversation_id)
            .unwrap()["revision"]
            .as_u64()
            .unwrap();
        store
            .mutate_domain(DomainMutationArgs {
                intent_id: "intent-remove-p6k-attachment".into(),
                workspace_id: imported.summary.id.clone(),
                entity: "conversation".into(),
                action: "removeAttachment".into(),
                object_id: Some(conversation_id.clone()),
                expected_revision: Some(revision),
                fields: json!({"messageId":user_message,"attachmentId":removed_attachment_id}),
            })
            .unwrap();
        assert_eq!(
            store.connection().unwrap().query_row(
                "SELECT state FROM p6k_zip_official_identity_ledger WHERE entity_kind='ATTACHMENT' AND local_object_id=?1",
                [&removed_attachment_id],
                |row| row.get::<_, String>(0),
            ).unwrap(),
            "USER_DELETED"
        );
        let stored: String = store
            .connection()
            .unwrap()
            .query_row(
                "SELECT storage_key FROM p6k_zip_import_tasks WHERE id=?1",
                [&task.id],
                |row| row.get(0),
            )
            .unwrap();
        drop(store);
        let reopened = DesktopWorkspaceStore::open(directory.path().join("app-data")).unwrap();
        reopened.delete_p6k_zip_import_batch(&task.id).unwrap();
        assert!(!reopened.root.join(stored).exists());
        assert!(reopened
            .workspace_projection(&imported.summary.id)
            .unwrap()
            .exchange["conversations"]
            .as_array()
            .unwrap()
            .iter()
            .find(|value| value["id"] == conversation_id)
            .unwrap()["deleted"]
            .as_bool()
            .unwrap());
    }

    #[test]
    fn p6k_versioned_profile_fixture_commits_replays_reopens_and_revokes_with_its_batch() {
        let (directory, store, imported) = imported_store();
        let source = directory.path().join("fixture-profile.zip");
        {
            let file = fs::File::create(&source).unwrap();
            let mut writer = ZipWriter::new(file);
            writer
                .start_file("conversations.json", SimpleFileOptions::default())
                .unwrap();
            writer.write_all(br#"[{"id":"profile-conversation","title":"Fixture","create_time":1,"update_time":2,"mapping":{"m":{"parent":null,"message":{"author":{"role":"user"},"content":{"parts":["fixture"]}}}}}]"#).unwrap();
            writer
                .start_file(
                    "profile-personalization-v1.json",
                    SimpleFileOptions::default(),
                )
                .unwrap();
            writer.write_all(r#"{"format":"nfai.third-party-profile-personalization","version":1,"personalization":{"displayName":"Fixture","language":"zh-CN","notificationsEnabled":true,"publicBio":"跨端可靠性与数据保全"}}"#.as_bytes()).unwrap();
            writer.finish().unwrap();
        }
        let task = store
            .stage_p6k_zip_import_selected(P6kZipImportSelectionArgs {
                workspace_id: imported.summary.id.clone(),
                provider: "CHATGPT".into(),
                selected_path: source.to_string_lossy().into_owned(),
            })
            .unwrap();
        assert_eq!(task.profile_status, "OWNER_COMMITTED");
        assert_eq!(task.profile_mapped_field_count, 4);
        assert_eq!(
            store
                .read_p6k_profile_personalization()
                .unwrap()
                .unwrap()
                .display_name
                .as_deref(),
            Some("Fixture")
        );
        let imported_interests: String = store
            .connection()
            .unwrap()
            .query_row(
                "SELECT interests FROM desktop_portable_personalization_v1 WHERE id=1",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(imported_interests, "跨端可靠性与数据保全");
        assert_eq!(
            store
                .retry_p6k_zip_import_task(&task.id)
                .unwrap()
                .profile_status,
            "OWNER_COMMITTED"
        );
        drop(store);
        let reopened = DesktopWorkspaceStore::open(directory.path().join("app-data")).unwrap();
        assert_eq!(
            reopened
                .read_p6k_profile_personalization()
                .unwrap()
                .unwrap()
                .language
                .as_deref(),
            Some("zh-CN")
        );
        reopened.delete_p6k_zip_import_batch(&task.id).unwrap();
        assert!(reopened
            .read_p6k_profile_personalization()
            .unwrap()
            .is_none());
    }

