    fn assert_json_replay_task_state(provider: &str, reject_task_write: bool) {
        let (directory, store, imported) = imported_store();
        let source = directory.path().join("synthetic-replay.json");
        let data = if provider == "chatgpt" { r#"[{"id":"alpha","title":"alpha","create_time":1,"update_time":2,"mapping":{"u":{"parent":null,"children":[],"message":{"author":{"role":"user"},"content":{"parts":["synthetic replay alpha"]}}}}},{"id":"beta","title":"beta","create_time":1,"update_time":2,"mapping":{"u":{"parent":null,"children":[],"message":{"author":{"role":"user"},"content":{"parts":["synthetic replay beta"]}}}}}]"# } else { r#"[{"uuid":"alpha","name":"alpha","created_at":"2026-08-15T08:00:00Z","updated_at":"2026-08-15T08:01:00Z","chat_messages":[{"uuid":"alpha-u","sender":"human","created_at":"2026-08-15T08:00:00Z","text":"synthetic replay alpha","parent_message_uuid":null}]},{"uuid":"beta","name":"beta","created_at":"2026-08-15T08:00:00Z","updated_at":"2026-08-15T08:01:00Z","chat_messages":[{"uuid":"beta-u","sender":"human","created_at":"2026-08-15T08:00:00Z","text":"synthetic replay beta","parent_message_uuid":null}]}]"# };
        fs::write(&source, data).unwrap();
        let stage = || if provider == "chatgpt" { store.stage_chatgpt_export_selected(source.to_str().unwrap(), &imported.summary.id).unwrap().id } else { store.stage_claude_export_selected(source.to_str().unwrap(), &imported.summary.id).unwrap().id };
        let confirm = |task: &str, ordinal: usize| if provider == "chatgpt" { store.confirm_chatgpt_import_item(ChatGptImportItemActionArgs { workspace_id: imported.summary.id.clone(), task_id: task.into(), item_id: format!("chatgpt-item-{ordinal}") }) } else { store.confirm_claude_import_item(ClaudeImportItemActionArgs { workspace_id: imported.summary.id.clone(), task_id: task.into(), item_id: format!("claude-item-{ordinal}") }) };
        let first = stage();
        let ids = [confirm(&first, 0).unwrap(), confirm(&first, 1).unwrap()];
        let original = store.workspace_projection(&imported.summary.id).unwrap().exchange;
        let replay = stage();
        if reject_task_write {
            store.connection().unwrap().execute_batch(&format!("CREATE TRIGGER synthetic_replay_state_denial BEFORE UPDATE ON {provider}_import_tasks WHEN NEW.id='{}' BEGIN SELECT RAISE(ABORT,'synthetic state denial'); END;", replay.replace('\'', "''"))).unwrap();
            assert!(confirm(&replay, 0).is_err());
            let status: String = store.connection().unwrap().query_row(&format!("SELECT status FROM {provider}_import_items WHERE task_id=?1 AND id=?2"), params![replay,format!("{provider}-item-0")], |row| row.get(0)).unwrap();
            assert_eq!(status, "PENDING_CONFIRMATION");
            store.connection().unwrap().execute_batch("DROP TRIGGER synthetic_replay_state_denial").unwrap();
        }
        assert_eq!(confirm(&replay, 0).unwrap(), ids[0]);
        let state = || store.connection().unwrap().query_row(&format!("SELECT status FROM {provider}_import_tasks WHERE id=?1"), [&replay], |row|row.get::<_,String>(0)).unwrap();
        assert_eq!(state(), "PARTIALLY_COMPLETED");
        assert_eq!(confirm(&replay, 1).unwrap(), ids[1]);
        assert_eq!(state(), "COMPLETED");
        assert_eq!(confirm(&replay, 1).unwrap(), ids[1]);
        assert_eq!(store.workspace_projection(&imported.summary.id).unwrap().exchange, original);
        let receipt_count: i64 = store.connection().unwrap().query_row(&format!("SELECT COUNT(*) FROM {provider}_import_receipts"), [], |row|row.get(0)).unwrap();
        assert_eq!(receipt_count, 2);
        drop(store);
        let reopened = DesktopWorkspaceStore::open(directory.path().join("app-data")).unwrap();
        let status: String = reopened.connection().unwrap().query_row(&format!("SELECT status FROM {provider}_import_tasks WHERE id=?1"), [&replay], |row|row.get(0)).unwrap();
        assert_eq!(status,"COMPLETED");
        assert_eq!(reopened.workspace_projection(&imported.summary.id).unwrap().exchange, original);
    }

    fn assert_json_legacy_read_status(provider: &str) {
        let directory=tempdir().unwrap();
        let old_store=DesktopWorkspaceStore::open(directory.path().join("app-data")).unwrap();
        drop(old_store);
        let root = directory.path().join("app-data");
        let root_lock = fs::OpenOptions::new().read(true).write(true).create(true).truncate(false).open(root.join(".runtime-owner.lock")).unwrap();
        root_lock.try_lock_exclusive().unwrap();
        desktop_schema_reconcile::reconcile_schema45_at_startup_under_existing_lock(&root, &root_lock).unwrap();
        let (store, _work) = open_desktop_area_stores_for_startup(directory.path().join("app-data"),DesktopStartupMode::Normal).unwrap();
        let imported=store.ensure_local_workspace().unwrap();
        let source=directory.path().join("synthetic-legacy.json");
        let data=if provider=="chatgpt" { r#"[{"id":"alpha","title":"Alpha","create_time":1,"update_time":2,"mapping":{"u":{"parent":null,"children":[],"message":{"author":{"role":"user"},"content":{"parts":["synthetic legacy"]}}}}}]"# } else { r#"[{"uuid":"alpha","name":"Alpha","created_at":"2026-08-15T08:00:00Z","updated_at":"2026-08-15T08:01:00Z","chat_messages":[{"uuid":"u","sender":"human","created_at":"2026-08-15T08:00:00Z","text":"synthetic legacy","parent_message_uuid":null}]}]"# };
        fs::write(&source,data).unwrap();
        let task=if provider=="chatgpt" {store.stage_chatgpt_export_selected(source.to_str().unwrap(),&imported.summary.id).unwrap().id} else {store.stage_claude_export_selected(source.to_str().unwrap(),&imported.summary.id).unwrap().id};
        let id=if provider=="chatgpt" {store.confirm_chatgpt_import_item(ChatGptImportItemActionArgs{workspace_id:imported.summary.id.clone(),task_id:task.clone(),item_id:"chatgpt-item-0".into()}).unwrap()} else {store.confirm_claude_import_item(ClaudeImportItemActionArgs{workspace_id:imported.summary.id.clone(),task_id:task.clone(),item_id:"claude-item-0".into()}).unwrap()};
        let original=store.workspace_projection(&imported.summary.id).unwrap().exchange;
        store.connection().unwrap().execute(&format!("UPDATE {provider}_import_tasks SET status='AWAITING_CONFIRMATION' WHERE id=?1"),[&task]).unwrap();
        let read=||if provider=="chatgpt" {store.read_chatgpt_import_task(&task).unwrap().status} else {store.read_claude_import_task(&task).unwrap().status};
        assert_eq!(read(),"COMPLETED");
        assert_eq!(store.connection().unwrap().query_row(&format!("SELECT status FROM {provider}_import_tasks WHERE id=?1"),[&task],|r|r.get::<_,String>(0)).unwrap(),"AWAITING_CONFIRMATION");

        for column in ["workspace_id","source_conversation_id","package_hash","content_hash","conversation_id"] {
            let before:String=store.connection().unwrap().query_row(&format!("SELECT {column} FROM {provider}_import_receipts WHERE conversation_id=?1"),[&id],|row|row.get(0)).unwrap();
            store.connection().unwrap().execute(&format!("UPDATE {provider}_import_receipts SET {column}='synthetic-wrong' WHERE conversation_id=?1"),[&id]).unwrap();
            assert_eq!(read(),"AWAITING_CONFIRMATION", "{provider} mismatched {column}");
            store.connection().unwrap().execute(&format!("UPDATE {provider}_import_receipts SET {column}=?1 WHERE {column}='synthetic-wrong'"),[&before]).unwrap();
            assert_eq!(read(),"COMPLETED");
        }
        store.connection().unwrap().execute(&format!("UPDATE {provider}_import_receipts SET content_hash='synthetic-wrong' WHERE conversation_id=?1"),[&id]).unwrap();
        assert_eq!(read(),"AWAITING_CONFIRMATION");
        store.connection().unwrap().execute(&format!("UPDATE {provider}_import_tasks SET status='CANCELLED' WHERE id=?1"),[&task]).unwrap();
        assert_eq!(read(),"CANCELLED");
        assert_eq!(store.workspace_projection(&imported.summary.id).unwrap().exchange,original);
    }
    #[test] fn json_chatgpt_legacy_read_completion_requires_exact_receipt_and_is_readonly(){assert_json_legacy_read_status("chatgpt");}
    #[test] fn json_claude_legacy_read_completion_requires_exact_receipt_and_is_readonly(){assert_json_legacy_read_status("claude");}

    #[test] fn json_chatgpt_replay_task_completes_without_duplicate_conversations() { assert_json_replay_task_state("chatgpt", false); }
    #[test] fn json_claude_replay_task_completes_without_duplicate_conversations() { assert_json_replay_task_state("claude", false); }
    #[test] fn json_chatgpt_replay_task_write_failure_rolls_back_item() { assert_json_replay_task_state("chatgpt", true); }
    #[test] fn json_claude_replay_task_write_failure_rolls_back_item() { assert_json_replay_task_state("claude", true); }

    #[test]
    fn chatgpt_confirm_skip_is_atomic_idempotent_and_survives_reopen() {
        let (directory, store, imported) = imported_store();
        let source = directory.path().join("conversations.json");
        fs::write(&source, br#"[{"id":"alpha","title":"Alpha","create_time":1,"update_time":2,"mapping":{"u":{"parent":null,"children":["a"],"message":{"author":{"role":"user"},"content":{"parts":["hello"]}}},"a":{"parent":"u","children":[],"message":{"author":{"role":"assistant"},"content":{"parts":["world"]},"metadata":{"model_slug":"inert-model"}}}}},{"id":"skip","title":"Skip","create_time":1,"update_time":2,"mapping":{"s":{"parent":null,"children":[],"message":{"author":{"role":"user"},"content":{"parts":["skip"]}}}}}]"#).unwrap();
        let task = store
            .stage_chatgpt_export_selected(source.to_str().unwrap(), &imported.summary.id)
            .unwrap();
        let confirmed = store
            .confirm_chatgpt_import_item(ChatGptImportItemActionArgs {
                workspace_id: imported.summary.id.clone(),
                task_id: task.id.clone(),
                item_id: "chatgpt-item-0".into(),
            })
            .unwrap();
        store
            .skip_chatgpt_import_item(ChatGptImportItemActionArgs {
                workspace_id: imported.summary.id.clone(),
                task_id: task.id.clone(),
                item_id: "chatgpt-item-1".into(),
            })
            .unwrap();
        let replayed = store
            .confirm_chatgpt_import_item(ChatGptImportItemActionArgs {
                workspace_id: imported.summary.id.clone(),
                task_id: task.id.clone(),
                item_id: "chatgpt-item-0".into(),
            })
            .unwrap();
        assert_eq!(confirmed, replayed);
        drop(store);
        let reopened = DesktopWorkspaceStore::open(directory.path().join("app-data")).unwrap();
        let projection = reopened.workspace_projection(&imported.summary.id).unwrap();
        let conversation = projection.exchange["conversations"]
            .as_array()
            .unwrap()
            .iter()
            .find(|value| value["id"] == confirmed)
            .unwrap();
        assert_eq!(conversation["messages"].as_array().unwrap().len(), 2);
        let connection = reopened.connection().unwrap();
        assert_eq!(
            connection
                .query_row(
                    "SELECT status FROM chatgpt_import_tasks WHERE id=?1",
                    [&task.id],
                    |row| row.get::<_, String>(0)
                )
                .unwrap(),
            "COMPLETED"
        );
        assert_eq!(
            connection
                .query_row(
                    "SELECT COUNT(*) FROM chatgpt_import_provenance WHERE conversation_id=?1",
                    [&confirmed],
                    |row| row.get::<_, i64>(0)
                )
                .unwrap(),
            1
        );
    }

