    #[test]
    fn xml_yaml_html_are_safe_local_text_attachments() {
        for (extension, mime, text) in [
            ("xml", "application/xml", "<root>合成正文</root>"),
            ("yml", "text/yaml", "title: 合成正文"),
            ("yaml", "text/yaml", "title: 合成正文"),
            ("html", "text/html", "<p>合成正文</p>"),
        ] {
            assert_eq!(desktop_attachment_kind(text.as_bytes(), Some(extension)).map(|kind| kind.0), Some(mime));
            assert!(is_desktop_text_attachment_mime(mime));
            assert_eq!(desktop_attachment_kind(&[0xff, 0xfe], Some(extension)), None);
        }
        assert_eq!(desktop_attachment_kind(b"<p>safe</p>", Some("exe")), None);
    }

    #[test]
    fn docx_composer_import_requires_readable_local_text() {
        let mut writer = ZipWriter::new(Cursor::new(Vec::new()));
        writer
            .start_file("word/document.xml", SimpleFileOptions::default())
            .unwrap();
        writer
            .write_all(b"<w:document xmlns:w='http://schemas.openxmlformats.org/wordprocessingml/2006/main'><w:p><w:t>local body</w:t></w:p></w:document>")
            .unwrap();
        writer.start_file("[Content_Types].xml",SimpleFileOptions::default()).unwrap();
        writer.write_all(br#"<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>"#).unwrap();
        writer.start_file("_rels/.rels",SimpleFileOptions::default()).unwrap();
        writer.write_all(br#"<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>"#).unwrap();
        let bytes = writer.finish().unwrap().into_inner();
        assert_eq!(
            desktop_attachment_kind(&bytes, Some("docx")),
            Some((
                "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                ".docx"
            ))
        );
        assert_eq!(
            desktop_attachment_kind(&bytes, Some("zip")),
            Some(("application/zip", ".zip"))
        );
        assert_eq!(desktop_attachment_kind(b"PK\x03\x04invalid", Some("docx")), None);
    }

    #[test]
    fn zip_composer_import_requires_safe_archive_directory() {
        let mut writer = ZipWriter::new(Cursor::new(Vec::new()));
        writer
            .start_file("folder/readme.txt", SimpleFileOptions::default())
            .unwrap();
        writer.write_all(b"safe entry").unwrap();
        let bytes = writer.finish().unwrap().into_inner();
        assert_eq!(
            desktop_attachment_kind(&bytes, Some("zip")),
            Some(("application/zip", ".zip"))
        );
        assert_eq!(desktop_attachment_kind(&bytes, Some("docx")), None);
        assert_eq!(desktop_attachment_kind(b"PK\x03\x04invalid", Some("zip")), None);
        let mut unsafe_writer = ZipWriter::new(Cursor::new(Vec::new()));
        unsafe_writer
            .start_file("../escape.txt", SimpleFileOptions::default())
            .unwrap();
        unsafe_writer.write_all(b"outside").unwrap();
        let unsafe_bytes = unsafe_writer.finish().unwrap().into_inner();
        assert_eq!(desktop_attachment_kind(&unsafe_bytes, Some("zip")), None);
    }

    #[test]
    fn p6f2d_mp4_magic_accepts_iso_bmff_ftyp() {
        let bytes = b"\0\0\0\x20ftypisom\0\0\x02\0isomiso2";
        assert_eq!(
            desktop_attachment_kind(bytes, Some("mp4")),
            Some(("video/mp4", ".mp4"))
        );
        assert_eq!(
            desktop_attachment_kind(bytes, Some("renamed")),
            Some(("video/mp4", ".mp4"))
        );
        assert_eq!(
            desktop_attachment_kind(b"\0\0\0\x18ftypM4A \0\0\0\0M4A ", Some("mp4")),
            None
        );
        let m4a_with_mp4_compatible_brands = b"\0\0\0\x20ftypM4A \0\0\0\0M4A isommp42";
        assert_eq!(
            desktop_attachment_kind(m4a_with_mp4_compatible_brands, Some("m4a")),
            Some(("audio/mp4", ".m4a"))
        );
        assert_eq!(
            desktop_attachment_kind(m4a_with_mp4_compatible_brands, Some("mp4")),
            Some(("video/mp4", ".mp4"))
        );
    }

