            read_desktop_video_thumbnail_from_paths(&store.root, &store.database, &args).unwrap();
        assert!(preview.data_url.starts_with("data:image/png;base64,"));
        assert_eq!(fs::read(&path).unwrap(), source);
        args.workspace_id = "wrong-workspace".into();
        assert!(
            read_desktop_video_thumbnail_from_paths(&store.root, &store.database, &args).is_err()
        );
