    pub(super) fn imported_store() -> (
        tempfile::TempDir,
        DesktopWorkspaceStore,
        WorkspaceProjection,
    ) {
        let directory = tempdir().unwrap();
        let store = DesktopWorkspaceStore::open(directory.path().join("app-data")).unwrap();
        // Direct-store unit fixtures use the pre-area schema; production startup upgrades
        // both committed areas through Schema50 before exposing ZIP import commands.
        store.connection().unwrap().execute_batch(desktop_p6k_occurrence_schema::ATTACHMENT_SUMMARY_TABLE_SQL).unwrap();
        let source = directory.path().join("golden.nfai-exchange");
        fs::write(&source, golden()).unwrap();
        let receipt = store.stage_selected_file(source.to_str().unwrap()).unwrap();
        let imported = store
            .import_staged(ImportArgs {
                staging_id: receipt.staging_id,
                workspace_title: "P6-C 测试工作区".into(),
            })
            .unwrap();
        (directory, store, imported)
    }

    #[test]
    fn ordinary_chat_usage_fallbacks_keep_quantitative_legacy_facts_and_reject_invalid_estimates() {
        let (_directory,store,imported)=imported_store();
        let mut expected=ordinary_chat_usage_fallbacks(&store).unwrap();
        let mut exchange=imported.exchange.clone();
        let template=exchange["conversations"][0]["messages"][0].clone();
        let additions=json!([
            {"id":"legacy-usage-a","attemptId":"legacy-a","estimatedUsage":{"inputTokens":32,"outputTokens":8,"cachedInputTokens":4}},
            {"id":"legacy-usage-b","attemptId":"legacy-b","estimatedUsage":{"inputTokens":7,"outputTokens":2}},
            {"id":"legacy-usage-negative","attemptId":"negative","estimatedUsage":{"inputTokens":-1,"outputTokens":2}},
            {"id":"legacy-usage-invalid","attemptId":"invalid","estimatedUsage":{"inputTokens":"7","outputTokens":2}},
            {"id":"legacy-usage-no-attempt","estimatedUsage":{"inputTokens":7,"outputTokens":2}}
        ]);
        for addition in additions.as_array().unwrap() {
            let mut message=template.clone();for (key,value) in addition.as_object().unwrap(){message[key]=value.clone();}
            exchange["conversations"][0]["messages"].as_array_mut().unwrap().push(message);
        }
        let c=store.connection().unwrap();
        c.execute("UPDATE workspace_exchange SET exchange_json=?1 WHERE workspace_id=?2",params![exchange.to_string(),imported.summary.id]).unwrap();
        let before:String=c.query_row("SELECT exchange_json FROM workspace_exchange WHERE workspace_id=?1",[&imported.summary.id],|r|r.get(0)).unwrap();
        let result=ordinary_chat_usage_fallbacks(&store).unwrap();
        expected.insert("legacy-a".into(),(32,8,4));expected.insert("legacy-b".into(),(7,2,0));assert_eq!(result,expected);
        let after:String=c.query_row("SELECT exchange_json FROM workspace_exchange WHERE workspace_id=?1",[&imported.summary.id],|r|r.get(0)).unwrap();
        assert_eq!(before,after,"fallback read must not change historical usage or body");
    }

