    #[test]
    fn cloud_workspace_projection_batch_preserves_full_owner_projection_and_isolates_failed_ids() {
        let (_directory, store, imported) = imported_store();
        let conversation_id = imported.exchange["conversations"][0]["id"].as_str().unwrap();
        let connection = store.connection().unwrap();
        desktop_app_settings_v1::set_conversation_favorite(&connection, &imported.summary.id, conversation_id, true).unwrap();
        let before_changes = connection.total_changes();
        let paths = DesktopStoreReadPaths { root: store.root.clone(), database: store.database.clone() };
        let batch = paths.cloud_workspace_projections(&[imported.summary.id.clone(), "missing-workspace".into(), imported.summary.id.clone()]).unwrap();
        assert_eq!(batch.projections.len(), 1);
        assert_eq!(batch.failed_workspace_ids, vec!["missing-workspace"]);
        assert_eq!(batch.projections[0].workspace_id, imported.summary.id);
        assert_eq!(batch.projections[0].favorite_ids, vec![conversation_id]);
        assert_eq!(serde_json::to_value(&batch.projections[0].workspace).unwrap(), serde_json::to_value(paths.workspace_projection(&imported.summary.id).unwrap()).unwrap());
        assert_eq!(connection.total_changes(), before_changes);
        connection.execute("UPDATE workspace_exchange SET exchange_json='broken' WHERE workspace_id=?1", [&imported.summary.id]).unwrap();
        let broken = paths.cloud_workspace_projections(&[imported.summary.id.clone()]).unwrap();
        assert!(broken.projections.is_empty());
        assert_eq!(broken.failed_workspace_ids, vec![imported.summary.id]);
    }

