    #[test]
    fn office_system_open_uses_a_verified_extension_bearing_private_reference() {
        let (_directory, store, imported) = imported_store();
        let mut writer = ZipWriter::new(Cursor::new(Vec::new()));
        writer
            .start_file("[Content_Types].xml", SimpleFileOptions::default())
            .unwrap();
        writer.write_all(b"<Types/>").unwrap();
        writer
            .start_file("word/document.xml", SimpleFileOptions::default())
            .unwrap();
        writer.write_all(b"<document>local</document>").unwrap();
        let bytes = writer.finish().unwrap().into_inner();
        let digest = sha256(&bytes);
        fs::write(store.root.join("assets").join(&digest), &bytes).unwrap();
        store.connection().unwrap().execute(
            "INSERT INTO desktop_conversation_attachments(workspace_id,attachment_id,mime_type,display_name,byte_count,sha256,created_at) VALUES(?1,?2,?3,?4,?5,?6,?7)",
            params![imported.summary.id, "attachment-office", "application/vnd.openxmlformats-officedocument.wordprocessingml.document", "local.docx", bytes.len() as u64, digest, local_now()],
        ).unwrap();
        let args = DesktopSystemOpenAttachmentArgs {
            workspace_id: imported.summary.id,
            attachment_id: "attachment-office".into(),
        };
        let presentation = store.prepare_attachment_for_system_open(&args).unwrap();
        assert_eq!(
            presentation.extension().and_then(|value| value.to_str()),
            Some("docx")
        );
        #[cfg(unix)]
        assert!(fs::symlink_metadata(&presentation)
            .unwrap()
            .file_type()
            .is_symlink());
        assert_eq!(fs::read(&presentation).unwrap(), bytes);
        #[cfg(windows)]
        {
            assert!(fs::symlink_metadata(&presentation).unwrap().is_file());
            assert!(!fs::symlink_metadata(&presentation)
                .unwrap()
                .file_type()
                .is_symlink());
            assert_eq!(
                store.prepare_attachment_for_system_open(&args).unwrap(),
                presentation
            );
            // External editors must never change the content-addressed original.
            fs::write(&presentation, b"externally edited copy").unwrap();
            assert_eq!(
                fs::read(store.root.join("assets").join(&digest)).unwrap(),
                bytes
            );
            assert!(store.prepare_attachment_for_system_open(&args).is_err());
            assert_eq!(fs::read(&presentation).unwrap(), b"externally edited copy");
        }
    }

    fn p6g_non_chat_test_candidate(model_id: &str) -> CatalogCandidate {
        serde_json::from_value(json!({
            "providerFamily":"OTHER","providerId":"ZHIPU","modelId":model_id,
            "displayName":"synthetic catalog identity","tiers":["BALANCED"],
            "capabilities":["TEXT"],"available":true,"knownCostMicros":0,"latencyRank":1,
            "contextWindowTokens":8192,"maxOutputTokens":1024,
        })).unwrap()
    }

