    #[test]
    fn p7e_owner_bridge_creates_only_an_isolated_workspace_and_never_a_tauri_entrypoint() {
        let (directory, store, imported) = imported_store();
        let snapshot = p7e_semantic_snapshot();
        let payload = json!({
            "format":"nfai.sync.payload", "protocolVersion":1, "schemaVersion":1,
            "appId":snapshot.app_id, "documentId":snapshot.document_id, "revision":snapshot.revision,
            "records": snapshot.records.iter().map(|record| json!({
                "kind":record.kind, "id":record.id, "revision":record.revision,
                "classification":record.classification,
                "content":serde_json::from_str::<Value>(&record.content_json).unwrap(),
            })).collect::<Vec<_>>(),
        });
        let envelope = sync_v1::seal_known(
            payload,
            "fixture recovery only",
            sync_v1::KnownMaterial {
                data_key: vec![7; 32],
                salt: vec![2; 16],
                wrapping_nonce: vec![3; 12],
                payload_nonce: vec![4; 12],
            },
        )
        .unwrap();

        let isolated_hash = store
            .open_p7e_to_new_isolated_workspace(
                &envelope,
                "fixture recovery only",
                "com.nanzhufeng.ai",
                "desktop-owner-p7e",
                2,
                "desktop-p7e-b",
            )
            .unwrap();

        assert_eq!(1, store.list_workspaces().unwrap().len());
        assert!(store.workspace_projection(&imported.summary.id).is_ok());
        assert!(directory
            .path()
            .join("app-data/p7e-isolated-workspace-v1/workspaces/desktop-p7e-b/workspace.sqlite3")
            .is_file());
        let readback = store.read_p7e_isolated_workspace("desktop-p7e-b").unwrap();
        assert_eq!(snapshot.app_id, readback.app_id);
        assert_eq!(snapshot.document_id, readback.document_id);
        assert_eq!(snapshot.revision, readback.revision);
        assert_eq!(snapshot.records.len(), readback.records.len());
        for (expected, actual) in snapshot.records.iter().zip(readback.records.iter()) {
            assert_eq!(expected.kind, actual.kind);
            assert_eq!(expected.id, actual.id);
            assert_eq!(expected.revision, actual.revision);
            assert_eq!(expected.classification, actual.classification);
            assert_eq!(
                serde_json::from_str::<Value>(&expected.content_json).unwrap(),
                serde_json::from_str::<Value>(&actual.content_json).unwrap(),
            );
        }
        assert_eq!(
            2,
            sync_v1::open(
                &store
                    .seal_p7e_isolated_workspace("desktop-p7e-b", "fixture recovery only", &[9; 32])
                    .unwrap(),
                "fixture recovery only",
                "com.nanzhufeng.ai",
                "desktop-owner-p7e",
                2,
            )
            .unwrap()
            .payload["revision"]
                .as_u64()
                .unwrap()
        );
        // A real store re-open must retain only the isolated P7-E owner state; the P6 workspace
        // remains independently readable and no Tauri command is involved.
        drop(store);
        let reopened = DesktopWorkspaceStore::open(directory.path().join("app-data")).unwrap();
        assert_eq!(1, reopened.list_workspaces().unwrap().len());
        let after_restart = reopened
            .read_p7e_isolated_workspace("desktop-p7e-b")
            .unwrap();
        assert_eq!(snapshot.revision, after_restart.revision);
        assert_eq!(snapshot.records.len(), after_restart.records.len());
        for (expected, actual) in snapshot.records.iter().zip(after_restart.records.iter()) {
            assert_eq!(expected.kind, actual.kind);
            assert_eq!(expected.id, actual.id);
            assert_eq!(expected.revision, actual.revision);
            assert_eq!(expected.classification, actual.classification);
            assert_eq!(
                serde_json::from_str::<Value>(&expected.content_json).unwrap(),
                serde_json::from_str::<Value>(&actual.content_json).unwrap(),
            );
        }
        assert!(reopened.workspace_projection(&imported.summary.id).is_ok());
        assert_eq!(64, isolated_hash.len());
    }

    #[test]
    fn selected_title_rename_persists_revision_and_retry_across_restart() {
        let (directory, store, imported) = imported_store();
        let conversation = &imported.exchange["conversations"][0];
        let id = conversation["id"].as_str().unwrap();
        let rename = |intent: &str, revision: u64, title: &str| store.mutate_domain(DomainMutationArgs {
            intent_id: intent.into(),workspace_id: imported.summary.id.clone(),entity: "conversation".into(),action: "update".into(),
            object_id: Some(id.into()),expected_revision: Some(revision),fields: json!({"title":title}),
        }).unwrap();
        let first = rename("title-local", conversation["revision"].as_u64().unwrap(), "第一次改名");
        let count: i64 = store.connection().unwrap().query_row("SELECT count(*) FROM desktop_sync_jobs WHERE stage='TITLE_PENDING'",[],|r| r.get(0)).unwrap();
        assert_eq!(count,0);
        store.connection().unwrap().execute("INSERT INTO desktop_selected_conversation_sync VALUES('fixture-account',?1,?2,'fixture-document',1,'remote','local',1)",params![imported.summary.id,id]).unwrap();
        rename("title-selected",first.revision,"第二次改名");
        let old: (String,String) = store.connection().unwrap().query_row("SELECT job_id,payload_hash FROM desktop_sync_jobs WHERE stage='TITLE_PENDING'",[],|r| Ok((r.get(0)?,r.get(1)?))).unwrap();
        let second = store.workspace_projection(&imported.summary.id).unwrap();
        let row = second.exchange["conversations"].as_array().unwrap().iter().find(|c|c["id"]==id).unwrap();
        assert_eq!(row["titleRevision"],2);
        rename("title-during-upload",row["revision"].as_u64().unwrap(),"第三次改名");
        store.apply_history(HistoryArgs{intent_id:"undo-title".into(),workspace_id:imported.summary.id.clone()},false).unwrap();
        store.apply_history(HistoryArgs{intent_id:"redo-title".into(),workspace_id:imported.summary.id.clone()},true).unwrap();
        let after_redo = store.workspace_projection(&imported.summary.id).unwrap();
        let title = after_redo.exchange["conversations"].as_array().unwrap().iter().find(|c|c["id"]==id).unwrap();
        assert_eq!(title["titleRevision"],5);
        assert_eq!(title["title"],"第三次改名");
        desktop_account_sync_v1::finish_pending_title_attempt(&store.connection().unwrap(),&old.0,&old.1,
            &Ok(desktop_account_sync_v1::SyncReceipt{status:"SYNCED_AFTER_RECONCILE".into(),safe_code:None,synced_at_ms:Some(1)})).unwrap();
        drop(store);
        let reopened = DesktopWorkspaceStore::open(directory.path().join("app-data")).unwrap();
        let row: (String,String) = reopened.connection().unwrap().query_row("SELECT stage,payload_hash FROM desktop_sync_jobs WHERE job_id=?1",[&old.0],|r| Ok((r.get(0)?,r.get(1)?))).unwrap();
        assert_eq!(row.0,"TITLE_PENDING");
        assert_ne!(row.1,old.1,"old upload must not acknowledge a later rename");
    }

    #[test]
    fn selected_pending_reconciled_commit_finishes_matching_job_across_restart() {
        for status in ["SYNCED_AFTER_RECONCILE", "SYNCED_AFTER_REMOTE_RECONCILE"] {
        let (directory, store, imported) = imported_store();
        let conversation = &imported.exchange["conversations"][0];
        let id = conversation["id"].as_str().unwrap();
        store.connection().unwrap().execute("INSERT INTO desktop_selected_conversation_sync VALUES('fixture-account',?1,?2,'fixture-document',1,'remote','local',1)",params![imported.summary.id,id]).unwrap();
        store.mutate_domain(DomainMutationArgs {
            intent_id: "title-reconciled-pending".into(), workspace_id: imported.summary.id.clone(),
            entity: "conversation".into(), action: "update".into(), object_id: Some(id.into()),
            expected_revision: conversation["revision"].as_u64(), fields: json!({"title":"已核对的改名"}),
        }).unwrap();
        let job: (String, String) = store.connection().unwrap().query_row(
            "SELECT job_id,payload_hash FROM desktop_sync_jobs WHERE stage='TITLE_PENDING'", [],
            |row| Ok((row.get(0)?, row.get(1)?)),
        ).unwrap();
        desktop_account_sync_v1::finish_pending_title_attempt(&store.connection().unwrap(), &job.0, &job.1,
            &Ok(desktop_account_sync_v1::SyncReceipt { status: status.into(), safe_code: None, synced_at_ms: Some(1) })).unwrap();
        drop(store);
        let reopened = DesktopWorkspaceStore::open(directory.path().join("app-data")).unwrap();
        let pending: i64 = reopened.connection().unwrap().query_row(
            "SELECT count(*) FROM desktop_sync_jobs WHERE job_id=?1", [&job.0], |row| row.get(0),
        ).unwrap();
        assert_eq!(pending, 0, "verified commit must finish its matching pending job rather than schedule another retry");
        assert_eq!(reopened.workspace_projection(&imported.summary.id).unwrap().exchange["conversations"][0]["title"], "已核对的改名");
        }
    }

    #[test]
    fn selected_soft_and_permanent_deletion_keep_a_durable_cloud_cleanup_job() {
        let (directory, store, imported) = imported_store();
        let conversation = &imported.exchange["conversations"][0];
        let id = conversation["id"].as_str().unwrap();
        store.connection().unwrap().execute("INSERT INTO desktop_selected_conversation_sync VALUES('fixture-account',?1,?2,'fixture-document',1,'remote','local',1)",params![imported.summary.id,id]).unwrap();
        let deleted = store.mutate_domain(DomainMutationArgs {
            intent_id: "delete-selected".into(), workspace_id: imported.summary.id.clone(), entity: "conversation".into(), action: "softDelete".into(),
            object_id: Some(id.into()), expected_revision: conversation["revision"].as_u64(), fields: json!({}),
        }).unwrap();
        let count = || store.connection().unwrap().query_row("SELECT count(*) FROM desktop_sync_jobs WHERE stage='DELETE_PENDING'",[],|r|r.get::<_,i64>(0)).unwrap();
        assert_eq!(count(),1);
        let job: (String,String) = store.connection().unwrap().query_row("SELECT job_id,payload_hash FROM desktop_sync_jobs WHERE stage='DELETE_PENDING'",[],|r|Ok((r.get(0)?,r.get(1)?))).unwrap();
        desktop_account_sync_v1::finish_pending_title_attempt(&store.connection().unwrap(), &job.0, &job.1, &Err("network unavailable".into())).unwrap();
        assert_eq!(count(),1,"failed deletion retains deletion intent rather than becoming an upload");
        store.permanently_delete_conversation(DesktopConversationPurgeArgs { workspace_id: imported.summary.id.clone(), conversation_id: id.into(), expected_revision: deleted.revision }).unwrap();
        assert_eq!(count(),1);
        drop(store);
        let reopened = DesktopWorkspaceStore::open(directory.path().join("app-data")).unwrap();
        let pending: i64 = reopened.connection().unwrap().query_row("SELECT count(*) FROM desktop_sync_jobs WHERE stage='DELETE_PENDING'",[],|r|r.get(0)).unwrap();
        assert_eq!(pending,1,"permanent local deletion cannot lose the cloud cleanup intent");
    }

    #[test]
    fn domain_intent_conflict_idempotency_undo_redo_and_export_are_persistent() {
        let (directory, store, imported) = imported_store();
        let create = DomainMutationArgs {
            intent_id: "intent-create-project-p6c".into(),
            workspace_id: imported.summary.id.clone(),
            entity: "project".into(),
            action: "create".into(),
            object_id: None,
            expected_revision: None,
            fields: json!({"title":"本地 P6-C 项目","description":"可撤销的本地项目"}),
        };
        let created = store.mutate_domain(create).unwrap();
        assert_eq!(created.revision, 1);
        assert!(
            store
                .mutate_domain(DomainMutationArgs {
                    intent_id: "intent-create-project-p6c".into(),
                    workspace_id: imported.summary.id.clone(),
                    entity: "project".into(),
                    action: "create".into(),
                    object_id: None,
                    expected_revision: None,
                    fields: json!({"title":"被重放的名称","description":"x"})
                })
                .unwrap()
                .replayed
        );
        let updated = store
            .mutate_domain(DomainMutationArgs {
                intent_id: "intent-update-project-p6c".into(),
                workspace_id: imported.summary.id.clone(),
                entity: "project".into(),
                action: "update".into(),
                object_id: Some(created.object_id.clone()),
                expected_revision: Some(1),
                fields: json!({"title":"已编辑项目"}),
            })
            .unwrap();
        assert_eq!(updated.revision, 2);
        assert!(store
            .mutate_domain(DomainMutationArgs {
                intent_id: "intent-conflict-project-p6c".into(),
                workspace_id: imported.summary.id.clone(),
                entity: "project".into(),
                action: "update".into(),
                object_id: Some(created.object_id.clone()),
                expected_revision: Some(1),
                fields: json!({"title":"不得覆盖"})
            })
            .unwrap_err()
            .contains("REVISION_CONFLICT"));
        let undone = store
            .apply_history(
                HistoryArgs {
                    intent_id: "intent-undo-project-p6c".into(),
                    workspace_id: imported.summary.id.clone(),
                },
                false,
            )
            .unwrap();
        assert_eq!(undone.revision, 3);
        let redone = store
            .apply_history(
                HistoryArgs {
                    intent_id: "intent-redo-project-p6c".into(),
                    workspace_id: imported.summary.id.clone(),
                },
                true,
            )
            .unwrap();
        assert_eq!(redone.revision, 4);
        let history = store.workbench_history(&imported.summary.id).unwrap();
        assert!(history.can_undo);
        drop(store);
        let reopened = DesktopWorkspaceStore::open(directory.path().join("app-data")).unwrap();
        assert!(
            reopened
                .workbench_history(&imported.summary.id)
                .unwrap()
                .can_undo
        );
        let output = directory.path().join("p6c-roundtrip.nfai-exchange");
        let receipt = reopened
            .export_workspace_to_path(&imported.summary.id, output.to_str().unwrap())
            .unwrap();
        assert_eq!(
            receipt.semantic_hash,
            reopened
                .workspace_projection(&imported.summary.id)
                .unwrap()
                .summary
                .semantic_hash
        );
        assert!(preflight_package(fs::read(output).unwrap()).is_ok());
    }

    #[test]
    fn undo_and_redo_of_a_created_object_do_not_require_it_in_the_before_snapshot() {
        let (_directory, store, imported) = imported_store();
        let created = store
            .mutate_domain(DomainMutationArgs {
                intent_id: "intent-create-undo-project-p6d".into(),
                workspace_id: imported.summary.id.clone(),
                entity: "project".into(),
                action: "create".into(),
                object_id: None,
                expected_revision: None,
                fields: json!({"title":"P6-D 可逆创建","description":"非敏感测试"}),
            })
            .unwrap();
        let undone = store
            .apply_history(
                HistoryArgs {
                    intent_id: "intent-undo-created-project-p6d".into(),
                    workspace_id: imported.summary.id.clone(),
                },
                false,
            )
            .unwrap();
        assert_eq!(undone.revision, 2);
        assert!(!store
            .workspace_projection(&imported.summary.id)
            .unwrap()
            .exchange["projects"]
            .as_array()
            .unwrap()
            .iter()
            .any(|item| item["id"] == created.object_id));
        let redone = store
            .apply_history(
                HistoryArgs {
                    intent_id: "intent-redo-created-project-p6d".into(),
                    workspace_id: imported.summary.id.clone(),
                },
                true,
            )
            .unwrap();
        assert_eq!(redone.revision, 2);
        assert!(store
            .workspace_projection(&imported.summary.id)
            .unwrap()
            .exchange["projects"]
            .as_array()
            .unwrap()
            .iter()
            .any(|item| item["id"] == created.object_id && item["revision"] == 2));
    }

