    #[test]
    fn domain_intent_replay_never_crosses_workspace_owner() {
        let directory = tempdir().unwrap();
        let store = DesktopWorkspaceStore::open(directory.path().join("app-data")).unwrap();
        let first = store.ensure_local_workspace().unwrap();
        let source = directory.path().join("second.nfai-exchange");
        fs::write(&source, golden()).unwrap();
        let staged = store.stage_selected_file(source.to_str().unwrap()).unwrap();
        let second = store
            .import_staged(ImportArgs {
                staging_id: staged.staging_id,
                workspace_title: "第二工作区".into(),
            })
            .unwrap();
        assert_ne!(first.summary.id, second.summary.id);
        let first_mutation = store
            .mutate_domain(DomainMutationArgs {
                intent_id: "shared-domain-intent-owner-check".into(),
                workspace_id: first.summary.id.clone(),
                entity: "project".into(),
                action: "create".into(),
                object_id: None,
                expected_revision: None,
                fields: json!({"title":"第一区新项目","description":"合成"}),
            })
            .unwrap();
        assert!(store
            .mutate_domain(DomainMutationArgs {
                intent_id: "shared-domain-intent-owner-check".into(),
                workspace_id: second.summary.id.clone(),
                entity: "project".into(),
                action: "create".into(),
                object_id: None,
                expected_revision: None,
                fields: json!({"title":"第二区新项目","description":"合成"}),
            })
            .is_err());
        assert!(store
            .apply_history(
                HistoryArgs {
                    intent_id: "shared-domain-intent-owner-check".into(),
                    workspace_id: second.summary.id.clone(),
                },
                false,
            )
            .is_err());
        assert!(store
            .upsert_model_metadata(ModelMetadataArgs {
                intent_id: "shared-domain-intent-owner-check".into(),
                workspace_id: second.summary.id.clone(),
                expected_revision: 0,
                provider_id: "openrouter".into(),
                model_id: "terra-model".into(),
                metadata: json!({}),
            })
            .is_err());
        assert!(store.apply_history(HistoryArgs {
            intent_id: "shared-domain-intent-owner-check".into(),
            workspace_id: first.summary.id.clone(),
        }, false).is_err());
        assert!(store.upsert_model_metadata(ModelMetadataArgs {
            intent_id: "shared-domain-intent-owner-check".into(),
            workspace_id: first.summary.id.clone(),
            expected_revision: 0,
            provider_id: "openrouter".into(),
            model_id: "terra-model".into(),
            metadata: json!({}),
        }).is_err());
        let replay = store
            .mutate_domain(DomainMutationArgs {
                intent_id: "shared-domain-intent-owner-check".into(),
                workspace_id: first.summary.id.clone(),
                entity: "project".into(),
                action: "create".into(),
                object_id: None,
                expected_revision: None,
                fields: json!({"title":"第一区新项目","description":"合成"}),
            })
            .unwrap();
        assert!(replay.replayed);
        assert_eq!(replay.object_id, first_mutation.object_id);
        assert!(!store.workspace_projection(&second.summary.id).unwrap().exchange["projects"]
            .as_array().unwrap().iter().any(|item| item["title"] == "第二区新项目"));
        let first_undo = store.apply_history(HistoryArgs {
            intent_id: "shared-undo-intent-owner-check".into(),
            workspace_id: first.summary.id.clone(),
        }, false).unwrap();
        assert!(!first_undo.replayed);
        assert!(store.apply_history(HistoryArgs {
            intent_id: "shared-undo-intent-owner-check".into(),
            workspace_id: second.summary.id.clone(),
        }, false).is_err());
        let metadata = || ModelMetadataArgs {
            intent_id: "model-metadata-target-owner-check".into(),
            workspace_id: first.summary.id.clone(),
            expected_revision: 0,
            provider_id: "openrouter".into(),
            model_id: "terra-model".into(),
            metadata: json!({}),
        };
        assert!(!store.upsert_model_metadata(metadata()).unwrap().replayed);
        assert!(store.upsert_model_metadata(metadata()).unwrap().replayed);
        assert!(store.upsert_model_metadata(ModelMetadataArgs {
            model_id: "other-model".into(),
            ..metadata()
        }).is_err());
    }

