    #[test]
    fn model_metadata_never_enters_domain_undo_stack() {
        let (directory, store, imported) = imported_store();
        let workspace_id = imported.summary.id;
        store.upsert_model_metadata(ModelMetadataArgs {
            intent_id: "metadata-undo-boundary".into(),
            workspace_id: workspace_id.clone(),
            expected_revision: 0,
            provider_id: "openrouter".into(),
            model_id: "terra-model".into(),
            metadata: json!({"pricingStatus":"UNKNOWN"}),
        }).unwrap();
        let history = store.workbench_history(&workspace_id).unwrap();
        assert!(!history.can_undo && !history.can_redo);
        assert!(store.apply_history(HistoryArgs {
            intent_id: "metadata-undo-must-reject".into(),
            workspace_id: workspace_id.clone(),
        }, false).is_err());

        let project = store.mutate_domain(DomainMutationArgs {
            intent_id: "project-after-metadata-undo-boundary".into(),
            workspace_id: workspace_id.clone(),
            entity: "project".into(),
            action: "create".into(),
            object_id: None,
            expected_revision: None,
            fields: json!({"title":"可撤销项目","description":"合成"}),
        }).unwrap();
        assert!(store.workbench_history(&workspace_id).unwrap().can_undo);
        store.apply_history(HistoryArgs {
            intent_id: "undo-project-after-metadata".into(),
            workspace_id: workspace_id.clone(),
        }, false).unwrap();
        assert!(!store.workbench_history(&workspace_id).unwrap().can_undo);
        assert!(store.workbench_history(&workspace_id).unwrap().can_redo);
        assert_eq!(store.workbench_history(&workspace_id).unwrap().model_metadata.len(), 1);
        assert!(store.workspace_projection(&workspace_id).unwrap().exchange["projects"]
            .as_array().unwrap().iter().all(|item| item["id"] != project.object_id));
        drop(store);
        let reopened = DesktopWorkspaceStore::open(directory.path().join("app-data")).unwrap();
        assert!(!reopened.workbench_history(&workspace_id).unwrap().can_undo);
        assert!(reopened.workbench_history(&workspace_id).unwrap().can_redo);
        reopened.apply_history(HistoryArgs {
            intent_id: "redo-project-after-metadata".into(),
            workspace_id: workspace_id.clone(),
        }, true).unwrap();
        assert!(reopened.workspace_projection(&workspace_id).unwrap().exchange["projects"]
            .as_array().unwrap().iter().any(|item| item["id"] == project.object_id));
        assert_eq!(reopened.workbench_history(&workspace_id).unwrap().model_metadata.len(), 1);
        assert_eq!(reopened.connection().unwrap().query_row(
            "PRAGMA integrity_check", [], |row| row.get::<_, String>(0),
        ).unwrap(), "ok");
    }

