    #[test]
    fn temporary_noop_does_not_renew_and_expired_id_cannot_be_resurrected() {
        let directory = tempdir().unwrap();
        let store = DesktopWorkspaceStore::open(directory.path().join("app-data")).unwrap();
        let started = 1_000_000_i64;
        let entered = store.enter_or_restore_temporary_at(None, started).unwrap();
        let changed = store.update_temporary_at(TemporaryConversationUpdateArgs {
            temporary_id: entered.temporary_id.clone(), draft: "合成临时草稿".into(),
            model_override_id: Some("local.fixture-v1".into()),
        }, started + 100).unwrap();
        let expiry = changed.updated_at_ms + ATTACHMENT_RETENTION_MILLIS;
        let no_op = store.update_temporary_at(TemporaryConversationUpdateArgs {
            temporary_id: entered.temporary_id.clone(), draft: changed.draft.clone(),
            model_override_id: changed.model_override_id.clone(),
        }, expiry - 1).unwrap();
        assert_eq!(no_op.updated_at_ms, changed.updated_at_ms);
        store.prune_temporary_at(expiry).unwrap();
        assert!(store.read_temporary_recovery_at(expiry).unwrap().is_none());
        assert!(store.enter_or_restore_temporary_at(Some(entered.temporary_id.clone()), expiry + 1).is_err());
        assert!(store.update_temporary_at(TemporaryConversationUpdateArgs {
            temporary_id: entered.temporary_id.clone(), draft: "过期后写入".into(),
            model_override_id: None,
        }, expiry + 1).is_err());
        assert!(store.read_temporary_recovery_at(expiry + 1).unwrap().is_none());
        let fresh = store.enter_or_restore_temporary_at(None, expiry + 2).unwrap();
        let edited = store.update_temporary_at(TemporaryConversationUpdateArgs {
            temporary_id: fresh.temporary_id.clone(), draft: "新草稿".into(),
            model_override_id: None,
        }, expiry + 3).unwrap();
        let renewed_at = edited.updated_at_ms + ATTACHMENT_RETENTION_MILLIS - 1;
        let renewed = store.update_temporary_at(TemporaryConversationUpdateArgs {
            temporary_id: fresh.temporary_id.clone(), draft: "继续编辑".into(),
            model_override_id: None,
        }, renewed_at).unwrap();
        assert_eq!(renewed.updated_at_ms, renewed_at);
        assert!(store.read_temporary_recovery_at(edited.updated_at_ms + ATTACHMENT_RETENTION_MILLIS)
            .unwrap().is_some());
    }

