    #[test]
    fn desktop_model_service_settings_migrate_persist_and_reject_stale_or_retired_values() {
        let directory = tempdir().unwrap();
        let root = directory.path().join("app-data");
        let store = DesktopWorkspaceStore::open(root.clone()).unwrap();
        let defaults = store.read_desktop_model_service_setting_records().unwrap();
        assert_eq!(
            defaults
                .iter()
                .map(|item| item.provider_id.as_str())
                .collect::<Vec<_>>(),
            vec!["OPENROUTER", "DEEPSEEK", "ZHIPU", "QWEN", "RELAYCORE_CLAUDE", "RELAYCORE_GPT", "RELAYCORE_GEMINI"]
        );
        let saved = store
            .save_desktop_model_service_setting_record("DEEPSEEK", true, "DEEPSEEK_V4_FLASH", 0)
            .unwrap();
        assert_eq!(saved.revision, 1);
        assert!(store
            .save_desktop_model_service_setting_record("DEEPSEEK", false, "DEEPSEEK_V4_PRO", 0,)
            .is_err());
        assert!(store
            .save_desktop_model_service_setting_record("OPENROUTER", true, "GROK_4_6", 0)
            .is_err());
        store
            .connection()
            .unwrap()
            .execute(
                "INSERT INTO desktop_provider_settings(provider_id,enabled,preset_id,revision,updated_at_ms) VALUES(?1,?2,?3,?4,?5)",
                params!["OPENROUTER", 1, "GEMINI_3_7_FLASH", 4, local_now_millis()],
            )
            .unwrap();
        let openrouter = store
            .read_desktop_model_service_setting_records()
            .unwrap()
            .into_iter()
            .find(|item| item.provider_id == "OPENROUTER")
            .unwrap();
        assert_eq!(openrouter.preset_id, "GEMINI_3_8_FLASH");
        // Read-time canonical projection does not invent a configuration write.
        assert_eq!(openrouter.revision, 4);
        let table_sql: String = store
            .connection()
            .unwrap()
            .query_row(
                "SELECT sql FROM sqlite_master WHERE type='table' AND name='desktop_provider_settings'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        for forbidden in ["api_key", "credential", "endpoint", "secret"] {
            assert!(!table_sql.to_ascii_lowercase().contains(forbidden));
        }
        drop(store);

        let reopened = DesktopWorkspaceStore::open(root).unwrap();
        let deepseek = reopened
            .read_desktop_model_service_setting_records()
            .unwrap()
            .into_iter()
            .find(|item| item.provider_id == "DEEPSEEK")
            .unwrap();
        assert!(deepseek.enabled);
        assert_eq!(deepseek.preset_id, "DEEPSEEK_V4_FLASH");
        assert_eq!(deepseek.revision, 1);
    }

    #[test]
    fn pending_model_setting_recovers_sqlite_abort_and_committed_update_after_reopen() {
        let directory = tempdir().unwrap();
        let root = directory.path().join("app-data");
        let store = DesktopWorkspaceStore::open(root.clone()).unwrap();
        let credentials = desktop_model_service_v1::AppPrivateProviderCredentialStore::at(&root);
        credentials
            .save_user_provided_secret("QWEN", b"previous-provider-secret")
            .unwrap();
        let previous = store.read_desktop_model_service_setting_record_raw("QWEN").unwrap();
        let target = desktop_model_service_v1::ModelSettingState {
            provider_id: "QWEN".into(),
            enabled: true,
            preset_id: "QWEN_3_8_MAX".into(),
            revision: 1,
        };
        store
            .configuration_connection()
            .unwrap()
            .execute_batch(
                "CREATE TRIGGER reject_qwen_save BEFORE INSERT ON desktop_provider_settings
                 WHEN NEW.provider_id='QWEN' BEGIN SELECT RAISE(ABORT,'fixture commit failure'); END;",
            )
            .unwrap();
        credentials
            .begin_model_setting_secret_update(
                model_setting_state(&previous),
                target.clone(),
                b"replacement-provider-secret",
            )
            .unwrap();
        assert!(store
            .save_desktop_model_service_setting_record("QWEN", true, "QWEN_3_8_MAX", 0)
            .is_err());
        assert_eq!(
            credentials.presence("QWEN"),
            desktop_model_service_v1::CredentialPresence::Unavailable
        );
        drop(store);
        let reopened = DesktopWorkspaceStore::open(root.clone()).unwrap();
        assert_eq!(
            reconcile_pending_model_setting(&reopened, &credentials)
                .unwrap()
                .unwrap()
                .1,
            desktop_model_service_v1::ModelSettingResolution::RestoredPrevious
        );
        assert_eq!(
            credentials
                .with_secret("QWEN", |secret| Ok(secret.to_vec()))
                .unwrap(),
            b"previous-provider-secret"
        );
        reopened
            .configuration_connection()
            .unwrap()
            .execute_batch("DROP TRIGGER reject_qwen_save")
            .unwrap();
        credentials
            .begin_model_setting_secret_update(
                model_setting_state(&previous),
                target,
                b"updated-provider-secret",
            )
            .unwrap();
        reopened
            .save_desktop_model_service_setting_record("QWEN", true, "QWEN_3_8_MAX", 0)
            .unwrap();
        drop(reopened);
        let reopened = DesktopWorkspaceStore::open(root).unwrap();
        let (committed, resolution) = reconcile_pending_model_setting(&reopened, &credentials)
            .unwrap()
            .unwrap();
        assert_eq!(
            resolution,
            desktop_model_service_v1::ModelSettingResolution::CommittedNew
        );
        assert_eq!(committed.revision, 1);
        assert_eq!(committed.preset_id, "QWEN_3_8_MAX");
        assert_eq!(
            credentials
                .with_secret("QWEN", |secret| Ok(secret.to_vec()))
                .unwrap(),
            b"updated-provider-secret"
        );
    }

    #[test]
    fn pending_model_setting_kill_child() {
        let Some(root) = std::env::var_os("NANFENG_AI_MODEL_PENDING_KILL_TEST_ROOT") else {
            return;
        };
        let phase = std::env::var("NANFENG_AI_MODEL_PENDING_KILL_TEST_PHASE").unwrap();
        let root = PathBuf::from(root);
        let store = DesktopWorkspaceStore::open(root.clone()).unwrap();
        let credentials = desktop_model_service_v1::AppPrivateProviderCredentialStore::at(&root);
        let before = store.read_desktop_model_service_setting_record_raw("QWEN").unwrap();
        assert_eq!(before.revision, 0);
        credentials
            .begin_model_setting_secret_update(
                model_setting_state(&before),
                desktop_model_service_v1::ModelSettingState {
                    provider_id: "QWEN".into(),
                    enabled: true,
                    preset_id: "QWEN_3_8_MAX".into(),
                    revision: 1,
                },
                b"replacement-provider-secret",
            )
            .unwrap();
        if phase == "after-sqlite" {
            store
                .save_desktop_model_service_setting_record("QWEN", true, "QWEN_3_8_MAX", 0)
                .unwrap();
        } else {
            assert_eq!(phase, "before-sqlite");
        }
        fs::write(root.join("model-pending-kill-point.reached"), phase.as_bytes()).unwrap();
        loop {
            std::thread::park_timeout(std::time::Duration::from_secs(1));
        }
    }

    #[cfg(windows)]
    #[test]
    fn pending_model_setting_process_kill_recovers_both_commit_sides() {
        for phase in ["before-sqlite", "after-sqlite"] {
            let directory = tempdir().unwrap();
            let root = directory.path().join("app-data");
            let store = DesktopWorkspaceStore::open(root.clone()).unwrap();
            let credentials = desktop_model_service_v1::AppPrivateProviderCredentialStore::at(&root);
            credentials
                .save_user_provided_secret("QWEN", b"previous-provider-secret")
                .unwrap();
            credentials
                .save_user_provided_secret("DEEPSEEK", b"unrelated-provider-secret")
                .unwrap();
            drop(store);

            let mut child = Command::new(std::env::current_exe().unwrap())
                .args(["--exact", "tests::pending_model_setting_kill_child", "--nocapture"])
                .env("NANFENG_AI_MODEL_PENDING_KILL_TEST_ROOT", &root)
                .env("NANFENG_AI_MODEL_PENDING_KILL_TEST_PHASE", phase)
                .stdout(Stdio::null())
                .stderr(Stdio::null())
                .spawn()
                .unwrap();
            let marker = root.join("model-pending-kill-point.reached");
            let deadline = std::time::Instant::now() + std::time::Duration::from_secs(30);
            while !marker.exists() && std::time::Instant::now() < deadline {
                if let Some(status) = child.try_wait().unwrap() {
                    panic!("model pending child exited before {phase}: {status}");
                }
                std::thread::sleep(std::time::Duration::from_millis(20));
            }
            child.kill().unwrap();
            child.wait().unwrap();
            assert_eq!(fs::read(&marker).unwrap(), phase.as_bytes());
            let pending = root.join("provider-credentials-v1/model-setting-pending-v1.json");
            let pending_bytes = fs::read(&pending).unwrap();
            assert!(!pending_bytes.windows(b"previous-provider-secret".len()).any(|window| window == b"previous-provider-secret"));
            assert!(!pending_bytes.windows(b"replacement-provider-secret".len()).any(|window| window == b"replacement-provider-secret"));
            assert_eq!(
                credentials.presence("QWEN"),
                desktop_model_service_v1::CredentialPresence::Unavailable
            );

            let reopened = DesktopWorkspaceStore::open(root.clone()).unwrap();
            let (record, resolution) = reconcile_pending_model_setting(&reopened, &credentials)
                .unwrap()
                .unwrap();
            let (revision, preset, secret, expected_resolution) = if phase == "before-sqlite" {
                (0, "QWEN_3_7_PLUS", b"previous-provider-secret".as_slice(),
                    desktop_model_service_v1::ModelSettingResolution::RestoredPrevious)
            } else {
                (1, "QWEN_3_8_MAX", b"replacement-provider-secret".as_slice(),
                    desktop_model_service_v1::ModelSettingResolution::CommittedNew)
            };
            assert_eq!(resolution, expected_resolution);
            assert_eq!(record.revision, revision);
            assert_eq!(record.preset_id, preset);
            assert_eq!(
                credentials.with_secret("QWEN", |value| Ok(value.to_vec())).unwrap(),
                secret
            );
            assert_eq!(
                credentials.with_secret("DEEPSEEK", |value| Ok(value.to_vec())).unwrap(),
                b"unrelated-provider-secret"
            );
            assert!(!pending.exists());
            assert!(reconcile_pending_model_setting(&reopened, &credentials).unwrap().is_none());
        }
    }

    #[cfg(windows)]
    #[test]
    fn pending_model_setting_survives_storage_location_switch_and_recovers_in_new_root() {
        for committed in [false, true] {
            let directory = tempdir().unwrap();
            let old = directory.path().join("old-app-data");
            let new = directory.path().join("new-app-data");
            fs::create_dir(&new).unwrap();
            let store = DesktopWorkspaceStore::open(old.clone()).unwrap();
            let credentials = desktop_model_service_v1::AppPrivateProviderCredentialStore::at(&old);
            credentials
                .save_user_provided_secret("QWEN", b"previous-provider-secret")
                .unwrap();
            let before = store.read_desktop_model_service_setting_record_raw("QWEN").unwrap();
            credentials
                .begin_model_setting_secret_update(
                    model_setting_state(&before),
                    desktop_model_service_v1::ModelSettingState {
                        provider_id: "QWEN".into(),
                        enabled: true,
                        preset_id: "QWEN_3_8_MAX".into(),
                        revision: 1,
                    },
                    b"replacement-provider-secret",
                )
                .unwrap();
            if committed {
                store
                    .save_desktop_model_service_setting_record("QWEN", true, "QWEN_3_8_MAX", 0)
                    .unwrap();
            }
            drop(store);
            let location = directory.path().join("configuration/location.json");
            desktop_storage_location::schedule(&location, &old, &new).unwrap();
            assert_eq!(
                desktop_storage_location::resolve(&location, &old).unwrap(),
                fs::canonicalize(&new).unwrap()
            );
            let pending = Path::new("provider-credentials-v1/model-setting-pending-v1.json");
            assert_eq!(fs::read(old.join(pending)).unwrap(), fs::read(new.join(pending)).unwrap());
            assert_eq!(
                fs::read(old.join("provider-credentials-v1/local.key")).unwrap(),
                fs::read(new.join("provider-credentials-v1/local.key")).unwrap()
            );
            let moved_credentials =
                desktop_model_service_v1::AppPrivateProviderCredentialStore::at(&new);
            assert_eq!(
                moved_credentials.presence("QWEN"),
                desktop_model_service_v1::CredentialPresence::Unavailable
            );
            let moved_store = DesktopWorkspaceStore::open(new.clone()).unwrap();
            let (record, resolution) =
                reconcile_pending_model_setting(&moved_store, &moved_credentials)
                    .unwrap()
                    .unwrap();
            assert_eq!(record.revision, if committed { 1 } else { 0 });
            assert_eq!(
                resolution,
                if committed {
                    desktop_model_service_v1::ModelSettingResolution::CommittedNew
                } else {
                    desktop_model_service_v1::ModelSettingResolution::RestoredPrevious
                }
            );
            assert_eq!(
                moved_credentials.with_secret("QWEN", |secret| Ok(secret.to_vec())).unwrap(),
                if committed {
                    b"replacement-provider-secret".as_slice()
                } else {
                    b"previous-provider-secret".as_slice()
                }
            );
            assert!(!new.join(pending).exists());
            assert!(old.join(pending).exists());
        }
    }

    #[test]
    fn prepared_ordinary_chat_does_not_use_a_rotated_provider_key() {
        let (_directory, store, imported) = imported_store();
        store
            .save_desktop_model_service_setting_record("QWEN", true, "QWEN_3_7_PLUS", 0)
            .unwrap();
        store
            .credentials
            .save_user_provided_secret("QWEN", b"previous-provider-secret")
            .unwrap();
        let prepared = store
            .prepare_ordinary_chat(
                DesktopOrdinaryChatSubmitArgs {
                    workspace_id: imported.summary.id,
                    conversation_id: None,
                    project_id: None,
                    expected_revision: None,
                    text: "合成模型设置竞态".into(),
                    attachment_ids: vec![],
                    model_id: Some("QWEN_3_7_PLUS".into()),
                    tone_override: None,
                    web_search_override: None,
                    egress_authorization: None,
                },
                None,
            )
            .unwrap();
        assert_eq!(prepared.provider_id, "QWEN");
        assert_eq!(prepared.provider_setting_revision, Some(1));
        let first = read_ordinary_chat_bound_secret(
            &store.credentials,
            &prepared.provider_id,
            prepared.provider_setting_revision,
            |provider_id| store.read_desktop_model_service_setting_record_raw(provider_id),
        )
        .unwrap();
        assert_eq!(first.as_slice(), b"previous-provider-secret");
        drop(first);

        let before = store.read_desktop_model_service_setting_record_raw("QWEN").unwrap();
        store
            .credentials
            .begin_model_setting_secret_update(
                model_setting_state(&before),
                desktop_model_service_v1::ModelSettingState {
                    provider_id: "QWEN".into(),
                    enabled: true,
                    preset_id: "QWEN_3_8_MAX".into(),
                    revision: 2,
                },
                b"replacement-provider-secret",
            )
            .unwrap();
        assert!(read_ordinary_chat_bound_secret(
            &store.credentials,
            &prepared.provider_id,
            prepared.provider_setting_revision,
            |provider_id| store.read_desktop_model_service_setting_record_raw(provider_id),
        )
        .is_err());
        store
            .save_desktop_model_service_setting_record("QWEN", true, "QWEN_3_8_MAX", 1)
            .unwrap();
        reconcile_pending_model_setting(&store, &store.credentials).unwrap();
        let error = read_ordinary_chat_bound_secret(
            &store.credentials,
            &prepared.provider_id,
            prepared.provider_setting_revision,
            |provider_id| store.read_desktop_model_service_setting_record_raw(provider_id),
        )
        .unwrap_err();
        assert_eq!(ordinary_chat_credential_failure_code(&error), "MODEL_SETTINGS_CHANGED");
        let current = read_ordinary_chat_bound_secret(&store.credentials, "QWEN", Some(2), |id| {
            store.read_desktop_model_service_setting_record_raw(id)
        })
        .unwrap();
        assert_eq!(current.as_slice(), b"replacement-provider-secret");
    }

