    #[test]
    fn privacy_failed_task_cleanup_requires_explicit_fresh_selection_and_removes_private_copy() {
        let (directory, store, _imported) = imported_store();
        let task_id = "privacy-failed-task";
        let storage_key = format!("chatgpt-import-assets/{task_id}/fixture.json");
        let asset = store.root.join(&storage_key);
        fs::create_dir_all(asset.parent().unwrap()).unwrap();
        fs::write(&asset, b"failed private import bytes").unwrap();
        store.connection().unwrap().execute(
            "INSERT INTO chatgpt_import_tasks(id,status,storage_key,display_name,mime_type,byte_count,package_hash,failure,retry_count,created_at_ms,updated_at_ms) VALUES(?1,'FAILED',?2,'fixture.json','application/json',27,'fixture-hash','PARSE_FAILED',0,1,1)",
            params![task_id, storage_key],
        ).unwrap();

        let first = store
            .preview_desktop_privacy_deletion(DesktopPrivacyPreviewArgs {
                scope: "TEMPORARY_FAILED_TASK_ASSETS".into(),
                selected_task_ids: BTreeSet::new(),
            })
            .unwrap();
        assert_eq!(first.task_candidates.len(), 1);
        assert!(first.aggregates.is_empty());
        let selection_id = first.task_candidates[0].selection_id.clone();
        let selected = BTreeSet::from([selection_id]);
        let stale = store
            .preview_desktop_privacy_deletion(DesktopPrivacyPreviewArgs {
                scope: "TEMPORARY_FAILED_TASK_ASSETS".into(),
                selected_task_ids: selected.clone(),
            })
            .unwrap();
        fs::write(asset.parent().unwrap().join("changed.bin"), b"changed").unwrap();
        assert!(store
            .delete_desktop_privacy_scope(DesktopPrivacyDeleteArgs {
                scope: stale.scope,
                preview_fingerprint: stale.fingerprint,
                confirmation_phrase: String::new(),
                selected_task_ids: selected.clone(),
            })
            .is_err());

        let current = store
            .preview_desktop_privacy_deletion(DesktopPrivacyPreviewArgs {
                scope: "TEMPORARY_FAILED_TASK_ASSETS".into(),
                selected_task_ids: selected.clone(),
            })
            .unwrap();
        let result = store
            .delete_desktop_privacy_scope(DesktopPrivacyDeleteArgs {
                scope: current.scope,
                preview_fingerprint: current.fingerprint,
                confirmation_phrase: String::new(),
                selected_task_ids: selected,
            })
            .unwrap();
        assert!(!result.cleanup_pending);
        assert!(!asset.parent().unwrap().exists());
        assert_eq!(
            store
                .connection()
                .unwrap()
                .query_row(
                    "SELECT COUNT(*) FROM chatgpt_import_tasks WHERE id=?1",
                    [task_id],
                    |row| row.get::<_, u64>(0),
                )
                .unwrap(),
            0
        );
        drop(directory);
    }

    #[test]
    fn privacy_trash_rejects_same_size_restored_and_redeleted_revision() {
        let (_directory, store, imported) = imported_store();
        let item = imported.exchange["knowledge"].as_array().unwrap().first().unwrap();
        let object_id = item["id"].as_str().unwrap().to_owned();
        let revision = item["revision"].as_u64().unwrap();
        let mutate = |intent: &str, action: &str, expected_revision: u64| {
            store.mutate_domain(DomainMutationArgs {
                intent_id: intent.into(), workspace_id: imported.summary.id.clone(),
                entity: "knowledge".into(), action: action.into(), object_id: Some(object_id.clone()),
                expected_revision: Some(expected_revision), fields: json!({}),
            }).unwrap()
        };
        mutate("trash-review-delete-a", "softDelete", revision);
        let preview = store.preview_desktop_privacy_deletion(DesktopPrivacyPreviewArgs {
            scope: "KNOWLEDGE_MEMORY_TRASH".into(), selected_task_ids: BTreeSet::new(),
        }).unwrap();
        mutate("trash-review-restore-a", "restore", revision + 1);
        mutate("trash-review-delete-b", "softDelete", revision + 2);
        let fresh = store.preview_desktop_privacy_deletion(DesktopPrivacyPreviewArgs {
            scope: "KNOWLEDGE_MEMORY_TRASH".into(), selected_task_ids: BTreeSet::new(),
        }).unwrap();
        assert_eq!(serde_json::to_value(&preview.aggregates).unwrap(), serde_json::to_value(&fresh.aggregates).unwrap(), "same-size replacement is not authorized by aggregate counts");
        assert_ne!(preview.fingerprint, fresh.fingerprint, "review must bind the actual deleted revision");
        let before = store.workspace_projection(&imported.summary.id).unwrap();
        assert!(store.delete_desktop_privacy_scope(DesktopPrivacyDeleteArgs {
            scope: preview.scope.clone(), preview_fingerprint: preview.fingerprint.clone(),
            confirmation_phrase: String::new(), selected_task_ids: BTreeSet::new(),
        }).is_err());
        assert_eq!(before.exchange, store.workspace_projection(&imported.summary.id).unwrap().exchange);
        assert!(store.purge_knowledge_memory_trash(&preview.fingerprint).is_err(), "write owner must also reject a stale confirmation after its outer check");
        assert_eq!(before.exchange, store.workspace_projection(&imported.summary.id).unwrap().exchange);
        store.delete_desktop_privacy_scope(DesktopPrivacyDeleteArgs {
            scope: fresh.scope, preview_fingerprint: fresh.fingerprint,
            confirmation_phrase: String::new(), selected_task_ids: BTreeSet::new(),
        }).unwrap();
        assert!(store.workspace_projection(&imported.summary.id).unwrap().exchange["knowledge"].as_array().unwrap().is_empty());
    }

    #[test]
    fn privacy_knowledge_memory_cleanup_only_purges_deleted_trash_and_full_snapshots() {
        let (directory, store, imported) = imported_store();
        let knowledge = imported.exchange["knowledge"]
            .as_array()
            .unwrap()
            .first()
            .unwrap();
        let memory = imported.exchange["memory"]
            .as_array()
            .unwrap()
            .first()
            .unwrap();
        for (entity, item) in [("knowledge", knowledge), ("memory", memory)] {
            store
                .mutate_domain(DomainMutationArgs {
                    intent_id: format!("privacy-delete-{entity}"),
                    workspace_id: imported.summary.id.clone(),
                    entity: entity.into(),
                    action: "softDelete".into(),
                    object_id: Some(item["id"].as_str().unwrap().into()),
                    expected_revision: item["revision"].as_u64(),
                    fields: json!({}),
                })
                .unwrap();
        }
        let preview = store
            .preview_desktop_privacy_deletion(DesktopPrivacyPreviewArgs {
                scope: "KNOWLEDGE_MEMORY_TRASH".into(),
                selected_task_ids: BTreeSet::new(),
            })
            .unwrap();
        assert_eq!(
            preview
                .aggregates
                .iter()
                .map(|item| item.count)
                .sum::<u64>(),
            2
        );
        store
            .delete_desktop_privacy_scope(DesktopPrivacyDeleteArgs {
                scope: preview.scope,
                preview_fingerprint: preview.fingerprint,
                confirmation_phrase: String::new(),
                selected_task_ids: BTreeSet::new(),
            })
            .unwrap();
        let readback = store.workspace_projection(&imported.summary.id).unwrap();
        assert!(readback.exchange["knowledge"]
            .as_array()
            .unwrap()
            .is_empty());
        assert!(readback.exchange["memory"].as_array().unwrap().is_empty());
        assert_eq!(
            store
                .connection()
                .unwrap()
                .query_row(
                    "SELECT COUNT(*) FROM domain_intents WHERE workspace_id=?1 AND (entity!='purged' OR action!='purged' OR object_id!='purged' OR undone!=1 OR before_exchange_json!='{}' OR after_exchange_json!='{}')",
                    [&imported.summary.id],
                    |row| row.get::<_, u64>(0),
                )
                .unwrap(),
            0
        );
        assert_eq!(store.connection().unwrap().query_row(
            "SELECT COUNT(*) FROM domain_intents WHERE workspace_id=?1 AND action='purged'",
            [&imported.summary.id], |row| row.get::<_, u64>(0),
        ).unwrap(), 2);
        drop(store);
        let reopened = DesktopWorkspaceStore::open(directory.path().join("app-data")).unwrap();
        assert!(reopened.mutate_domain(DomainMutationArgs {
            intent_id: "privacy-delete-knowledge".into(),
            workspace_id: imported.summary.id.clone(),
            entity: "project".into(),
            action: "create".into(),
            object_id: None,
            expected_revision: None,
            fields: json!({"title":"旧知识删除 ID 不得重建项目","description":"合成"}),
        }).is_err());
        assert!(reopened.mutate_domain(DomainMutationArgs {
            intent_id: "privacy-delete-memory".into(),
            workspace_id: imported.summary.id.clone(),
            entity: "memory".into(),
            action: "softDelete".into(),
            object_id: Some(memory["id"].as_str().unwrap().into()),
            expected_revision: memory["revision"].as_u64(),
            fields: json!({}),
        }).is_err());
        assert!(!reopened.workbench_history(&imported.summary.id).unwrap().can_undo);
        assert!(!reopened.workbench_history(&imported.summary.id).unwrap().can_redo);
        assert!(reopened.workspace_projection(&imported.summary.id).unwrap().exchange["projects"]
            .as_array().unwrap().iter().all(|item| item["title"] != "旧知识删除 ID 不得重建项目"));
        assert_eq!(reopened.connection().unwrap().query_row(
            "PRAGMA integrity_check", [], |row| row.get::<_, String>(0),
        ).unwrap(), "ok");
    }

