    #[test]
    fn usage_outcome_matches_durable_attempt_and_never_infers_failed_duration() {
        for failed in [false, true] {
            let (_directory, store, imported) = imported_store();
            let prepared = store.prepare_ordinary_chat(DesktopOrdinaryChatSubmitArgs {
                workspace_id: imported.summary.id.clone(), conversation_id: None, project_id: None,
                expected_revision: None, text: "synthetic usage outcome".into(), attachment_ids: vec![],
                model_id: None, tone_override: None, web_search_override: Some(false), egress_authorization: None,
            }, Some("http://127.0.0.1:1/chat/completions")).unwrap();
            let completed = desktop_ordinary_chat_v1::Completed {
                text: "synthetic measured response".into(), reasoning: None,
                usage: desktop_ordinary_chat_v1::Usage { input_tokens: Some(11), output_tokens: Some(7), cached_input_tokens: None, reasoning_tokens: None },
                reported_cost_micros: Some(9), actual_model_id: Some("fixture-actual".into()), web_search_verified: false, elapsed_ms: 999999,

                native_sources: Vec::new(),
            };
            let id = &prepared.projection.attempt_id;
            store.update_ordinary_chat_message(id, &completed.text, if failed { "FAILED" } else { "COMPLETE" }, None, Some(&completed), failed.then_some("OUTPUT_LIMIT")).unwrap();
            store.complete_ordinary_chat_accounting(id, &completed).unwrap();
            let entries = usage_ledger_v1::Ledger::open(&store.root.join("usage-ledger")).unwrap().entries_for_execution(id).unwrap();
            assert_eq!(entries.len(), 1);
            let connection = store.connection().unwrap();
            let outcome = usage_attempt_outcome(&connection, &entries[0]).unwrap();
            assert_eq!(outcome.0.as_deref(), Some(if failed { "FAILED" } else { "COMPLETED" }));
            if failed { assert_eq!(outcome.1.as_deref(), Some("OUTPUT_LIMIT")); assert_eq!(outcome.2, None); }
            else {
                let expected: i64 = connection.query_row("SELECT terminal_at_ms-created_at_ms FROM desktop_ordinary_chat_attempts WHERE attempt_id=?1", [id], |row|row.get(0)).unwrap();
                assert_eq!(outcome.2, Some(expected));assert_ne!(outcome.2, Some(completed.elapsed_ms));
            }
            let mut wrong_leaf = entries[0].clone();wrong_leaf.branch_leaf_message_id = "other-answer".into();
            assert_eq!(usage_attempt_outcome(&connection, &wrong_leaf).unwrap(), (None,None,None));
            let mut wrong_time = entries[0].clone();wrong_time.occurred_at_ms += 1;
            assert_eq!(usage_attempt_outcome(&connection, &wrong_time).unwrap(), (None,None,None));
            let mut imported = entries[0].clone();imported.source = usage_ledger_v1::Source::CrossPlatformImport;
            assert_eq!(usage_attempt_outcome(&connection, &imported).unwrap(), (None,None,None));
        }
    }

    #[test]
    fn reminder_deleted_plan_keeps_usage_outcome_and_recovers_denied_ledger() {
        for failed in [false, true] {
            let (_directory,store,imported)=imported_store();
            let mut connection=store.connection().unwrap();
            let now=1_788_285_000_000;
            let draft=desktop_reminders_v1::create_manual_draft(&connection,&desktop_reminders_v1::ManualDraftArgs {
                workspace_id:imported.summary.id.clone(),conversation_id:None,timezone_id:"Asia/Shanghai".into(),
            },now).unwrap().drafts.remove(0);
            let plan=desktop_reminders_v1::confirm_draft(&mut connection,&desktop_reminders_v1::ConfirmDraftArgs {
                draft_id:draft.draft_id,title:"private-title".into(),instruction:"private-instruction".into(),schedule_kind:"ONCE".into(),
                anchor_local:"2026-09-02T09:00".into(),timezone_id:"Asia/Shanghai".into(),missed_policy:"RUN_ONCE".into(),
            },now+1).unwrap().plans.remove(0);
            let run=desktop_reminders_v1::claim_due(&mut connection,plan.next_run_at_ms.unwrap()).unwrap().unwrap();
            let facts=desktop_reminders_v1::Completion {provider_id:"OPENROUTER",requested_model_id:"fixture",actual_model_id:Some("actual-fixture"),text:"private-result",input_tokens:Some(20),output_tokens:Some(8),cached_input_tokens:Some(2),charge_micros:Some(7)};
            if failed {desktop_reminders_v1::fail_run_reported(&mut connection,&run,"OUTPUT_LIMIT",facts,now+100).unwrap();}
            else {desktop_reminders_v1::complete_run(&connection,&run,facts,now+100).unwrap();}
            drop(usage_ledger_v1::Ledger::open(&store.root.join("usage-ledger")).unwrap());
            let sidecar=Connection::open(store.root.join("usage-ledger/usage-ledger-v1.sqlite3")).unwrap();
            sidecar.execute_batch("CREATE TRIGGER synthetic_denial BEFORE INSERT ON usage_ledger_entries BEGIN SELECT RAISE(ABORT,'synthetic denial'); END;").unwrap();
            store.recover_reminder_accounting().unwrap();
            desktop_reminders_v1::delete_plan(&connection,&plan.plan_id).unwrap();
            sidecar.execute_batch("DROP TRIGGER synthetic_denial;").unwrap();
            store.recover_reminder_accounting().unwrap();
            let ledger=usage_ledger_v1::Ledger::open(&store.root.join("usage-ledger")).unwrap();
            let entries=ledger.entries_for_execution(&plan.plan_id).unwrap();assert_eq!(entries.len(),1);
            let entry=&entries[0];assert_eq!(entry.attempt_id,run.attempt_id);assert_eq!(entry.charge_micros,Some(7));
            assert_eq!(usage_attempt_outcome(&connection,entry).unwrap(),(Some(if failed{"FAILED"}else{"COMPLETED"}.into()),failed.then(||"OUTPUT_LIMIT".into()),None));
            let mut wrong=entry.clone();wrong.conversation_id="unrelated".into();assert_eq!(usage_attempt_outcome(&connection,&wrong).unwrap(),(None,None,None));
            let mut wrong=entry.clone();wrong.charge_micros=Some(8);assert_eq!(usage_attempt_outcome(&connection,&wrong).unwrap(),(None,None,None));
            store.recover_reminder_accounting().unwrap();assert_eq!(ledger.entries_for_execution(&plan.plan_id).unwrap(),entries);
            assert!(desktop_reminders_v1::read_projection(&connection).unwrap().plans.is_empty());
        }
    }

    #[test]
    fn reminder_draft_retry_preserves_unaccounted_attempt_until_ledger_accepts() {
        let (_directory,store,imported)=imported_store();
        let mut exchange=imported.exchange.clone();
        let conversation=&mut exchange["conversations"][0];
        let conversation_id=conversation["id"].as_str().unwrap().to_owned();
        let user_id=conversation["messages"][0]["id"].as_str().unwrap().to_owned();
        let assistant_id=conversation["messages"][1]["id"].as_str().unwrap().to_owned();
        let user_text="明天提醒我核对公开合成材料";
        let assistant_text="合成提醒来源";
        conversation["messages"][0]["blocks"]=json!([{"kind":"TEXT","ordinal":0,"text":user_text}]);
        conversation["messages"][1]["blocks"]=json!([{"kind":"TEXT","ordinal":0,"text":assistant_text}]);
        let mut connection=store.connection().unwrap();
        connection.execute("UPDATE workspace_exchange SET exchange_json=?2 WHERE workspace_id=?1",params![imported.summary.id,exchange.to_string()]).unwrap();
        let reservation=desktop_reminders_v1::reserve_generated_draft(&mut connection,&desktop_reminders_v1::GenerateDraftArgs {
            workspace_id:imported.summary.id.clone(),conversation_id,user_message_id:user_id,assistant_message_id:assistant_id,timezone_id:"UTC".into(),
        },user_text,assistant_text,1_788_285_000_000).unwrap();
        let failed=desktop_reminders_v1::fail_draft_reported(&connection,&reservation.draft_id,"OUTPUT_LIMIT",desktop_reminders_v1::Completion {
            provider_id:"QWEN",requested_model_id:"fixture",actual_model_id:Some("actual-fixture"),text:"synthetic",
            input_tokens:Some(20),output_tokens:Some(8),cached_input_tokens:Some(2),charge_micros:Some(7),
        },1_788_285_000_001).unwrap();
        drop(connection);
        drop(usage_ledger_v1::Ledger::open(&store.root.join("usage-ledger")).unwrap());
        let sidecar=Connection::open(store.root.join("usage-ledger/usage-ledger-v1.sqlite3")).unwrap();
        sidecar.execute_batch("CREATE TRIGGER synthetic_denial BEFORE INSERT ON usage_ledger_entries BEGIN SELECT RAISE(ABORT,'synthetic accounting denial'); END;").unwrap();
        assert!(store.prepare_reminder_draft_retry(&reservation.draft_id,Some("http://127.0.0.1:1/chat/completions")).is_err());
        assert_eq!(desktop_reminders_v1::read_draft(&store.connection().unwrap(),&reservation.draft_id).unwrap(),failed);
        sidecar.execute_batch("DROP TRIGGER synthetic_denial;").unwrap();
        let retry=store.prepare_reminder_draft_retry(&reservation.draft_id,Some("http://127.0.0.1:1/chat/completions")).unwrap();
        assert_ne!(retry.reservation.attempt_id,reservation.attempt_id);
        let entries=usage_ledger_v1::Ledger::open(&store.root.join("usage-ledger")).unwrap().entries_for_execution(&reservation.draft_id).unwrap();
        assert_eq!(entries.len(),1);assert_eq!(entries[0].attempt_id,reservation.attempt_id);
        assert_eq!(entries[0].charge_micros,Some(7));assert_eq!(entries[0].occurred_at_ms,failed.updated_at_ms);
        store.recover_reminder_accounting().unwrap();
        assert_eq!(usage_ledger_v1::Ledger::open(&store.root.join("usage-ledger")).unwrap().entries_for_execution(&reservation.draft_id).unwrap().len(),1);
    }

    #[test]
