    #[test]
    fn reminder_unknown_draft_accounting_recovers_once_without_retry() {
        let (_directory,store,imported)=imported_store();
        let mut exchange=imported.exchange.clone();
        let conversation=&mut exchange["conversations"][0];
        let conversation_id=conversation["id"].as_str().unwrap().to_owned();
        let user_id=conversation["messages"][0]["id"].as_str().unwrap().to_owned();
        let assistant_id=conversation["messages"][1]["id"].as_str().unwrap().to_owned();
        let user_text="明天提醒我核对公开合成材料";
        let assistant_text="合成提醒来源";
        conversation["messages"][0]["blocks"]=json!([{"kind":"TEXT","ordinal":0,"text":user_text}]);
        conversation["messages"][1]["blocks"]=json!([{"kind":"TEXT","ordinal":0,"text":assistant_text}]);
        let mut connection=store.connection().unwrap();
        connection.execute("UPDATE workspace_exchange SET exchange_json=?2 WHERE workspace_id=?1",params![imported.summary.id,exchange.to_string()]).unwrap();
        let reservation=desktop_reminders_v1::reserve_generated_draft(&mut connection,&desktop_reminders_v1::GenerateDraftArgs {
            workspace_id:imported.summary.id.clone(),conversation_id,user_message_id:user_id,assistant_message_id:assistant_id,timezone_id:"UTC".into(),
        },user_text,assistant_text,1_788_285_000_000).unwrap();
        let failed=desktop_reminders_v1::unknown_draft_reported(&connection,&reservation.draft_id,"NETWORK",desktop_reminders_v1::Completion {
            provider_id:"QWEN",requested_model_id:"fixture",actual_model_id:Some("actual-fixture"),text:"synthetic",
            input_tokens:Some(20),output_tokens:Some(8),cached_input_tokens:Some(2),charge_micros:Some(7),
        },1_788_285_000_001).unwrap();
        assert_eq!(failed.status,"UNKNOWN");
        drop(connection);
        drop(usage_ledger_v1::Ledger::open(&store.root.join("usage-ledger")).unwrap());
        let sidecar=Connection::open(store.root.join("usage-ledger/usage-ledger-v1.sqlite3")).unwrap();
        sidecar.execute_batch("CREATE TRIGGER synthetic_denial BEFORE INSERT ON usage_ledger_entries BEGIN SELECT RAISE(ABORT,'synthetic accounting denial'); END;").unwrap();
        store.recover_reminder_accounting().unwrap();
        assert_eq!(desktop_reminders_v1::read_draft(&store.connection().unwrap(),&reservation.draft_id).unwrap(),failed);
        sidecar.execute_batch("DROP TRIGGER synthetic_denial;").unwrap();
        store.recover_reminder_accounting().unwrap();
        let entries=usage_ledger_v1::Ledger::open(&store.root.join("usage-ledger")).unwrap().entries_for_execution(&reservation.draft_id).unwrap();
        assert_eq!(entries.len(),1);assert_eq!(entries[0].attempt_id,reservation.attempt_id);
        assert_eq!(entries[0].charge_micros,Some(7));assert_eq!(entries[0].occurred_at_ms,failed.updated_at_ms);
        store.recover_reminder_accounting().unwrap();
        assert_eq!(usage_ledger_v1::Ledger::open(&store.root.join("usage-ledger")).unwrap().entries_for_execution(&reservation.draft_id).unwrap().len(),1);
    }

    #[test]
    fn history_accounting_cold_recovery_preserves_exact_attempt_without_rereading_source() {
        for unknown in [false,true] {
            let (directory,store,imported)=imported_store();
            let mut exchange=imported.exchange.clone();
            let conversation=&mut exchange["conversations"][0];
            let templates=conversation["messages"].as_array().unwrap().clone();
            let mut messages=Vec::new();
            for index in 0..4 {
                let mut message=templates[index%2].clone();
                message["id"]=json!(format!("synthetic-history-{index}"));
                message["parentId"]=if index==0 {Value::Null}else{json!(format!("synthetic-history-{}",index-1))};
                message["role"]=json!(if index%2==0 {"user"}else{"assistant"});
                message["delivery"]=json!("COMPLETE");
                message["blocks"]=json!([{"kind":"TEXT","ordinal":0,"text":"公开合成历史计量恢复材料。".repeat(80)}]);
                message.as_object_mut().unwrap().remove("attemptId");messages.push(message);
            }
            conversation["messages"]=json!(messages);conversation["currentLeafId"]=json!("synthetic-history-3");
            let mut connection=store.connection().unwrap();
            // imported_store is the legacy44 owner fixture. Add this component's
            // schema explicitly; genuine area58->59 upgrade is tested separately.
            let tx=connection.transaction().unwrap();
            desktop_history_knowledge_v1::migrate_accounting(&tx).unwrap();tx.commit().unwrap();
            connection.execute("UPDATE workspace_exchange SET exchange_json=?2 WHERE workspace_id=?1",params![imported.summary.id,exchange.to_string()]).unwrap();
            desktop_history_knowledge_v1::set_enabled(&connection,true,100).unwrap();
            connection.execute("UPDATE desktop_app_settings SET history_library_enabled=1 WHERE id=1",[]).unwrap();
            let desktop_history_knowledge_v1::Selection::Ready(source)=desktop_history_knowledge_v1::select_next(&connection,101).unwrap() else {panic!("valid synthetic history source required")};
            let run=desktop_history_knowledge_v1::reserve(&mut connection,&source,102).unwrap();
            desktop_history_knowledge_v1::mark_running(&connection,&run.candidate_id,"OPENROUTER","fixture-history",103).unwrap();
            let facts=desktop_history_knowledge_v1::Completion {provider_id:"OPENROUTER",requested_model_id:"fixture-history",actual_model_id:Some("actual-history"),response_text:"",input_tokens:Some(11),output_tokens:Some(7),cached_input_tokens:Some(2),reasoning_tokens:None,charge_micros:Some(9)};
            let original=if unknown {desktop_history_knowledge_v1::unknown_reported(&mut connection,&run.candidate_id,"NETWORK",facts,104).unwrap()}else{desktop_history_knowledge_v1::fail_reported(&mut connection,&run.candidate_id,"RESPONSE_FORMAT",facts,104).unwrap()};
            let sidecar=store.root.join("usage-ledger");usage_ledger_v1::Ledger::open(&sidecar).unwrap();
            let parked=store.root.join("synthetic-history-ledger-parked");std::fs::rename(&sidecar,&parked).unwrap();std::fs::write(&sidecar,b"synthetic ledger unavailable").unwrap();
            let prepared=DesktopHistoryKnowledgePrepared {reservation:run.clone(),endpoint:"http://127.0.0.1:1".into(),provider_id:"OPENROUTER".into(),model_id:"fixture-history".into()};
            let completed=desktop_ordinary_chat_v1::Completed {text:String::new(),reasoning:None,usage:desktop_ordinary_chat_v1::Usage {input_tokens:Some(11),output_tokens:Some(7),cached_input_tokens:Some(2),reasoning_tokens:None},reported_cost_micros:Some(9),actual_model_id:Some("actual-history".into()),web_search_verified:false,native_sources:vec![],elapsed_ms:5};
            assert!(store.complete_history_knowledge_usage(&prepared,&completed).is_err());
            // The old source can change before accounting becomes writable. Never reread it.
            exchange["conversations"][0]["messages"][0]["blocks"][0]["text"]=json!("已修改的公开合成历史材料");
            connection.execute("UPDATE workspace_exchange SET exchange_json=?2 WHERE workspace_id=?1",params![imported.summary.id,exchange.to_string()]).unwrap();
            drop(connection);drop(store);std::fs::remove_file(&sidecar).unwrap();std::fs::rename(&parked,&sidecar).unwrap();
            let root=directory.path().join("app-data");
            for _ in 0..2 {
                let reopened=DesktopWorkspaceStore::open_for_startup(root.clone(),DesktopStartupMode::Normal).unwrap();
                let candidate=desktop_history_knowledge_v1::read_candidate(&reopened.connection().unwrap(),&run.candidate_id).unwrap();assert_eq!(candidate,original);
                let rows=usage_ledger_v1::Ledger::open(&sidecar).unwrap().entries_for_execution(&run.candidate_id).unwrap();assert_eq!(rows.len(),1);
                assert_eq!((&rows[0].attempt_id,&rows[0].branch_leaf_message_id),(&run.attempt_id,&source.current_leaf_message_id));
                assert_eq!((rows[0].input_tokens,rows[0].output_tokens,rows[0].cached_input_tokens,rows[0].charge_micros),(Some(11),Some(7),Some(2),Some(9)));
                assert_eq!(usage_attempt_outcome(&reopened.connection().unwrap(),&rows[0]).unwrap(),(Some(if unknown {"UNKNOWN"}else{"FAILED"}.into()),Some(if unknown {"NETWORK"}else{"RESPONSE_FORMAT"}.into()),None));
                let mut unrelated=rows[0].clone();unrelated.branch_leaf_message_id="different-source-leaf".into();
                assert_eq!(usage_attempt_outcome(&reopened.connection().unwrap(),&unrelated).unwrap(),(None,None,None));
            }
        }
    }

    #[test]
    fn history_accounting_schema59_upgrades_both_reconstructed58_areas_without_rewriting_data() {
        let directory=tempdir().unwrap();
        let legacy=DesktopWorkspaceStore::open(directory.path().join("app-data")).unwrap();
        legacy.ensure_local_workspace().unwrap();
        let connection=legacy.connection().unwrap();
        desktop_data_area::migrate(&connection).unwrap();connection.pragma_update(None,"user_version",45).unwrap();drop(connection);
        desktop_legacy_area_split::migrate(&legacy).unwrap();drop(legacy);
        let root=directory.path().join("app-data");
        let (chat,work)=open_desktop_area_stores_for_startup(root.clone(),DesktopStartupMode::Normal).unwrap();
        let work=work.unwrap();
        for (store,area) in [(&chat,"CHAT"),(&work,"WORK")] {
            let mut c=store.connection().unwrap();
            assert_eq!(c.pragma_query_value(None,"user_version",|r|r.get::<_,u32>(0)).unwrap(),59);
            assert!(desktop_history_knowledge_v1::accounting_receipts(&c).unwrap().is_empty());
            c.execute_batch("DROP TABLE desktop_history_knowledge_accounting_v1; PRAGMA user_version=58; CREATE TABLE synthetic_history_migration_marker(value TEXT NOT NULL); INSERT INTO synthetic_history_migration_marker VALUES('preserve-this-synthetic-value');").unwrap();
            assert!(matches!(desktop_schema_source::classify(&c,58).unwrap(),desktop_schema_source::SchemaSource::Common58 {..}));
            let before:Vec<(String,String)>=c.prepare("SELECT workspace_id,exchange_json FROM workspace_exchange ORDER BY workspace_id").unwrap().query_map([],|r|Ok((r.get(0)?,r.get(1)?))).unwrap().collect::<Result<_,_>>().unwrap();
            desktop_history_knowledge_v1::migrate_accounting_committed_area(&mut c,area).unwrap();
            assert!(desktop_history_knowledge_v1::accounting_schema_valid(&c).unwrap());
            let after:Vec<(String,String)>=c.prepare("SELECT workspace_id,exchange_json FROM workspace_exchange ORDER BY workspace_id").unwrap().query_map([],|r|Ok((r.get(0)?,r.get(1)?))).unwrap().collect::<Result<_,_>>().unwrap();
            assert_eq!(before,after);assert!(desktop_history_knowledge_v1::accounting_receipts(&c).unwrap().is_empty());
            assert_eq!(c.query_row("SELECT value FROM synthetic_history_migration_marker",[],|r|r.get::<_,String>(0)).unwrap(),"preserve-this-synthetic-value");
            desktop_history_knowledge_v1::migrate_accounting_committed_area(&mut c,area).unwrap();
            assert_eq!(c.pragma_query_value(None,"user_version",|r|r.get::<_,u32>(0)).unwrap(),59);
        }
        drop(chat);drop(work);
        let (chat,work)=open_desktop_area_stores_for_startup(root,DesktopStartupMode::Normal).unwrap();
        assert!(desktop_history_knowledge_v1::accounting_schema_valid(&chat.connection().unwrap()).unwrap());
        assert!(desktop_history_knowledge_v1::accounting_schema_valid(&work.unwrap().connection().unwrap()).unwrap());
    }

    #[test]
    fn identity_only_failed_calls_recover_once_with_unknown_quantities_and_original_outcome() {
        for (state,code) in [("FAILED","OUTPUT_LIMIT"),("UNKNOWN","MISSING_COMPLETION"),("CANCELLED","CANCELLED")] {
            let (directory,store,imported)=imported_store();let conversation=imported.exchange["conversations"].as_array().unwrap().first().unwrap();
            let prepared=store.prepare_ordinary_chat(DesktopOrdinaryChatSubmitArgs {workspace_id:imported.summary.id.clone(),conversation_id:conversation["id"].as_str().map(ToOwned::to_owned),project_id:None,expected_revision:conversation["revision"].as_u64(),text:"synthetic identity-only failure".into(),attachment_ids:vec![],model_id:None,tone_override:None,web_search_override:None,egress_authorization:None},Some("http://127.0.0.1:1/chat/completions")).unwrap();
            let id=prepared.projection.attempt_id.clone();
            let reply=desktop_ordinary_chat_v1::Completed {text:String::new(),reasoning:None,usage:Default::default(),reported_cost_micros:None,actual_model_id:Some("openai/gpt-6-luna".into()),web_search_verified:false,elapsed_ms:7,native_sources:vec![]};
            let original=store.update_ordinary_chat_message(&id,"",state,None,Some(&reply),Some(code)).unwrap();assert_eq!(original.actual_model_id,reply.actual_model_id);
            assert!(!ordinary_chat_usage_fallbacks(&store).unwrap().contains_key(&id),"Failed, unknown or stopped provider quantities must not be replaced with local message estimates");
            assert!(usage_ledger_v1::Ledger::open(&store.root.join("usage-ledger")).unwrap().entries_for_execution(&id).unwrap().is_empty());drop(store);
            let root=directory.path().join("app-data");
            for _ in 0..2 {
                let reopened=DesktopWorkspaceStore::open_for_startup(root.clone(),DesktopStartupMode::Normal).unwrap();
                let current=DesktopWorkspaceStore::ordinary_chat_projection(&reopened.connection().unwrap(),&id).unwrap();assert_eq!(current.state,original.state);assert_eq!(current.safe_error_code.as_deref(),Some(code));assert_eq!(current.actual_model_id.as_deref(),Some("openai/gpt-6-luna"));
                let entries=usage_ledger_v1::Ledger::open(&root.join("usage-ledger")).unwrap().entries_for_execution(&id).unwrap();assert_eq!(entries.len(),1,"Recovery must record the known actual identity once even when every quantity is unknown");let row=&entries[0];assert_eq!(row.actual_model_id.as_deref(),Some("openai/gpt-6-luna"));assert_eq!((row.input_tokens,row.output_tokens,row.cached_input_tokens,row.charge_micros),(None,None,None,None));assert_eq!(row.kind,usage_ledger_v1::Kind::FinalMeasured);
                assert_eq!(usage_attempt_outcome(&reopened.connection().unwrap(),row).unwrap().0.as_deref(),Some(original.state.as_str()));
            }
        }
    }

    fn retrieval_progress_test_request(key:&str)->desktop_ordinary_chat_v1::TransportRequest {
        desktop_ordinary_chat_v1::TransportRequest{endpoint:"http://127.0.0.1:1/".into(),provider_id:"OPENROUTER".into(),model_id:"openai/gpt-6.1-sol".into(),messages:json!([]),idempotency_key:key.into(),max_output_tokens:512,web_search_route:"OPENROUTER_SERVER_TOOL".into(),structured_json:false,disable_thinking:false,grounded_answer:false,explicit_search_query:None}
    }
    fn retrieval_progress_test_measurement()->desktop_ordinary_chat_v1::ReportedMeasurement {
        desktop_ordinary_chat_v1::ReportedMeasurement{usage:desktop_ordinary_chat_v1::Usage{input_tokens:Some(17),output_tokens:Some(0),cached_input_tokens:Some(3),reasoning_tokens:None},reported_cost_micros:Some(4),actual_model_id:Some("openai/gpt-6.1-sol".into()),elapsed_ms:8}
    }
    #[test]
    fn retrieval_progress_normal_startup_recovers_child_once_without_parent_measurement() {
        let(directory,store,imported)=imported_store();call_window_test_catalog(&store,8192);let p=call_window_test_prepare(&store,&imported.summary.id);
        let request=retrieval_progress_test_request("synthetic-child-key");store.record_relay_search_usage_for(&p.projection,None,Some(&request.idempotency_key),Some(&request)).unwrap();
        store.checkpoint_retrieval_measurement(&p.projection,&request,&retrieval_progress_test_measurement()).unwrap();
        let ledger=usage_ledger_v1::Ledger::open(&store.root.join("usage-ledger")).unwrap();assert_eq!(ledger.display_entries().unwrap().iter().filter(|e|e.kind==usage_ledger_v1::Kind::FinalMeasured).count(),0);drop(ledger);drop(store);
        let root=directory.path().join("app-data");let mut frozen=None;
        for _ in 0..2 {
            let store=DesktopWorkspaceStore::open_for_startup(root.clone(),DesktopStartupMode::Normal).unwrap();let a=DesktopWorkspaceStore::ordinary_chat_projection(&store.connection().unwrap(),&p.projection.attempt_id).unwrap();
            assert_eq!(a.state,"UNKNOWN");assert_eq!(a.safe_error_code.as_deref(),Some("PROCESS_INTERRUPTED"));assert_eq!((a.input_tokens,a.output_tokens,a.charge_micros,a.actual_model_id),(None,None,None,None));
            let ledger=usage_ledger_v1::Ledger::open(&root.join("usage-ledger")).unwrap();let rows=ledger.display_entries().unwrap().into_iter().filter(|e|e.execution_id==a.attempt_id).collect::<Vec<_>>();assert_eq!(rows.len(),1);
            let e=&rows[0];assert_eq!(e.kind,usage_ledger_v1::Kind::FinalMeasured);assert_eq!((e.input_tokens,e.output_tokens,e.cached_input_tokens,e.charge_micros),(Some(17),Some(0),Some(3),Some(4)));assert_eq!(e.currency_code.as_deref(),Some("USD"));assert!(ledger.retrieval_was_interrupted(e).unwrap());assert_eq!(ledger.call_metadata(&e.entry_id).unwrap().unwrap().role,"RETRIEVAL");
            if let Some(old)=&frozen {assert_eq!(&rows,old);} else {frozen=Some(rows);}
        }
    }
    #[test]
    fn retrieval_progress_recovery_does_not_attribute_an_older_retry_to_the_current_attempt() {
        let(directory,store,imported)=imported_store();call_window_test_catalog(&store,8192);let p=call_window_test_prepare(&store,&imported.summary.id);
        let request=retrieval_progress_test_request("synthetic-old-child");store.record_relay_search_usage_for(&p.projection,None,Some(&request.idempotency_key),Some(&request)).unwrap();store.checkpoint_retrieval_measurement(&p.projection,&request,&retrieval_progress_test_measurement()).unwrap();
        store.connection().unwrap().execute("UPDATE desktop_ordinary_chat_attempts SET retry_count=retry_count+1 WHERE attempt_id=?1",[&p.projection.attempt_id]).unwrap();drop(store);
        let root=directory.path().join("app-data");let store=DesktopWorkspaceStore::open_for_startup(root.clone(),DesktopStartupMode::Normal).unwrap();let a=DesktopWorkspaceStore::ordinary_chat_projection(&store.connection().unwrap(),&p.projection.attempt_id).unwrap();assert_eq!(a.state,"UNKNOWN");assert_eq!(a.input_tokens,None);
        let ledger=usage_ledger_v1::Ledger::open(&root.join("usage-ledger")).unwrap();let rows=ledger.display_entries().unwrap();assert_eq!(rows.len(),1);assert_eq!(rows[0].kind,usage_ledger_v1::Kind::StreamPending);assert_eq!(ledger.retrieval_progress().unwrap()[0].0.input_tokens,Some(17));assert!(!ledger.retrieval_progress().unwrap()[0].2);
    }
    #[test]
    fn retrieval_progress_rejects_stale_parent_unknown_child_and_terminal_callback() {
        let(_directory,store,imported)=imported_store();call_window_test_catalog(&store,8192);let p=call_window_test_prepare(&store,&imported.summary.id);
        let request=retrieval_progress_test_request("synthetic-child-key");let m=retrieval_progress_test_measurement();store.record_relay_search_usage_for(&p.projection,None,Some(&request.idempotency_key),Some(&request)).unwrap();
        let mut wrong=p.projection.clone();wrong.retry_count+=1;assert!(store.checkpoint_retrieval_measurement(&wrong,&request,&m).is_err());
        wrong=p.projection.clone();wrong.assistant_message_id="other-assistant".into();assert!(store.checkpoint_retrieval_measurement(&wrong,&request,&m).is_err());
        let unknown=retrieval_progress_test_request("unknown-child-key");assert!(store.checkpoint_retrieval_measurement(&p.projection,&unknown,&m).is_err());
        assert!(usage_ledger_v1::Ledger::open(&store.root.join("usage-ledger")).unwrap().retrieval_progress().unwrap().is_empty());
        store.update_ordinary_chat_message(&p.projection.attempt_id,"","CANCELLED",None,None,Some("CANCELLED")).unwrap();assert!(store.checkpoint_retrieval_measurement(&p.projection,&request,&m).is_err());
    }
