    #[test]
    fn failed_provider_measurement_replays_once_after_accounting_gap() {
        for code in ["WEB_SEARCH_NO_SOURCES", "WEB_SEARCH_NO_VERIFIED_SOURCES", "WEB_SEARCH_SCOPE_INCOMPLETE", "INCOMPLETE_RESPONSE", "RESPONSE_INCOMPLETE", "PROVIDER_RESPONSE_FAILED",
                     "OUTPUT_LIMIT", "CONTENT_FILTER", "PROVIDER_REFUSAL", "RESPONSE_FORMAT"] {
        let (directory, store, imported) = imported_store();
        let conversation = imported.exchange["conversations"].as_array().unwrap().first().unwrap();
        let prepared = store.prepare_ordinary_chat(
            DesktopOrdinaryChatSubmitArgs {
                workspace_id: imported.summary.id.clone(),
                conversation_id: conversation["id"].as_str().map(ToOwned::to_owned),
                project_id: None,
                expected_revision: conversation["revision"].as_u64(),
                text: "synthetic failed search".into(),
                attachment_ids: vec![], model_id: None, tone_override: None,
                web_search_override: None, egress_authorization: None,
            },
            Some("http://127.0.0.1:1/chat/completions"),
        ).unwrap();
        let attempt_id = prepared.projection.attempt_id.clone();
        let completed = desktop_ordinary_chat_v1::Completed {
            text: String::new(), reasoning: None,
            usage: desktop_ordinary_chat_v1::Usage {
                input_tokens: Some(11), output_tokens: Some(7),
                cached_input_tokens: None, reasoning_tokens: None,
            },
            reported_cost_micros: Some(9),
            actual_model_id: Some("fixture-actual".into()),
            web_search_verified: false, elapsed_ms: 12,

            native_sources: Vec::new(),
        };
        let failed = store.update_ordinary_chat_message(
            &attempt_id, "", "FAILED", None, Some(&completed), Some(code),
        ).unwrap();
        assert_eq!(failed.state, "FAILED");
        assert_eq!(failed.charge_micros, Some(9));
        let ledger = usage_ledger_v1::Ledger::open(&store.root.join("usage-ledger")).unwrap();
        assert!(ledger.entries_for_execution(&attempt_id).unwrap().is_empty());
        drop(ledger);
        drop(store);

        let root = directory.path().join("app-data");
        for _ in 0..2 {
            let reopened = DesktopWorkspaceStore::open_for_startup(root.clone(), DesktopStartupMode::Normal).unwrap();
            let recovered = DesktopWorkspaceStore::ordinary_chat_projection(&reopened.connection().unwrap(), &attempt_id).unwrap();
            assert_eq!(recovered.state, "FAILED");
            assert_eq!(recovered.safe_error_code.as_deref(), Some(code));
            assert_eq!(recovered.charge_micros, Some(9));
            assert_eq!(recovered.web_search_verified, Some(false));
            let entries = usage_ledger_v1::Ledger::open(&root.join("usage-ledger")).unwrap()
                .entries_for_execution(&attempt_id).unwrap();
            assert_eq!(entries.len(), 1);
            assert_eq!(entries[0].charge_micros, Some(9));
            assert_eq!(entries[0].kind, usage_ledger_v1::Kind::FinalMeasured);
            let workspace = reopened.workspace_projection(&imported.summary.id).unwrap();
            let assistant = workspace.exchange["conversations"].as_array().unwrap().iter()
                .flat_map(|conversation| conversation["messages"].as_array().unwrap())
                .find(|message| message["id"].as_str() == Some(prepared.projection.assistant_message_id.as_str()))
                .unwrap();
            assert_eq!(assistant["blocks"][0]["text"], "");
        }
        }
    }

    #[test]
    fn ordinary_chat_http_failure_status_survives_reopen_without_body_or_usage() {
        for (status, code) in [(429, "RATE_LIMIT"), (503, "SERVICE_UNAVAILABLE")] {
            let (directory, store, imported) = imported_store();
            let conversation = imported.exchange["conversations"].as_array().unwrap().first().unwrap();
            let prepared = store.prepare_ordinary_chat(
                DesktopOrdinaryChatSubmitArgs {
                    workspace_id: imported.summary.id.clone(),
                    conversation_id: conversation["id"].as_str().map(ToOwned::to_owned),
                    project_id: None,
                    expected_revision: conversation["revision"].as_u64(),
                    text: "synthetic HTTP failure".into(),
                    attachment_ids: vec![], model_id: None, tone_override: None,
                    web_search_override: None, egress_authorization: None,
                },
                Some("http://127.0.0.1:1/chat/completions"),
            ).unwrap();
            let attempt_id = prepared.projection.attempt_id.clone();
            let failed = store.update_ordinary_chat_message_with_http_status(
                &attempt_id, "", "FAILED", None, None, Some(code), Some(status), None,
            ).unwrap();
            assert_eq!(failed.state, "FAILED");
            assert_eq!(failed.input_tokens, None);
            let diagnostic_status: Option<i64> = store.connection().unwrap().query_row(
                "SELECT http_status FROM desktop_ordinary_chat_diagnostics WHERE attempt_id=?1",
                [&attempt_id], |row| row.get(0),
            ).unwrap();
            assert_eq!(diagnostic_status, Some(i64::from(status)));
            drop(store);
            let reopened = DesktopWorkspaceStore::open_for_startup(
                directory.path().join("app-data"), DesktopStartupMode::Normal,
            ).unwrap();
            let reopened_status: Option<i64> = reopened.connection().unwrap().query_row(
                "SELECT http_status FROM desktop_ordinary_chat_diagnostics WHERE attempt_id=?1",
                [&attempt_id], |row| row.get(0),
            ).unwrap();
            assert_eq!(reopened_status, Some(i64::from(status)));
        }
    }

    #[test]
    fn ordinary_chat_same_text_creates_independent_attempts_and_persists_stream_completion() {
        let (_directory, store, imported) = imported_store();
        let conversation = imported.exchange["conversations"]
            .as_array()
            .unwrap()
            .first()
            .unwrap();
        let conversation_id = conversation["id"].as_str().unwrap().to_owned();
        let first = store
            .prepare_ordinary_chat(
                DesktopOrdinaryChatSubmitArgs {
                    workspace_id: imported.summary.id.clone(),
                    conversation_id: Some(conversation_id.clone()),
                    project_id: None,
                    expected_revision: conversation["revision"].as_u64(),
                    text: "same text".into(),
                    attachment_ids: vec![],
                    model_id: None,
                    tone_override: None,
                    web_search_override: None,
                    egress_authorization: None,
                },
                Some("http://127.0.0.1:1/chat/completions"),
            )
            .unwrap();
        // Sequential user sends remain distinct; an unfinished reservation is
        // intentionally rejected by the ordinary-chat transaction owner.
        store.update_ordinary_chat_message(&first.projection.attempt_id,
            "first completed answer", "COMPLETE", None, None, None).unwrap();
        let after_first = store.workspace_projection(&imported.summary.id).unwrap();
        let revision = after_first.exchange["conversations"]
            .as_array()
            .unwrap()
            .iter()
            .find(|item| item["id"] == conversation_id)
            .unwrap()["revision"]
            .as_u64();
        let second = store
            .prepare_ordinary_chat(
                DesktopOrdinaryChatSubmitArgs {
                    workspace_id: imported.summary.id.clone(),
                    conversation_id: Some(conversation_id.clone()),
                    project_id: None,
                    expected_revision: revision,
                    text: "same text".into(),
                    attachment_ids: vec![],
                    model_id: None,
                    tone_override: None,
                    web_search_override: None,
                    egress_authorization: None,
                },
                Some("http://127.0.0.1:1/chat/completions"),
            )
            .unwrap();
        assert_ne!(first.projection.attempt_id, second.projection.attempt_id);
        assert_ne!(
            first.projection.user_message_id,
            second.projection.user_message_id
        );
        // Another local owner can hold a reserved write lock. A streamed checkpoint must
        // wait for it rather than failing a deferred read-to-write lock upgrade.
        let database = store.database.clone();
        let (ready_tx, ready_rx) = std::sync::mpsc::channel();
        let writer = std::thread::spawn(move || {
            let mut connection = Connection::open(database).unwrap();
            let transaction = connection
                .transaction_with_behavior(rusqlite::TransactionBehavior::Immediate)
                .unwrap();
            ready_tx.send(()).unwrap();
            std::thread::sleep(std::time::Duration::from_millis(200));
            transaction.commit().unwrap();
        });
        ready_rx.recv().unwrap();
        store
            .update_ordinary_chat_message(
                &second.projection.attempt_id,
                "streamed",
                "PARTIAL",
                None,
                None,
                None,
            )
            .unwrap();
        writer.join().unwrap();
        let completed = desktop_ordinary_chat_v1::Completed {
            text: "streamed answer".into(),
            reasoning: Some("retained after completion".into()),
            usage: desktop_ordinary_chat_v1::Usage {
                input_tokens: Some(4),
                output_tokens: Some(3),
                cached_input_tokens: Some(1),
                reasoning_tokens: Some(1),
            },
            reported_cost_micros: Some(8),
            actual_model_id: Some("fixture-actual".into()),
            web_search_verified: false,
            elapsed_ms: 12,

            native_sources: Vec::new(),
        };
        store
            .update_ordinary_chat_message(
                &second.projection.attempt_id,
                &completed.text,
                "COMPLETE",
                completed.reasoning.as_deref(),
                Some(&completed),
                None,
            )
            .unwrap();
        let final_attempt = store
            .complete_ordinary_chat_accounting(&second.projection.attempt_id, &completed)
            .unwrap();
        assert_eq!(final_attempt.state, "COMPLETED");
        assert_eq!(final_attempt.charge_micros, Some(8));
        let unread = desktop_conversation_read_state_v1::read_projection(
            &mut store.connection().unwrap(),
            &imported.summary.id,
            None,
            system_now_millis(),
        )
        .unwrap();
        assert!(unread
            .conversations
            .iter()
            .any(|item| item.conversation_id == conversation_id && item.unread));
        let opened = desktop_conversation_read_state_v1::mark_opened(
            &mut store.connection().unwrap(),
            &imported.summary.id,
            &conversation_id,
            system_now_millis(),
        )
        .unwrap();
        assert!(opened
            .conversations
            .iter()
            .all(|item| item.conversation_id != conversation_id || !item.unread));
        let missing_usage = desktop_ordinary_chat_v1::Completed {
            text: "provider omitted usage".into(),
            reasoning: None,
            usage: desktop_ordinary_chat_v1::Usage::default(),
            reported_cost_micros: None,
            actual_model_id: Some("openai/gpt-5.6-terra".into()),
            web_search_verified: false,
            elapsed_ms: 2_300,

            native_sources: Vec::new(),
        };
        store
            .update_ordinary_chat_message(
                &first.projection.attempt_id,
                &missing_usage.text,
                "COMPLETE",
                None,
                Some(&missing_usage),
                None,
            )
            .unwrap();
        let projected = store.workspace_projection(&imported.summary.id).unwrap();
        let estimated_message = projected.exchange["conversations"]
            .as_array()
            .unwrap()
            .iter()
            .flat_map(|conversation| conversation["messages"].as_array().unwrap())
            .find(|message| message["id"] == first.projection.assistant_message_id)
            .unwrap();
        assert!(
            estimated_message["estimatedUsage"]["inputTokens"]
                .as_i64()
                .unwrap()
                > 0
        );
        assert!(
            estimated_message["estimatedUsage"]["outputTokens"]
                .as_i64()
                .unwrap()
                > 0
        );
        let shared_fallbacks = ordinary_chat_usage_fallbacks(&store).unwrap();
        let shared_usage = shared_fallbacks
            .get(&first.projection.attempt_id)
            .copied()
            .unwrap();
        assert_eq!(
            shared_usage.0,
            estimated_message["estimatedUsage"]["inputTokens"]
                .as_i64()
                .unwrap()
        );
        assert_eq!(
            shared_usage.1,
            estimated_message["estimatedUsage"]["outputTokens"]
                .as_i64()
                .unwrap()
        );
        assert_eq!(estimated_message["run"]["durationMs"], 2_300);
        let reopened = DesktopWorkspaceStore::open(store.root.clone()).unwrap();
        assert_eq!(
            reopened
                .latest_ordinary_chat_attempt(&imported.summary.id, &conversation_id)
                .unwrap()
                .unwrap()
                .state,
            "COMPLETED"
        );
    }

    #[test]
    fn explicit_memory_command_and_answer_commit_or_roll_back_together() {
        let (directory, store, imported) = imported_store();
        let conversation = imported.exchange["conversations"].as_array().unwrap().first().unwrap();
        let prepared = store.prepare_ordinary_chat(DesktopOrdinaryChatSubmitArgs {
            workspace_id: imported.summary.id.clone(),
            conversation_id: conversation["id"].as_str().map(ToOwned::to_owned),
            project_id: None, expected_revision: conversation["revision"].as_u64(),
            text: "记住了：我长期关注跨端开发与数据保全".into(),
            attachment_ids: vec![], model_id: None, tone_override: None,
            web_search_override: None, egress_authorization: None,
        }, Some("http://127.0.0.1:1/chat/completions")).unwrap();
        let draft = desktop_memory_summary_v1::parse_model_summary(
            "【记忆主题】工作流程偏好\n【记忆摘要】长期关注跨端开发与数据保全。",
        ).unwrap();
        let completed = desktop_ordinary_chat_v1::Completed {
            text: "synthetic structured response".into(), reasoning: Some("synthetic secret reasoning".into()),
            usage: desktop_ordinary_chat_v1::Usage {
                input_tokens: Some(12), output_tokens: Some(8),
                cached_input_tokens: None, reasoning_tokens: None,
            },
            reported_cost_micros: Some(5), actual_model_id: Some("fixture-actual".into()),
            web_search_verified: false, elapsed_ms: 15,

            native_sources: Vec::new(),
        };
        store.connection().unwrap().execute_batch(
            "CREATE TRIGGER synthetic_fail_memory_answer BEFORE UPDATE ON desktop_ordinary_chat_attempts
             WHEN NEW.state='RESPONSE_COMMITTED' BEGIN SELECT RAISE(FAIL,'synthetic answer failure'); END;",
        ).unwrap();
        assert!(store.complete_ordinary_memory_command(&prepared.projection.attempt_id, &completed, &draft).is_err());
        let after_failure = store.workspace_projection(&imported.summary.id).unwrap().exchange;
        assert!(after_failure["memory"].as_array().unwrap().iter().all(|item| item["body"] != draft.body));
        assert_eq!(store.connection().unwrap().query_row(
            "SELECT COUNT(*) FROM domain_intents WHERE intent_id=?1",
            [format!("memory-command-{}", prepared.projection.attempt_id)],
            |row| row.get::<_, i64>(0),
        ).unwrap(), 0);
        assert_eq!(DesktopWorkspaceStore::ordinary_chat_projection(
            &store.connection().unwrap(), &prepared.projection.attempt_id,
        ).unwrap().state, "PENDING");
        store.connection().unwrap().execute_batch("DROP TRIGGER synthetic_fail_memory_answer").unwrap();
        store.complete_ordinary_memory_command(&prepared.projection.attempt_id, &completed, &draft).unwrap();
        drop(store);
        let reopened = DesktopWorkspaceStore::open_for_startup(
            directory.path().join("app-data"), DesktopStartupMode::Normal,
        ).unwrap();
        let exchange = reopened.workspace_projection(&imported.summary.id).unwrap().exchange;
        assert_eq!(exchange["memory"].as_array().unwrap().iter().filter(|item| item["body"] == draft.body).count(), 1);
        assert_eq!(exchange["memory"].as_array().unwrap().iter()
            .find(|item| item["body"] == draft.body).unwrap()["title"], draft.title);
        let assistant = exchange["conversations"].as_array().unwrap().iter()
            .flat_map(|item| item["messages"].as_array().unwrap())
            .find(|item| item["id"] == prepared.projection.assistant_message_id).unwrap();
        assert_eq!(assistant["delivery"], "COMPLETE");
        assert!(assistant.to_string().contains("已更新记忆摘要"));
        assert!(!assistant.to_string().contains("synthetic secret reasoning"));
        reopened.connection().unwrap().execute_batch(
            "ALTER TABLE desktop_app_settings ADD COLUMN memory_retrieval_enabled INTEGER NOT NULL DEFAULT 1;",
        ).unwrap();
        let current = exchange["conversations"].as_array().unwrap().iter()
            .find(|item| item["id"] == prepared.projection.conversation_id).unwrap();
        let pending = reopened.prepare_ordinary_chat(DesktopOrdinaryChatSubmitArgs {
            workspace_id: imported.summary.id.clone(),
            conversation_id: Some(prepared.projection.conversation_id.clone()),
            project_id: None, expected_revision: current["revision"].as_u64(),
            text: "记住了：这个新的偏好只用于合成测试".into(),
            attachment_ids: vec![], model_id: None, tone_override: None,
            web_search_override: None, egress_authorization: None,
        }, Some("http://127.0.0.1:1/chat/completions")).unwrap();
        assert!(pending.memory_command);
        reopened.connection().unwrap().execute(
            "UPDATE desktop_app_settings SET memory_enabled=0,memory_retrieval_enabled=1 WHERE id=1", [],
        ).unwrap();
        let later_draft = desktop_memory_summary_v1::Draft {
            title: "测试".into(), body: "关闭后不能写入的合成偏好".into(),
        };
        reopened.complete_ordinary_memory_command(&pending.projection.attempt_id, &completed, &later_draft).unwrap();
        let after_disabled = reopened.workspace_projection(&imported.summary.id).unwrap().exchange;
        assert!(after_disabled["memory"].as_array().unwrap().iter().all(|item| item["body"] != later_draft.body));
        let disabled_answer = after_disabled["conversations"].as_array().unwrap().iter()
            .flat_map(|item| item["messages"].as_array().unwrap())
            .find(|item| item["id"] == pending.projection.assistant_message_id).unwrap();
        assert!(disabled_answer.to_string().contains("没有写入"));
    }

    #[test]
    fn pending_memory_topic_resolution_preserves_old_revision_until_chosen() {
        let initial = json!({"memory":[
            {"id":"memory-existing","title":"工作流程偏好","body":"旧正文","scope":"GLOBAL","scopeId":null,"status":"ACTIVE","revision":1,"contentHash":sha256("旧正文".as_bytes())},
            {"id":"memory-candidate","title":"工作流程偏好","body":"新正文","scope":"GLOBAL","scopeId":null,"status":"PENDING_REVIEW","revision":1,"contentHash":sha256("新正文".as_bytes())}
        ]});
        let args = |resolution: &str, expected: u64| DomainMutationArgs {
            intent_id: format!("resolve-{}", resolution.to_ascii_lowercase()), workspace_id: "workspace-test".into(),
            entity: "memory".into(), action: "resolvePendingMemoryTopic".into(),
            object_id: Some("memory-candidate".into()), expected_revision: Some(1),
            fields: json!({"resolution":resolution,"existingId": if resolution == "REVISE_EXISTING" { Some("memory-existing") } else { None },
                "expectedEntries":[{"id":"memory-existing","revision":expected}]}),
        };
        let mut stale = initial.clone();
        assert!(apply_domain_mutation(&mut stale, &args("REVISE_EXISTING", 0)).is_err());
        assert_eq!(stale, initial);
        let mut revised = initial.clone();
        apply_domain_mutation(&mut revised, &args("REVISE_EXISTING", 1)).unwrap();
        assert_eq!(revised["memory"][0]["body"], "新正文");
        assert_eq!(revised["memory"][0]["revision"], 2);
        assert_eq!(revised["memory"][1]["status"], "DELETED");
        let mut kept = initial.clone();
        apply_domain_mutation(&mut kept, &args("KEEP_EXISTING", 1)).unwrap();
        assert_eq!(kept["memory"][0], initial["memory"][0]);
        assert_eq!(kept["memory"][1]["status"], "DELETED");
        let mut parallel = initial.clone();
        apply_domain_mutation(&mut parallel, &args("CREATE_PARALLEL", 1)).unwrap();
        assert_eq!(parallel["memory"][0], initial["memory"][0]);
        assert_eq!(parallel["memory"][1]["status"], "ACTIVE");
    }

    #[test]
    fn explicit_memory_command_uses_the_retrieval_gate_and_persists_once() {
        let (directory, store, imported) = imported_store();
        let conversation = imported.exchange["conversations"].as_array().unwrap().first().unwrap();
        let prepared = store.prepare_ordinary_chat(
            DesktopOrdinaryChatSubmitArgs {
                workspace_id: imported.summary.id.clone(),
                conversation_id: conversation["id"].as_str().map(ToOwned::to_owned),
                project_id: None,
                expected_revision: conversation["revision"].as_u64(),
                text: "记住了：我长期关注跨端开发与数据保全".into(),
                attachment_ids: vec![], model_id: None, tone_override: None,
                web_search_override: None, egress_authorization: None,
            },
            Some("http://127.0.0.1:1/chat/completions"),
        ).unwrap();
        assert!(prepared.memory_command);
        assert!(prepared.messages.to_string().contains("【记忆主题】"));
        let draft = desktop_memory_summary_v1::parse_model_summary(
            "【记忆主题】工作流程偏好\n【记忆摘要】长期关注跨端开发与数据保全。",
        ).unwrap();
        let completed = desktop_ordinary_chat_v1::Completed {
            text: "synthetic structured response".into(), reasoning: None,
            usage: desktop_ordinary_chat_v1::Usage::default(),
            reported_cost_micros: None, actual_model_id: Some("fixture-actual".into()),
            web_search_verified: false, elapsed_ms: 1,

            native_sources: Vec::new(),
        };
        store.complete_ordinary_memory_command(&prepared.projection.attempt_id, &completed, &draft).unwrap();
        let memory_intent_state: i64 = store.connection().unwrap().query_row(
            "SELECT undone FROM domain_intents WHERE intent_id=?1",
            [format!("memory-command-{}", prepared.projection.attempt_id)],
            |row| row.get(0),
        ).unwrap();
        assert_eq!(memory_intent_state, 1, "automatic memory write must stay outside undo");
        let workspace = store.workspace_projection(&imported.summary.id).unwrap();
        assert_eq!(workspace.exchange["memory"].as_array().unwrap().iter()
            .filter(|item| item["body"] == draft.body).count(), 1);
        assert_eq!(workspace.exchange["memory"].as_array().unwrap().iter()
            .find(|item| item["body"] == draft.body).unwrap()["title"], draft.title);
        let current = workspace.exchange["conversations"].as_array().unwrap().iter()
            .find(|item| item["id"] == prepared.projection.conversation_id).unwrap();
        let duplicate = store.prepare_ordinary_chat(DesktopOrdinaryChatSubmitArgs {
            workspace_id: imported.summary.id.clone(),
            conversation_id: Some(prepared.projection.conversation_id.clone()),
            project_id: None, expected_revision: current["revision"].as_u64(),
            text: "记住了：这条长期关注的合成偏好再次出现".into(),
            attachment_ids: vec![], model_id: None, tone_override: None,
            web_search_override: None, egress_authorization: None,
        }, Some("http://127.0.0.1:1/chat/completions")).unwrap();
        store.complete_ordinary_memory_command(&duplicate.projection.attempt_id, &completed, &draft).unwrap();
        let after_duplicate = store.workspace_projection(&imported.summary.id).unwrap().exchange;
        assert_eq!(after_duplicate["memory"].as_array().unwrap().iter()
            .filter(|item| item["body"] == draft.body).count(), 1);
        let duplicate_answer = after_duplicate["conversations"].as_array().unwrap().iter()
            .flat_map(|item| item["messages"].as_array().unwrap())
            .find(|item| item["id"] == duplicate.projection.assistant_message_id).unwrap();
        assert!(duplicate_answer.to_string().contains("无需重复保存"));
        let original_memory = after_duplicate["memory"].as_array().unwrap().iter()
            .find(|item| item["body"] == draft.body).unwrap().clone();
        let current = after_duplicate["conversations"].as_array().unwrap().iter()
            .find(|item| item["id"] == duplicate.projection.conversation_id).unwrap();
        let parallel = store.prepare_ordinary_chat(DesktopOrdinaryChatSubmitArgs {
            workspace_id: imported.summary.id.clone(),
            conversation_id: Some(duplicate.projection.conversation_id.clone()),
            project_id: None, expected_revision: current["revision"].as_u64(),
            text: "记住了：我也长期关注跨端产品的可访问性".into(),
            attachment_ids: vec![], model_id: None, tone_override: None,
            web_search_override: None, egress_authorization: None,
        }, Some("http://127.0.0.1:1/chat/completions")).unwrap();
        let parallel_draft = desktop_memory_summary_v1::Draft {
            title: draft.title.clone(), body: "长期关注跨端产品的可访问性。".into(),
        };
        store.complete_ordinary_memory_command(&parallel.projection.attempt_id, &completed, &parallel_draft).unwrap();
        let after_parallel = store.workspace_projection(&imported.summary.id).unwrap().exchange;
        assert_eq!(after_parallel["memory"].as_array().unwrap().iter()
            .find(|item| item["id"] == original_memory["id"]).unwrap(), &original_memory);
        assert_eq!(after_parallel["memory"].as_array().unwrap().iter()
            .filter(|item| item["body"] == parallel_draft.body).count(), 1);
        let parallel_answer = after_parallel["conversations"].as_array().unwrap().iter()
            .flat_map(|item| item["messages"].as_array().unwrap())
            .find(|item| item["id"] == parallel.projection.assistant_message_id).unwrap();
        assert!(parallel_answer.to_string().contains("已生成同主题记忆候选"));
        let candidate = after_parallel["memory"].as_array().unwrap().iter()
            .find(|item| item["body"] == parallel_draft.body).unwrap();
        assert_eq!(candidate["status"], "PENDING_REVIEW");
        assert_eq!(parallel_answer["memoryTopicReviewCandidateId"], candidate["id"]);
        let current = after_parallel["conversations"].as_array().unwrap().iter()
            .find(|item| item["id"] == parallel.projection.conversation_id).unwrap();
        let repeated = store.prepare_ordinary_chat(DesktopOrdinaryChatSubmitArgs {
            workspace_id: imported.summary.id.clone(),
            conversation_id: Some(parallel.projection.conversation_id.clone()),
            project_id: None, expected_revision: current["revision"].as_u64(),
            text: "记住了：再次记住相同的跨端可访问性偏好".into(),
            attachment_ids: vec![], model_id: None, tone_override: None,
            web_search_override: None, egress_authorization: None,
        }, Some("http://127.0.0.1:1/chat/completions")).unwrap();
        store.complete_ordinary_memory_command(&repeated.projection.attempt_id, &completed, &parallel_draft).unwrap();
        let after_repeated = store.workspace_projection(&imported.summary.id).unwrap().exchange;
        assert_eq!(after_repeated["memory"].as_array().unwrap().iter()
            .filter(|item| item["body"] == parallel_draft.body).count(), 1);
        assert!(after_repeated["conversations"].as_array().unwrap().iter()
            .flat_map(|item| item["messages"].as_array().unwrap())
            .find(|item| item["id"] == repeated.projection.assistant_message_id).unwrap()
            .to_string().contains("本次未重复写入"));
        let receipt = store.mutate_domain(DomainMutationArgs {
            intent_id: "resolve-explicit-memory-candidate".into(),
            workspace_id: imported.summary.id.clone(), entity: "memory".into(),
            action: "resolvePendingMemoryTopic".into(),
            object_id: candidate["id"].as_str().map(ToOwned::to_owned),
            expected_revision: candidate["revision"].as_u64(),
            fields: json!({"resolution":"CREATE_PARALLEL","expectedEntries":[{"id":original_memory["id"],"revision":original_memory["revision"]}]}),
        }).unwrap();
        assert_eq!(receipt.revision, 2);
        store.connection().unwrap().execute_batch(
            "ALTER TABLE desktop_app_settings ADD COLUMN memory_retrieval_enabled INTEGER NOT NULL DEFAULT 1;
             UPDATE desktop_app_settings SET memory_enabled=1,memory_retrieval_enabled=0 WHERE id=1;",
        ).unwrap();
        let (_, _, _, enabled) = store.ordinary_chat_request_messages(
            &store.connection().unwrap(), &workspace.exchange, &imported.summary.id,
            &prepared.projection.conversation_id, &prepared.projection.assistant_message_id,
            "OPENROUTER", "openai/gpt-5.6-terra",
        ).unwrap();
        assert!(!enabled);
        store.connection().unwrap().execute(
            "UPDATE desktop_app_settings SET memory_enabled=0,memory_retrieval_enabled=1 WHERE id=1", [],
        ).unwrap();
        let (_, _, _, enabled) = store.ordinary_chat_request_messages(
            &store.connection().unwrap(), &workspace.exchange, &imported.summary.id,
            &prepared.projection.conversation_id, &prepared.projection.assistant_message_id,
            "OPENROUTER", "openai/gpt-5.6-terra",
        ).unwrap();
        assert!(!enabled);
        drop(store);
        let reopened = DesktopWorkspaceStore::open_for_startup(
            directory.path().join("app-data"), DesktopStartupMode::Normal,
        ).unwrap();
        assert_eq!(reopened.workspace_projection(&imported.summary.id).unwrap().exchange["memory"]
            .as_array().unwrap().iter().filter(|item| item["body"] == draft.body).count(), 1);
        assert_eq!(reopened.workspace_projection(&imported.summary.id).unwrap().exchange["memory"]
            .as_array().unwrap().iter().filter(|item| item["body"] == parallel_draft.body).count(), 1);
        let memory = reopened.workspace_projection(&imported.summary.id).unwrap().exchange["memory"]
            .as_array().unwrap().iter().find(|item| item["body"] == draft.body).unwrap().clone();
        reopened.mutate_domain(DomainMutationArgs {
            intent_id: "delete-command-memory".into(),
            workspace_id: imported.summary.id.clone(),
            entity: "memory".into(), action: "softDelete".into(),
            object_id: memory["id"].as_str().map(ToOwned::to_owned),
            expected_revision: memory["revision"].as_u64(), fields: json!({}),
        }).unwrap();
        reopened.apply_history(HistoryArgs {
            intent_id: "undo-delete-command-memory".into(),
            workspace_id: imported.summary.id.clone(),
        }, false).unwrap();
        assert!(reopened.workspace_projection(&imported.summary.id).unwrap().exchange["memory"]
            .as_array().unwrap().iter().any(|item| item["body"] == draft.body && item["status"] == "ACTIVE"));
        reopened.apply_history(HistoryArgs {
            intent_id: "undo-send-after-memory-command".into(),
            workspace_id: imported.summary.id.clone(),
        }, false).unwrap();
        assert_eq!(reopened.workspace_projection(&imported.summary.id).unwrap().exchange["memory"]
            .as_array().unwrap().iter().filter(|item| item["body"] == draft.body).count(), 1);
    }

