    #[test]
    fn qwen_responses_alignment_prepares_max_and_complete_text_material() {
        for (preset, model, attachment, web) in [
            ("QWEN_3_8_MAX", "qwen3.8-max", false, true),
            ("QWEN_3_8_MAX", "qwen3.8-max", false, false),
            ("QWEN_3_7_PLUS", "qwen3.7-plus", true, true),
            ("QWEN_3_8_MAX", "qwen3.8-max", true, true),
            ("QWEN_3_7_PLUS", "qwen3.7-plus", true, false),
        ] {
            let (directory, store, imported) = imported_store();
            let material = format!("{}QWEN_MATERIAL_LAST_LINE", "完整合成材料🙂\n".repeat(1000));
            let attachment_ids = if attachment {
                let path = directory.path().join("qwen-material.txt");
                fs::write(&path, &material).unwrap();
                vec![store.import_conversation_attachment(DesktopAttachmentImportArgs {
                    workspace_id: imported.summary.id.clone(), selected_path: path.to_string_lossy().into_owned(),
                }).unwrap().id]
            } else { vec![] };
            let prepared = store.prepare_ordinary_chat(DesktopOrdinaryChatSubmitArgs {
                workspace_id: imported.summary.id, conversation_id: None, project_id: None,
                expected_revision: None, text: "按本次联网开关处理合成公开材料".into(), attachment_ids,
                model_id: Some(preset.into()), tone_override: None, web_search_override: Some(web), egress_authorization: None,
            }, Some("http://127.0.0.1:1/chat/completions")).unwrap();
            assert_eq!(prepared.provider_id, "QWEN");
            assert_eq!(prepared.model_id, model);
            assert_eq!(prepared.web_search_route, if web {"QWEN_RESPONSES"} else {"NONE"}, "{preset} attachment={attachment}");
            assert_eq!(prepared.max_output_tokens, if preset == "QWEN_3_8_MAX" {16384} else {65536});
            if attachment {
                let parts: Vec<&str> = prepared.messages.as_array().unwrap().iter()
                    .flat_map(|m| m["content"].as_array().into_iter().flatten()).filter_map(|p| p["text"].as_str()).collect();
                assert_eq!(parts.iter().filter(|p| p.contains(&material)).count(), 1);
            }
        }
    }

    #[test]
    fn qwen_responses_alignment_legacy_chat_retry_keeps_its_protocol_and_key() {
        for preset in ["QWEN_3_7_PLUS", "QWEN_3_8_MAX"] {
            let (directory, store, imported) = imported_store();
            let path = directory.path().join("legacy-qwen.txt");
            fs::write(&path, "LEGACY_QWEN_ORIGINAL_MATERIAL").unwrap();
            let attachment = store.import_conversation_attachment(DesktopAttachmentImportArgs {
                workspace_id: imported.summary.id.clone(), selected_path: path.to_string_lossy().into_owned(),
            }).unwrap();
            let endpoint = Some("http://127.0.0.1:1/chat/completions");
            let first = store.prepare_ordinary_chat(DesktopOrdinaryChatSubmitArgs {
                workspace_id: imported.summary.id, conversation_id: None, project_id: None,
                expected_revision: None, text: "旧请求合成问题".into(), attachment_ids: vec![attachment.id],
                model_id: Some(preset.into()), tone_override: None, web_search_override: Some(true), egress_authorization: None,
            }, endpoint).unwrap();
            store.update_ordinary_chat_message(&first.projection.attempt_id, "", "FAILED", None, None, Some("NETWORK")).unwrap();
            // The saved protocol column is the pre-alignment writer's durable fact.
            store.connection().unwrap().execute("UPDATE desktop_ordinary_chat_attempts SET web_search_route='QWEN_CHAT_COMPLETIONS' WHERE attempt_id=?1", [&first.projection.attempt_id]).unwrap();
            let root=store.root.clone();drop(store);
            let reopened=DesktopWorkspaceStore::open(root).unwrap();
            let preview=reopened.preview_ordinary_chat_retry(&first.projection.attempt_id, endpoint).unwrap();
            let authorization=DesktopOrdinaryChatEgressAuthorization {
                approved_at_ms:1, disclosure_version:"normal-chat-egress-v2".into(), client_submission_id:Some(format!("legacy-qwen-{preset}")),
                draft_fingerprint:Some(preview.draft_fingerprint), recipient_choice_id:Some(preview.recipient_choice_id),
                recipient_provider_id:Some(preview.recipient_provider_id), recipient_model_id:Some(preview.recipient_model_id), retrieval_recipient:None, attachment_reading:None,
            };
            let retry=reopened.prepare_ordinary_chat_retry_with_authorization(&first.projection.attempt_id,endpoint,Some(&authorization)).unwrap();
            assert_eq!(retry.web_search_route,"QWEN_CHAT_COMPLETIONS");
            assert_eq!(retry.idempotency_key,first.idempotency_key);
            assert_eq!(retry.projection.attempt_id,first.projection.attempt_id);
            assert!(retry.messages.to_string().contains("LEGACY_QWEN_ORIGINAL_MATERIAL"));
        }
    }

