    #[test]
    fn ordinary_retry_v2_binds_failed_leaf_and_original_recipient_before_mutation() {
        let (_directory, store, imported) = imported_store();
        let endpoint = Some("http://127.0.0.1:1/chat/completions");
        let prepared = store.prepare_ordinary_chat(DesktopOrdinaryChatSubmitArgs {
            workspace_id: imported.summary.id.clone(), conversation_id: None, project_id: None,
            expected_revision: None, text: "合成重试授权问题".into(), attachment_ids: vec![],
            model_id: None, tone_override: None, web_search_override: Some(false),
            egress_authorization: None,
        }, endpoint).unwrap();
        let attempt_id = &prepared.projection.attempt_id;
        store.update_ordinary_chat_message(attempt_id, "", "FAILED", None, None, Some("NETWORK")).unwrap();
        let preview = store.preview_ordinary_chat_retry(attempt_id, endpoint).unwrap();
        assert_eq!(preview.recipient_choice_id, "RETRY_ORIGINAL");
        let mut authorization = DesktopOrdinaryChatEgressAuthorization {
            approved_at_ms: 1, disclosure_version: "normal-chat-egress-v2".into(),
            client_submission_id: Some("client-retry-v2-001".into()),
            draft_fingerprint: Some("stale".into()),
            recipient_choice_id: Some(preview.recipient_choice_id.clone()),
            recipient_provider_id: Some(preview.recipient_provider_id.clone()),
            recipient_model_id: Some(preview.recipient_model_id.clone()),
         retrieval_recipient: None, attachment_reading: None };
        assert!(store.prepare_ordinary_chat_retry_with_authorization(attempt_id, endpoint, Some(&authorization))
            .unwrap_err().contains("重试来源或接收方已变化"));
        assert_eq!(DesktopWorkspaceStore::ordinary_chat_projection(&store.connection().unwrap(), attempt_id).unwrap().retry_count, 0);
        authorization.draft_fingerprint = Some(preview.draft_fingerprint);
        let retried = store.prepare_ordinary_chat_retry_with_authorization(attempt_id, endpoint, Some(&authorization)).unwrap();
        assert_eq!(retried.idempotency_key, prepared.idempotency_key);
        assert_eq!(retried.provider_id, preview.recipient_provider_id);
        assert_eq!(retried.model_id, preview.recipient_model_id);
        assert_eq!(retried.projection.retry_count, 1);
        let disclosure: String = store.connection().unwrap().query_row(
            "SELECT egress_disclosure_version FROM desktop_ordinary_chat_attempts WHERE attempt_id=?1",
            [attempt_id], |row| row.get(0),
        ).unwrap();
        assert_eq!(disclosure, "normal-chat-egress-v2");
        assert!(store.preview_ordinary_chat_retry(attempt_id, endpoint).is_err());
    }


    #[test]
    fn defaultstyle_new_draft_choice_survives_reopen_without_renewing_text_expiry() {
        let (directory, store, imported) = imported_store();
        let args = |tone: &str| DesktopConversationDraftArgs {
            workspace_id: imported.summary.id.clone(), conversation_id: None,
            text: "synthetic retained text".into(), attachment_ids: vec![], model_id: None,
            tone_override: Some(tone.into()), web_search_override: Some(false),
        };
        let first = store.save_conversation_draft(args("professional")).unwrap().unwrap();
        let changed = store.save_conversation_draft(args("default")).unwrap().unwrap();
        assert_eq!(changed.tone_override.as_deref(), Some("default"));
        assert_eq!(first.expires_at_ms, changed.expires_at_ms);
        assert_eq!(first.text, changed.text);
        drop(store);
        let reopened = DesktopWorkspaceStore::open(directory.path().join("app-data")).unwrap();
        let recovered = reopened.read_conversation_draft(&imported.summary.id, None).unwrap().unwrap();
        assert_eq!(recovered.tone_override.as_deref(), Some("default"));
        assert_eq!(changed.expires_at_ms, recovered.expires_at_ms);
        assert_eq!(changed.text, recovered.text);
    }

