    #[test]
    fn new_conversation_text_expires_at_one_hour_without_losing_choices_or_attachments() {
        let (_directory, store, imported) = imported_store();
        let workspace_id = imported.summary.id;
        let attachment = store.import_conversation_attachment_bytes(
            &workspace_id, b"draft attachment".to_vec(), Some("txt"), "draft.txt",
        ).unwrap();
        let text = " \n保留  ";
        store.save_conversation_draft(DesktopConversationDraftArgs {
            workspace_id: workspace_id.clone(), conversation_id: None, text: text.into(),
            attachment_ids: vec![attachment.id.clone()],
            model_id: Some("DEEPSEEK_V4_PRO".into()),
            tone_override: Some("professional".into()), web_search_override: Some(false),
        }).unwrap();
        let edited_at: i64 = store.connection().unwrap().query_row(
            "SELECT updated_at_ms FROM desktop_conversation_drafts_v1 WHERE workspace_id=?1 AND conversation_key=?2",
            params![workspace_id, NEW_CONVERSATION_DRAFT_KEY], |row| row.get(0),
        ).unwrap();
        // Changing only model/style/search or reading the draft does not extend the text's life.
        store.save_conversation_draft(DesktopConversationDraftArgs {
            workspace_id: workspace_id.clone(), conversation_id: None, text: text.into(),
            attachment_ids: vec![attachment.id.clone()], model_id: Some("GLM_5_3".into()),
            tone_override: Some("friendly".into()), web_search_override: Some(false),
        }).unwrap();
        let before_expiry = store.read_conversation_draft_at(
            &workspace_id, None, edited_at + NEW_CONVERSATION_DRAFT_TTL_MS - 1,
        ).unwrap().unwrap();
        assert_eq!(before_expiry.text, text);
        assert_eq!(before_expiry.expires_at_ms, Some(edited_at + NEW_CONVERSATION_DRAFT_TTL_MS));
        assert_eq!(store.connection().unwrap().query_row(
            "SELECT updated_at_ms FROM desktop_conversation_drafts_v1 WHERE workspace_id=?1 AND conversation_key=?2",
            params![workspace_id, NEW_CONVERSATION_DRAFT_KEY], |row| row.get::<_, i64>(0),
        ).unwrap(), edited_at);

        let expired = store.read_conversation_draft_at(
            &workspace_id, None, edited_at + NEW_CONVERSATION_DRAFT_TTL_MS,
        ).unwrap().unwrap();
        assert_eq!(expired.text, "");
        assert_eq!(expired.expires_at_ms, None);
        assert_eq!(expired.attachments[0].id, attachment.id);
        assert_eq!(expired.model_id.as_deref(), Some("GLM_5_3"));
        assert_eq!(expired.tone_override.as_deref(), Some("friendly"));
        assert_eq!(expired.web_search_override, Some(false));
        assert_eq!(store.read_conversation_draft_at(
            &workspace_id, None, edited_at + NEW_CONVERSATION_DRAFT_TTL_MS + 1,
        ).unwrap().unwrap().text, "");

        store.connection().unwrap().execute(
            "UPDATE desktop_conversation_drafts_v1 SET updated_at_ms=?3 WHERE workspace_id=?1 AND conversation_key=?2",
            params![workspace_id, NEW_CONVERSATION_DRAFT_KEY, system_now_millis() - 30 * 60 * 1_000],
        ).unwrap();
        let stale_time: i64 = store.connection().unwrap().query_row(
            "SELECT updated_at_ms FROM desktop_conversation_drafts_v1 WHERE workspace_id=?1 AND conversation_key=?2",
            params![workspace_id, NEW_CONVERSATION_DRAFT_KEY], |row| row.get(0),
        ).unwrap();
        store.save_conversation_draft(DesktopConversationDraftArgs {
            workspace_id: workspace_id.clone(), conversation_id: None,
            text: "重新编辑".into(), attachment_ids: vec![attachment.id.clone()],
            model_id: Some("GLM_5_3".into()), tone_override: Some("friendly".into()),
            web_search_override: Some(false),
        }).unwrap();
        let renewed = store.read_conversation_draft_at(
            &workspace_id, None, stale_time + NEW_CONVERSATION_DRAFT_TTL_MS,
        ).unwrap().unwrap();
        assert_eq!(renewed.text, "重新编辑");
        assert!(renewed.expires_at_ms.unwrap() > stale_time + NEW_CONVERSATION_DRAFT_TTL_MS);
        store.connection().unwrap().execute(
            "UPDATE desktop_conversation_drafts_v1 SET updated_at_ms=?3 WHERE workspace_id=?1 AND conversation_key=?2",
            params![workspace_id, NEW_CONVERSATION_DRAFT_KEY, system_now_millis() - NEW_CONVERSATION_DRAFT_TTL_MS - 1],
        ).unwrap();
        let choice_after_expiry = store.save_conversation_draft(DesktopConversationDraftArgs {
            workspace_id: workspace_id.clone(), conversation_id: None,
            text: "重新编辑".into(), attachment_ids: vec![attachment.id.clone()],
            model_id: Some("DEEPSEEK_V4_PRO".into()), tone_override: Some("friendly".into()),
            web_search_override: Some(false),
        }).unwrap().unwrap();
        assert_eq!(choice_after_expiry.text, "");
        assert_eq!(choice_after_expiry.model_id.as_deref(), Some("DEEPSEEK_V4_PRO"));
        assert_eq!(choice_after_expiry.attachments[0].id, attachment.id);
        store.save_conversation_draft(DesktopConversationDraftArgs {
            workspace_id: workspace_id.clone(), conversation_id: None,
            text: "".into(), attachment_ids: vec![attachment.id.clone()],
            model_id: Some("GLM_5_3".into()), tone_override: Some("friendly".into()),
            web_search_override: Some(false),
        }).unwrap();
        assert_eq!(store.read_conversation_draft(&workspace_id, None).unwrap().unwrap().text, "");

        store.save_conversation_draft(DesktopConversationDraftArgs {
            workspace_id: workspace_id.clone(), conversation_id: Some("conversation-existing".into()),
            text: "existing continuation".into(), attachment_ids: vec![],
            model_id: None, tone_override: None, web_search_override: None,
        }).unwrap();
        assert_eq!(store.read_conversation_draft_at(
            &workspace_id, Some("conversation-existing"), edited_at + 2 * NEW_CONVERSATION_DRAFT_TTL_MS,
        ).unwrap().unwrap().text, "existing continuation");
    }

