    #[test]
    fn local_workspace_bootstrap_saves_first_draft_without_import_or_fake_conversation() {
        let directory = tempdir().unwrap();
        let root = directory.path().join("app-data");
        let store = DesktopWorkspaceStore::open(root.clone()).unwrap();
        assert!(store.list_workspaces().unwrap().is_empty());
        let workspace = store.ensure_local_workspace().unwrap();
        for collection in [
            "projects",
            "conversations",
            "knowledge",
            "memory",
            "relations",
        ] {
            assert!(workspace.exchange[collection]
                .as_array()
                .unwrap()
                .is_empty());
        }
        assert_eq!(
            workspace.exchange["export"]["origin"]["platform"],
            "DESKTOP"
        );
        validate_exchange(&workspace.exchange).unwrap();
        let journal: i64 = store
            .connection()
            .unwrap()
            .query_row("SELECT COUNT(*) FROM import_journal", [], |row| row.get(0))
            .unwrap();
        assert_eq!(journal, 0, "local initialization is not an import");
        assert_eq!(
            store.ensure_local_workspace().unwrap().summary.id,
            workspace.summary.id
        );
        store
            .save_conversation_draft(DesktopConversationDraftArgs {
                workspace_id: workspace.summary.id.clone(),
                conversation_id: None,
                text: "空库首稿：中文、空格 与标点。".into(),
                attachment_ids: vec![],
                model_id: None,
                tone_override: None,
                web_search_override: None,
            })
            .unwrap();
        drop(store);
        let reopened = DesktopWorkspaceStore::open(root).unwrap();
        assert_eq!(
            reopened.ensure_local_workspace().unwrap().summary.id,
            workspace.summary.id
        );
        assert_eq!(reopened.list_workspaces().unwrap().len(), 1);
        assert_eq!(
            reopened
                .read_conversation_draft(&workspace.summary.id, None)
                .unwrap()
                .unwrap()
                .text,
            "空库首稿：中文、空格 与标点。"
        );
        let exported = directory.path().join("local.nfai-exchange");
        reopened
            .export_workspace_to_path(&workspace.summary.id, exported.to_str().unwrap())
            .unwrap();
        let checked = preflight_package(fs::read(exported).unwrap()).unwrap();
        assert!(checked.exchange["conversations"]
            .as_array()
            .unwrap()
            .is_empty());
    }

