    #[test]
    fn local_workspace_bootstrap_is_idempotent_across_concurrent_connections() {
        let directory = tempdir().unwrap();
        let root = directory.path().join("app-data");
        let first = DesktopWorkspaceStore::open(root.clone()).unwrap();
        let second = DesktopWorkspaceStore::open(root.clone()).unwrap();
        let barrier = std::sync::Arc::new(std::sync::Barrier::new(2));
        let other_barrier = barrier.clone();
        let one = std::thread::spawn(move || {
            barrier.wait();
            first.ensure_local_workspace().unwrap().summary.id
        });
        let two = std::thread::spawn(move || {
            other_barrier.wait();
            second.ensure_local_workspace().unwrap().summary.id
        });
        assert_eq!(one.join().unwrap(), two.join().unwrap());
        assert_eq!(
            DesktopWorkspaceStore::open(root)
                .unwrap()
                .list_workspaces()
                .unwrap()
                .len(),
            1
        );
    }

